INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25534, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ca2cfbf-e3e8-48b8-b2c2-e98554d74ffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25534, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "空气里有好多水，感觉湿湿的。", "primary_collocate": null, "pronunciation": "gāo shī", "ipa": "kaʊ˥ ʂɨ˥", "syllable_count": 2, "sentences": [{"text": "雨后的空气很高湿，皮肤黏黏的。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高湿的天气里，我总觉得身上湿湿的。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间高湿，墙上都是水珠。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的海边高湿，出门一会儿就出汗。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高湿的早晨，草地上全是水。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天高湿，洗的衣服一直不干。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在高湿的地方住久了，被子会有味道。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高湿的山里，树上长满了青苔。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浴室里高湿，镜子上全是雾。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高湿天，地板总是滑滑的。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高湿度", "label": "复合"}, {"form": "高濕", "label": "繁体"}], "register": "口语", "sense_fingerprint": "空气里水很多，身体感觉湿湿黏黏的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86516c74-f999-42cd-9d96-f0f7c57cd30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25534, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高湿", "is_correct": true, "explanation": "正确：高湿（gāo shī）指空气里水很多，人会感觉湿湿黏黏的。"}, {"text": "高士", "is_correct": false, "explanation": "gāo 不变，shì 与 shī 只差声调（第四声与第一声），意思是高尚的人。"}, {"text": "告示", "is_correct": false, "explanation": "gào 与 gāo 声调不同，shì 与 shī 声调不同，意思是告示。"}, {"text": "考试", "is_correct": false, "explanation": "kǎo 与 gāo 声母不同（k 与 g），shì 与 shī 声调不同，意思是考试。"}], "explanations": {"高湿": "正确：高湿（gāo shī）指空气里水很多，人会感觉湿湿黏黏的。", "高士": "gāo 不变，shì 与 shī 只差声调（第四声与第一声），意思是高尚的人。", "告示": "gào 与 gāo 声调不同，shì 与 shī 声调不同，意思是告示。", "考试": "kǎo 与 gāo 声母不同（k 与 g），shì 与 shī 声调不同，意思是考试。"}, "sentence_index": null, "correct_answer": "高湿"}, "level_3": {"options": [{"text": "高湿", "is_correct": true, "explanation": "正确：高湿描述空气里水多，与“皮肤黏黏的”的感受一致。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：后句说“皮肤黏黏的”，干燥的空气不会让皮肤黏。"}, {"text": "稀薄", "is_correct": false, "explanation": "搭配：“稀薄”指空气稀少，不用来形容雨后空气，与“皮肤黏黏的”也不相关。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：寒冷的空气与“皮肤黏黏的”这一前句感受无关，语境不合。"}], "explanations": {"高湿": "正确：高湿描述空气里水多，与“皮肤黏黏的”的感受一致。", "干燥": "语义：后句说“皮肤黏黏的”，干燥的空气不会让皮肤黏。", "稀薄": "搭配：“稀薄”指空气稀少，不用来形容雨后空气，与“皮肤黏黏的”也不相关。", "寒冷": "语义：寒冷的空气与“皮肤黏黏的”这一前句感受无关，语境不合。"}, "sentence_index": 0, "correct_answer": "高湿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很高湿，晾了一天还没干。", "explanation": "这里应该用〈潮湿〉。高湿只描述空气的湿度，衣服沾了水要说〈潮湿〉。"}, {"text": "她哭了很久，眼睛很高湿。", "explanation": "这里应该用〈湿润〉。高湿不用来形容眼睛，眼睛里的水汽要说〈湿润〉。"}, {"text": "他的头发很高湿，还在滴水。", "explanation": "这里应该用〈湿漉漉〉。高湿指空气的湿度，头发沾水要说〈湿漉漉〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ca2cfbf-e3e8-48b8-b2c2-e98554d74ffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25534, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "高湿", "is_correct": true, "explanation": "正确：高湿（gāo shī）指空气里水很多，湿度很高。"}, {"text": "干湿", "is_correct": false, "explanation": "gān 与 gāo 韵母不同（an 与 ao），shī 不变，意思是干和湿。"}, {"text": "高枝", "is_correct": false, "explanation": "zhī 与 shī 声母不同（zh 与 sh），gāo 不变，意思是高处的树枝。"}, {"text": "好似", "is_correct": false, "explanation": "hǎo 与 gāo 声调不同，sì 与 shī 声母和声调都不同，意思是好像。"}, {"text": "干事", "is_correct": false, "explanation": "gàn 与 gāo 韵母和声调不同，shì 与 shī 声调不同，意思是工作人员。"}], "explanations": {"高湿": "正确：高湿（gāo shī）指空气里水很多，湿度很高。", "干湿": "gān 与 gāo 韵母不同（an 与 ao），shī 不变，意思是干和湿。", "高枝": "zhī 与 shī 声母不同（zh 与 sh），gāo 不变，意思是高处的树枝。", "好似": "hǎo 与 gāo 声调不同，sì 与 shī 声母和声调都不同，意思是好像。", "干事": "gàn 与 gāo 韵母和声调不同，shì 与 shī 声调不同，意思是工作人员。"}, "sentence_index": null, "correct_answer": "高湿"}, "level_3": {"options": [{"text": "高湿", "is_correct": true, "explanation": "正确：在高湿的地方住久了，被子会有味道，语义通顺。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：干燥的地方不会让被子有味道，与前后语义矛盾。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容表面质感，不说地方粗糙，也不会让被子有味道。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：明亮的地方与被子有味道没有因果关系，语境不合。"}], "explanations": {"高湿": "正确：在高湿的地方住久了，被子会有味道，语义通顺。", "干燥": "语义：干燥的地方不会让被子有味道，与前后语义矛盾。", "粗糙": "搭配：“粗糙”形容表面质感，不说地方粗糙，也不会让被子有味道。", "明亮": "语义：明亮的地方与被子有味道没有因果关系，语境不合。"}, "sentence_index": 6, "correct_answer": "高湿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯咖啡很高湿，喝起来很甜。", "explanation": "这里应该用〈浓〉。高湿只描述空气或环境的湿度，不用来形容饮料的浓淡。"}, {"text": "他今天高湿得很，一句话也不说。", "explanation": "这里应该用〈闷〉。高湿只指空气或环境的湿度，形容人的情绪和状态要用〈闷〉。"}, {"text": "这座山很高湿，我们爬了很久。", "explanation": "这里应该用〈高大〉。高湿指湿度大，不指高度；说山很高要用〈高大〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ca2cfbf-e3e8-48b8-b2c2-e98554d74ffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天的仓库被高湿，要常开门通风。", "corrected_sentence": "夏天的仓库高湿，要常开门通风。", "error_description": "错误：“被高湿”。正确：“高湿”。“被”字句要求后面接动词，不能直接接形容词“高湿”；“高湿”作谓语时前面不加“被”，直接说“仓库高湿”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ca2cfbf-e3e8-48b8-b2c2-e98554d74ffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个仓库高湿地，粮食容易坏。", "corrected_sentence": "这个仓库高湿，粮食容易坏。", "error_description": "错误：“高湿地”。正确：“高湿”。“地”是状语标记，用在形容词修饰动词时；这里“高湿”作谓语，直接说“仓库高湿”即可，不加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ca2cfbf-e3e8-48b8-b2c2-e98554d74ffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
