INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "淀粉是藏在土豆、米饭里的白色粉末，能让汤变稠。", "primary_collocate": null, "pronunciation": "diàn fěn", "ipa": "tjɛn˥˩ fən˨˩˦", "syllable_count": 2, "sentences": [{"text": "土豆里有很多淀粉。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师在汤里加了一勺淀粉，汤就变稠了。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先用冷水把淀粉调开，再倒进锅里。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "淀粉是白色的粉末，摸起来很滑。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃太多含淀粉的食物，容易变胖。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在肉里放了点淀粉，炒出来更嫩。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包、面条和米饭都有很多淀粉。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗米的水发白，是因为里面有淀粉。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗汤太稀了，再加点淀粉吧。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一袋淀粉准备做炸鸡。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "土豆淀粉", "label": "复合"}, {"form": "一袋淀粉", "label": "量词"}, {"form": "一勺淀粉", "label": "量词"}], "register": "中性", "sense_fingerprint": "厨房里常用的白色粉末，土豆米饭里有，可让汤变稠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86516c74-f999-42cd-9d96-f0f7c57cd30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25542, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "淀粉", "is_correct": true, "explanation": "正确答案：淀粉（diàn fěn），指土豆、米饭里的白色粉末，能让汤变稠。"}, {"text": "淡粉", "is_correct": false, "explanation": "dàn 与 diàn 韵母不同（an 与 ian），意思是浅粉色。"}, {"text": "面粉", "is_correct": false, "explanation": "miàn 与 diàn 声母不同（m 与 d），意思是小麦磨成的面粉。"}, {"text": "蛋粉", "is_correct": false, "explanation": "dàn 与 diàn 韵母不同（an 与 ian），意思是鸡蛋磨成的粉。"}], "explanations": {"淀粉": "正确答案：淀粉（diàn fěn），指土豆、米饭里的白色粉末，能让汤变稠。", "淡粉": "dàn 与 diàn 韵母不同（an 与 ian），意思是浅粉色。", "面粉": "miàn 与 diàn 声母不同（m 与 d），意思是小麦磨成的面粉。", "蛋粉": "dàn 与 diàn 韵母不同（an 与 ian），意思是鸡蛋磨成的粉。"}, "sentence_index": null, "correct_answer": "淀粉"}, "level_3": {"options": [{"text": "淀粉", "is_correct": true, "explanation": "正确答案：淀粉。土豆里含有大量淀粉，这是土豆的主要成分之一。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是土豆的成分，句子与事实不符。"}, {"text": "煤炭", "is_correct": false, "explanation": "语义：煤炭是燃料，土豆里不会含有很多煤炭。"}, {"text": "汽油", "is_correct": false, "explanation": "搭配：“汽油”属于燃料，不能用来说土豆里有很多，与“土豆里”搭配不当。"}], "explanations": {"淀粉": "正确答案：淀粉。土豆里含有大量淀粉，这是土豆的主要成分之一。", "石头": "语义：石头不是土豆的成分，句子与事实不符。", "煤炭": "语义：煤炭是燃料，土豆里不会含有很多煤炭。", "汽油": "搭配：“汽油”属于燃料，不能用来说土豆里有很多，与“土豆里”搭配不当。"}, "sentence_index": 0, "correct_answer": "淀粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这锅汤太淡了，我又多放了一勺淀粉调味。", "explanation": "这里应该用〈盐〉。淀粉没有咸味，调味要用盐；淀粉的作用是让汤变稠。"}, {"text": "他买了一颗淀粉准备做炸鸡。", "explanation": "这里应该用〈袋〉。淀粉是粉末，成袋出售，不能用“颗”来计量。"}, {"text": "早上他习惯喝一杯淀粉。", "explanation": "这里应该用〈茶〉。淀粉不能当饮料喝，早上喝的饮品要用茶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ca2cfbf-e3e8-48b8-b2c2-e98554d74ffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25542, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "淀粉", "is_correct": true, "explanation": "正确答案：淀粉（diàn fěn），指土豆、米饭里的白色粉末，能让汤变稠。"}, {"text": "垫付", "is_correct": false, "explanation": "第二音节 fù 与 fěn 声调和韵母都不同，意思是先替别人垫钱付款。"}, {"text": "米粉", "is_correct": false, "explanation": "第一音节声母与声调不同（m 与 d，第三声与第四声），意思是用大米做成的粉条。"}, {"text": "电费", "is_correct": false, "explanation": "fèi（第四声）与 fěn（第三声）韵母不同（ei 与 en），意思是用电的费用。"}], "explanations": {"淀粉": "正确答案：淀粉（diàn fěn），指土豆、米饭里的白色粉末，能让汤变稠。", "垫付": "第二音节 fù 与 fěn 声调和韵母都不同，意思是先替别人垫钱付款。", "米粉": "第一音节声母与声调不同（m 与 d，第三声与第四声），意思是用大米做成的粉条。", "电费": "fèi（第四声）与 fěn（第三声）韵母不同（ei 与 en），意思是用电的费用。"}, "sentence_index": null, "correct_answer": "淀粉"}, "level_3": {"options": [{"text": "淀粉", "is_correct": true, "explanation": "正确答案：淀粉。面包、面条和米饭的主要成分都是淀粉。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：面包、面条和米饭是食物，不含塑料，句意不通。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁不是食物的成分，与“面包、面条和米饭”的说法不符。"}, {"text": "沥青", "is_correct": false, "explanation": "搭配：“沥青”是道路材料，不能用“很多”来说食物里的含量。"}], "explanations": {"淀粉": "正确答案：淀粉。面包、面条和米饭的主要成分都是淀粉。", "塑料": "语义：面包、面条和米饭是食物，不含塑料，句意不通。", "钢铁": "语义：钢铁不是食物的成分，与“面包、面条和米饭”的说法不符。", "沥青": "搭配：“沥青”是道路材料，不能用“很多”来说食物里的含量。"}, "sentence_index": 6, "correct_answer": "淀粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去加油站加了五十升淀粉。", "explanation": "这里应该用〈汽油〉。淀粉不能当燃料，加油站加的是汽油。"}, {"text": "他用淀粉把手洗干净了。", "explanation": "这里应该用〈香皂〉。淀粉没有去污作用，洗手要用香皂。"}, {"text": "他每天往眼睛里滴两次淀粉。", "explanation": "这里应该用〈眼药水〉。淀粉不能滴入眼睛，滴眼要用眼药水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ca2cfbf-e3e8-48b8-b2c2-e98554d74ffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这锅汤有点稀，加一个淀粉就能变稠。", "corrected_sentence": "这锅汤有点稀，加一勺淀粉就能变稠。", "error_description": "量词用错：淀粉按勺计量，应说“一勺淀粉”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ca2cfbf-e3e8-48b8-b2c2-e98554d74ffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汤太稀的时候，可以加的一点淀粉。", "corrected_sentence": "汤太稀的时候，可以加一点淀粉。", "error_description": "结构助词错误：动词“加”后不能直接接“的”，应说“加一点淀粉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ca2cfbf-e3e8-48b8-b2c2-e98554d74ffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
