INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25546, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做研究的人。", "primary_collocate": null, "pronunciation": "yán jiū zhě", "ipa": "jɛn˧˥ tɕjoʊ˥ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "研究者正在看显微镜。", "target_word": "研究者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是一位年轻的研究者。", "target_word": "研究者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家医院有很多研究者。", "target_word": "研究者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究者每天都要做实验。", "target_word": "研究者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位研究者在写一篇论文。", "target_word": "研究者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我姐姐是研究者，她研究植物。", "target_word": "研究者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究者找到了新的数据。", "target_word": "研究者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些研究者来自不同的国家。", "target_word": "研究者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究者跟学生一起讨论问题。", "target_word": "研究者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想成为一名研究者，帮助病人。", "target_word": "研究者", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位研究者", "label": "量词"}, {"form": "一名研究者", "label": "量词"}, {"form": "研究者们", "label": "复数"}], "register": "中性", "sense_fingerprint": "做研究的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82b7b2-23d4-4ad6-a0b8-5954ca1e3faa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25546, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究者", "is_correct": true, "explanation": "正确：研究者指做研究的人，会用显微镜观察，与句意相符。"}, {"text": "裁缝", "is_correct": false, "explanation": "语义：裁缝做衣服，不看显微镜。"}, {"text": "售货员", "is_correct": false, "explanation": "语义：售货员在商店卖东西，与看显微镜无关。"}, {"text": "驾驶员", "is_correct": false, "explanation": "搭配：「驾驶员」一般驾车，与「看显微镜」不搭配。"}], "explanations": {"研究者": "正确：研究者指做研究的人，会用显微镜观察，与句意相符。", "裁缝": "语义：裁缝做衣服，不看显微镜。", "售货员": "语义：售货员在商店卖东西，与看显微镜无关。", "驾驶员": "搭配：「驾驶员」一般驾车，与「看显微镜」不搭配。"}, "sentence_index": 0, "correct_answer": "研究者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妹妹是研究者，每天在医院照顾病人。", "explanation": "这里应该用〈护士〉。研究者指做研究的人，不负责照顾病人。"}, {"text": "这栋楼是研究者，有十二层高。", "explanation": "这里应该用〈大楼〉。研究者指人，不能指建筑物。"}, {"text": "我弟弟是研究者，每天在超市收银。", "explanation": "这里应该用〈收银员〉。研究者指做研究的人，不负责收银。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25546, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究者", "is_correct": true, "explanation": "正确：研究者指做研究的人，找到新数据与其工作相符。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：园丁负责照料植物，不负责找数据。"}, {"text": "邮递员", "is_correct": false, "explanation": "语义：邮递员负责送信，与找到新的数据无关。"}, {"text": "花", "is_correct": false, "explanation": "搭配：「找到」的主语须是人，「花」不能找到数据。"}], "explanations": {"研究者": "正确：研究者指做研究的人，找到新数据与其工作相符。", "园丁": "语义：园丁负责照料植物，不负责找数据。", "邮递员": "语义：邮递员负责送信，与找到新的数据无关。", "花": "搭配：「找到」的主语须是人，「花」不能找到数据。"}, "sentence_index": 6, "correct_answer": "研究者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我表姐是研究者，每天开公交车。", "explanation": "这里应该用〈司机〉。研究者指做研究的人，不负责开公交车。"}, {"text": "那只猫是研究者，每天在实验室里工作。", "explanation": "这里应该用〈实验动物〉。研究者指人，不能用来称呼动物。"}, {"text": "那位研究者每天在银行窗口给客户办理存款。", "explanation": "这里应该用〈银行职员〉。研究者指做研究的人，不在银行窗口办理存款业务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只研究者找到了原因。", "corrected_sentence": "这位研究者找到了原因。", "error_description": "错误在量词：「只」用于动物，不用于人，应说「这位研究者」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几只研究者来到了实验室。", "corrected_sentence": "几位研究者来到了实验室。", "error_description": "错误在量词：「只」用于动物，不用于人，应说「几位研究者」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
