INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25548, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西有更多的用处。", "primary_collocate": null, "pronunciation": "gōng néng huà", "ipa": "kʊŋ˥ nɤŋ˧˥ xu̯a˥˩", "syllable_count": 3, "sentences": [{"text": "设计师想让这张桌子功能化，多放些东西。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把小房间功能化，既能睡觉又能工作。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架功能化以后，还能当桌子用。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种椅子功能化了，下面可以放书。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把旧衣服功能化，做成有用的包。", "target_word": "功能化", "complexity_tier": "T3", "furigana": "gōng néng huà", "sentence_source": "generated"}, {"text": "老师让孩子把废盒子功能化。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房功能化后，东西更好找。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师把手表功能化，加了不少新用处。", "target_word": "功能化", "complexity_tier": "T3", "furigana": "gōng néng huà", "sentence_source": "generated"}, {"text": "他们没有功能化这个房间。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要先功能化，再卖给客人。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "功能化了", "label": "体标"}, {"form": "功能化后", "label": "短语"}, {"form": "功能化设计", "label": "复合词"}], "register": "通用", "sense_fingerprint": "让东西多出用处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5af2ec-2319-44fd-ab0e-6a7a7c95acf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "功能化", "is_correct": true, "explanation": "正确。“让桌子功能化”指使桌子增加用途，与后文“多放些东西”照应。"}, {"text": "粗糙化", "is_correct": false, "explanation": "语义：“粗糙化”指变得粗糙，与“多放些东西”的目的无关，也不是增加用途。"}, {"text": "大众化", "is_correct": false, "explanation": "语义：“大众化”指使普及、面向大众，不能用来说桌子的用途，句子不通。"}, {"text": "学术化", "is_correct": false, "explanation": "语域：“学术化”偏向学术、书面语境，用在这张普通桌子上很不自然，也与“多放些东西”不搭。"}], "explanations": {"功能化": "正确。“让桌子功能化”指使桌子增加用途，与后文“多放些东西”照应。", "粗糙化": "语义：“粗糙化”指变得粗糙，与“多放些东西”的目的无关，也不是增加用途。", "大众化": "语义：“大众化”指使普及、面向大众，不能用来说桌子的用途，句子不通。", "学术化": "语域：“学术化”偏向学术、书面语境，用在这张普通桌子上很不自然，也与“多放些东西”不搭。"}, "sentence_index": 0, "correct_answer": "功能化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们把客厅功能化得很漂亮。", "explanation": "这里应该用〈美化〉。美化指使外观更好看，功能化指增加用途，与“很漂亮”的外观评价不符。"}, {"text": "我们功能化了一顿丰盛的晚餐。", "explanation": "这里应该用〈享用〉。享用指享受并使用，功能化指给东西增添用途，晚餐不能功能化。"}, {"text": "妈妈把孩子功能化得很可爱。", "explanation": "这里应该用〈打扮〉。打扮指修饰外表，功能化说的是给事物增加用途，只能用于物品，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "功能化", "is_correct": true, "explanation": "正确。“厨房功能化后”指厨房增加了用途，所以东西更好找，前后意思一致。"}, {"text": "腐朽化", "is_correct": false, "explanation": "语义：“腐朽化”指腐烂衰败，与“东西更好找”的积极结果冲突，厨房不会变得腐朽。"}, {"text": "神圣化", "is_correct": false, "explanation": "搭配：“神圣化”指赋予神圣地位，不搭配厨房的实用改造，“厨房神圣化”不通。"}, {"text": "口语化", "is_correct": false, "explanation": "语义：“口语化”指变得通俗、口语化，与厨房的空间改造无关，放在这里句子不通。"}], "explanations": {"功能化": "正确。“厨房功能化后”指厨房增加了用途，所以东西更好找，前后意思一致。", "腐朽化": "语义：“腐朽化”指腐烂衰败，与“东西更好找”的积极结果冲突，厨房不会变得腐朽。", "神圣化": "搭配：“神圣化”指赋予神圣地位，不搭配厨房的实用改造，“厨房神圣化”不通。", "口语化": "语义：“口语化”指变得通俗、口语化，与厨房的空间改造无关，放在这里句子不通。"}, "sentence_index": 6, "correct_answer": "功能化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议要功能化，请大家准时出席。", "explanation": "这里应该用〈召开〉。召开指组织会议，功能化指给事物增添用途，会议不能功能化。"}, {"text": "他把客人功能化得很周到。", "explanation": "这里应该用〈接待〉。接待指招待客人，功能化指增加用途，不能用来说对待客人的方式。"}, {"text": "他把地板功能化得很干净。", "explanation": "这里应该用〈清洁〉。清洁指弄干净，功能化指增加用途，与“很干净”的结果不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把房间功能化很好。", "corrected_sentence": "他把房间功能化得很好。", "error_description": "错误形式是“功能化很好”，正确形式是“功能化得很好”。“功能化”后面带表示程度的补语时，要在中间加“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把旧衣柜功能化了过，现在能放鞋子。", "corrected_sentence": "我们把旧衣柜功能化过，现在能放鞋子。", "error_description": "错误形式是“功能化了过”，“了”和“过”不能同时用在同一个动词后，应只用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
