INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25550, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25550, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "物质或器件受光照后性质会发生变化的。", "primary_collocate": null, "pronunciation": "guāng mǐn", "ipa": "kwɑŋ˥ min˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种纸很光敏。", "target_word": "光敏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "光敏的东西怕阳光。", "target_word": "光敏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶药光敏，要放在柜子里。", "target_word": "光敏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光敏的颜料见光会变色。", "target_word": "光敏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说这种材料很光敏。", "target_word": "光敏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块布光敏，晒后颜色变了。", "target_word": "光敏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种光敏的小灯天黑就会自动亮。", "target_word": "光敏", "complexity_tier": "T3", "furigana": "zhè zhǒng guāng mǐn de xiǎo dēng tiān hēi jiù huì zì dòng liàng.", "sentence_source": "generated"}, {"text": "底片太光敏，不能打开盒子。", "target_word": "光敏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种墨水不光敏，放在外面也可以。", "target_word": "光敏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么这种塑料这么光敏？", "target_word": "光敏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "光敏电阻", "label": "复合"}, {"form": "光敏材料", "label": "复合"}, {"form": "光敏树脂", "label": "复合"}], "register": "科技", "sense_fingerprint": "东西碰到光就会发生变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82b7b2-23d4-4ad6-a0b8-5954ca1e3faa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光敏", "is_correct": true, "explanation": "正确。“这种纸很光敏”说明纸遇光会起变化，这是光敏的本义。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说的是味道，纸不会有甜味，不能用来形容纸。"}, {"text": "滚烫", "is_correct": false, "explanation": "体貌：“滚烫”描述温度，与纸遇光变化的性质不符。"}, {"text": "咸", "is_correct": false, "explanation": "语义：咸味不能用来形容纸，句意不通。"}], "explanations": {"光敏": "正确。“这种纸很光敏”说明纸遇光会起变化，这是光敏的本义。", "甜": "语义：“甜”说的是味道，纸不会有甜味，不能用来形容纸。", "滚烫": "体貌：“滚烫”描述温度，与纸遇光变化的性质不符。", "咸": "语义：咸味不能用来形容纸，句意不通。"}, "sentence_index": 0, "correct_answer": "光敏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对别人的批评很光敏，一听就哭了。", "explanation": "这里应该用〈敏感〉。光敏只用于物质或器件遇光产生变化，不能说人对批评的反应。"}, {"text": "这个孩子对猫毛很光敏，一接触就打喷嚏。", "explanation": "这里应该用〈过敏〉。光敏指东西受光照影响，猫毛引起的反应与光照无关。"}, {"text": "这个计划很光敏，大家一看就同意了。", "explanation": "这里把“光敏”用成了〈吸引人〉的意思。光敏只指东西碰到光会变化，计划不会因光而变，所以不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光敏", "is_correct": true, "explanation": "正确。“光敏的小灯”指遇光会自动变化的灯，与“天黑就会自动亮”相合。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”形容感情或味道，与灯依据光线自动亮的功能无关。"}, {"text": "粗糙", "is_correct": false, "explanation": "体貌：“粗糙”形容表面质感，与“天黑就会自动亮”的功能不符。"}, {"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”是味道，不能用来形容小灯。"}], "explanations": {"光敏": "正确。“光敏的小灯”指遇光会自动变化的灯，与“天黑就会自动亮”相合。", "甜蜜": "语义：“甜蜜”形容感情或味道，与灯依据光线自动亮的功能无关。", "粗糙": "体貌：“粗糙”形容表面质感，与“天黑就会自动亮”的功能不符。", "辛辣": "语义：“辛辣”是味道，不能用来形容小灯。"}, "sentence_index": 6, "correct_answer": "光敏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的耳朵很光敏，一有动静就醒了。", "explanation": "这里应该用〈灵敏〉。光敏只指东西遇光起变化，不能用来说耳朵对声音的反应。"}, {"text": "这条路很光敏，一下雨就特别滑。", "explanation": "这里应该用〈易滑〉。光敏只指东西碰到光会变化，路面湿了打滑与光照无关，不能这样用。"}, {"text": "他今天的心情很光敏，一句玩笑就哭了。", "explanation": "这里应该用〈脆弱〉。光敏只指东西碰到光会变化，不能用来形容人的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种墨水很光敏地，见光就会变蓝。", "corrected_sentence": "这种墨水很光敏，见光就会变蓝。", "error_description": "结构助词多余：“很光敏”作谓语，后面不能加“地”，应去掉“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种涂料光敏得，晒后就会变黄。", "corrected_sentence": "这种涂料光敏得厉害，晒后就会变黄。", "error_description": "“得”后面缺少补语：程度补语结构“光敏得……”需要补足语，应说“光敏得厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
