INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25552, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "物体移动的快慢。", "primary_collocate": null, "pronunciation": "sù lǜ", "ipa": "su˥˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "火车的速率比汽车快。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小球滚动的速率越来越慢。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请记下这辆车的速率。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步时，他的速率一直很稳。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们鸟飞的速率是多少。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯上升的速率不太快。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流的速率大，船开得快。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用秒表算了一下自己走路的速率。", "target_word": "速率", "complexity_tier": "T3", "furigana": "sù lǜ", "sentence_source": "generated"}, {"text": "风的速率变大了，树叶飘起来。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车的速率不同，到的时间也不同。", "target_word": "速率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平均速率", "label": "复合词"}, {"form": "飞行速率", "label": "复合词"}], "register": "通用", "sense_fingerprint": "东西移动有多快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5af2ec-2319-44fd-ab0e-6a7a7c95acf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "速率", "is_correct": true, "explanation": "正确。“速率”指火车运动的快慢，可以拿来与汽车比较，句意通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能用“比汽车快”来比较，句子不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不说快慢，“价格比汽车快”搭配不当。"}, {"text": "体积", "is_correct": false, "explanation": "语义：“体积”指物体的大小，不能用“快”来描述，句子意思说不通。"}], "explanations": {"速率": "正确。“速率”指火车运动的快慢，可以拿来与汽车比较，句意通顺。", "颜色": "语义：“颜色”指色彩，不能用“比汽车快”来比较，句子不通。", "价格": "搭配：“价格”不说快慢，“价格比汽车快”搭配不当。", "体积": "语义：“体积”指物体的大小，不能用“快”来描述，句子意思说不通。"}, "sentence_index": 0, "correct_answer": "速率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "银行的速率一直很稳。", "explanation": "这里应该用〈利率〉。利率指利息与本金的比率，速率指运动的快慢，银行不说速率。"}, {"text": "这台音响的速率一直很稳。", "explanation": "这里应该用〈音量〉。音量指声音的大小，速率指物体移动的快慢，音响的声音大小不说速率。"}, {"text": "这块木头的速率一直很稳。", "explanation": "这里应该用〈密度〉。密度指单位体积的质量，速率指快慢，木头的质量与体积之比不说速率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "速率", "is_correct": true, "explanation": "正确。“速率大”指水流快，所以船开得快，前后意思一致。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热程度，不能用“大”来说水流的快慢，句子不通。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：“亮度”指明暗程度，与船开得快无关，放在这里句子不通。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“寿命”指存在的年限，不能用来说水流的快慢，与“船开得快”搭配不当。"}], "explanations": {"速率": "正确。“速率大”指水流快，所以船开得快，前后意思一致。", "温度": "语义：“温度”指冷热程度，不能用“大”来说水流的快慢，句子不通。", "亮度": "语义：“亮度”指明暗程度，与船开得快无关，放在这里句子不通。", "寿命": "搭配：“寿命”指存在的年限，不能用来说水流的快慢，与“船开得快”搭配不当。"}, "sentence_index": 6, "correct_answer": "速率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间的速率比昨天低了。", "explanation": "这里应该用〈温度〉。温度指冷热的程度，速率指物体移动的快慢，房间的冷热不说速率。"}, {"text": "这家商店的速率今天增加了五千元。", "explanation": "这里应该用〈营业额〉。营业额指营业收入的总数，速率指物体移动的快慢，商店的收入不能用速率来说。"}, {"text": "这块地的速率很大。", "explanation": "这里应该用〈面积〉。面积指平面的大小，速率指运动快慢，地的面积不说速率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这艘船的速率长得多。", "corrected_sentence": "这艘船的速率快得多。", "error_description": "错误形式是“长得多”。“速率”表示快慢，不能用“长”来形容，应为“快得多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他骑车的速率很长。", "corrected_sentence": "他骑车的速率很快。", "error_description": "错误形式是“很长”。“速率”表示快慢，不能用“长”来形容，应为“很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
