INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25558, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "太阳光里的一种看不见的光，晒多了会伤害皮肤。", "primary_collocate": null, "pronunciation": "zǐ wài xiàn", "ipa": "tsɨ˨˩˦ waɪ˥˩ ɕjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "夏天太阳大，紫外线很强。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门要涂防晒霜，挡住紫外线。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "紫外线是看不见的光。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晒太多紫外线会伤害皮肤。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他戴上帽子和墨镜，挡住紫外线。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阴天的时候也有紫外线。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把伞可以挡紫外线。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "紫外线太强，孩子不要在外面玩太久。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，紫外线对眼睛也不好。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的眼睛看不到紫外线。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "束", "label": "量词"}, {"form": "紫外辐射", "label": "复合词"}], "register": "通用", "sense_fingerprint": "日常：太阳光里看不见、晒多了伤皮肤的光", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82b7b2-23d4-4ad6-a0b8-5954ca1e3faa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "紫外线", "is_correct": true, "explanation": "正确答案。“夏天太阳大，紫外线很强”，紫外线是句中能够“很强”的对象。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：香蕉不是太阳光，不能说“很强”，与“太阳大”的语境不符。"}, {"text": "海拔", "is_correct": false, "explanation": "搭配：“海拔”不能用“很强”来形容，这里要说的是光照的强弱。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包与夏天的太阳光无关，不能作为“很强”的主语。"}], "explanations": {"紫外线": "正确答案。“夏天太阳大，紫外线很强”，紫外线是句中能够“很强”的对象。", "香蕉": "语义：香蕉不是太阳光，不能说“很强”，与“太阳大”的语境不符。", "海拔": "搭配：“海拔”不能用“很强”来形容，这里要说的是光照的强弱。", "书包": "语义：书包与夏天的太阳光无关，不能作为“很强”的主语。"}, "sentence_index": 0, "correct_answer": "紫外线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书房里的紫外线很亮。", "explanation": "这里应该用〈灯光〉。紫外线是看不见的光，不能用“亮”来形容。"}, {"text": "中午紫外线很暖和，我们在院子里坐着。", "explanation": "这里应该用〈阳光〉。阳光能带来温暖；紫外线看不见，人感觉不到它的温暖。"}, {"text": "我们靠紫外线看清了黑板上的字。", "explanation": "这里应该用〈可见光〉。可见光人眼能看见，能照明；紫外线看不见，不能靠它看清字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "紫外线", "is_correct": true, "explanation": "正确答案。“这把伞可以挡紫外线”，伞能挡住的是光线。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不是伞能挡住的东西，与句子的物理语境不符。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜不能被伞挡住，这种说法不符合伞的用途。"}, {"text": "伞", "is_correct": false, "explanation": "搭配：“挡”的对象不能是伞本身，句中要挡的应是外界的东西。"}], "explanations": {"紫外线": "正确答案。“这把伞可以挡紫外线”，伞能挡住的是光线。", "心情": "语义：心情不是伞能挡住的东西，与句子的物理语境不符。", "饭菜": "语义：饭菜不能被伞挡住，这种说法不符合伞的用途。", "伞": "搭配：“挡”的对象不能是伞本身，句中要挡的应是外界的东西。"}, "sentence_index": 6, "correct_answer": "紫外线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室里有一张紫外线。", "explanation": "这里应该用〈束〉。“张”用于纸、桌子等扁平的东西，紫外线是光，计量光线要用“束”。"}, {"text": "客厅里有一座紫外线。", "explanation": "这里应该用〈束〉。“座”用于山、房屋等大型固定的东西，紫外线是光，计量光线要用“束”。"}, {"text": "天上有一颗紫外线。", "explanation": "这里应该用〈束〉。“颗”用于颗粒或球形的东西，紫外线是光，计量光线要用“束”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张紫外线很强。", "corrected_sentence": "这束紫外线很强。", "error_description": "量词错误：「这张紫外线」应为「这束紫外线」。紫外线是光线，计量光线要用“束”，“张”用于纸、桌子等扁平的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子不能长时间待紫外线下。", "corrected_sentence": "孩子不能长时间待在紫外线下。", "error_description": "介词漏用：「紫外线下」前缺少“在”，应为「待在紫外线下」，“在”引出处所。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
