INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25568, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "基团是化学里的一种小团体，由一些原子组成。", "primary_collocate": null, "pronunciation": "jī tuán", "ipa": "tɕi˥ tʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "基团是由几个原子组成的。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个基团。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个分子里有两个基团。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学书里讲了很多基团。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基团很小，我们用眼睛看不见。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道这个基团由哪些原子组成。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水分子里没有这样的基团。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的基团，性质也不一样。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书上找到了这个基团的名字。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个基团有三个原子。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "官能团", "label": "复合词"}], "register": "科技", "sense_fingerprint": "化学：由几个原子组成的小团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e82b7b2-23d4-4ad6-a0b8-5954ca1e3faa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基团", "is_correct": true, "explanation": "正确。“基团是由几个原子组成的”是基团的定义，句意成立。"}, {"text": "乐曲", "is_correct": false, "explanation": "语义：乐曲由音符组成，不是由原子组成的。"}, {"text": "季节", "is_correct": false, "explanation": "语义：季节是时间段，不是由原子组成的实体，与化学概念的定义不符。"}, {"text": "情绪", "is_correct": false, "explanation": "语义：情绪不是物质，不能由原子组成。"}], "explanations": {"基团": "正确。“基团是由几个原子组成的”是基团的定义，句意成立。", "乐曲": "语义：乐曲由音符组成，不是由原子组成的。", "季节": "语义：季节是时间段，不是由原子组成的实体，与化学概念的定义不符。", "情绪": "语义：情绪不是物质，不能由原子组成。"}, "sentence_index": 0, "correct_answer": "基团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个基团的活动很精彩。", "explanation": "这里应该用〈团体〉。基团是化学中分子的一部分，不指有活动的一群人。"}, {"text": "这家基团有三万名员工。", "explanation": "这里应该用〈集团〉。基团是化学术语，不能指公司或企业。"}, {"text": "这台基团很小，我们用眼睛看不见。", "explanation": "量词用错。“基团”应该用“个”，“台”用于机器等，不能用来数基团。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基团", "is_correct": true, "explanation": "正确。“水分子里没有这样的基团”指水分子中不存在的原子组合，句意成立。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不是分子的一部分，“水分子里”不会有花朵。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具与分子结构无关，句中讲的是化学结构。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“水分子里”不搭配“书包”，化学语境中不能这样说。"}], "explanations": {"基团": "正确。“水分子里没有这样的基团”指水分子中不存在的原子组合，句意成立。", "花朵": "语义：花朵不是分子的一部分，“水分子里”不会有花朵。", "玩具": "语义：玩具与分子结构无关，句中讲的是化学结构。", "书包": "搭配：“水分子里”不搭配“书包”，化学语境中不能这样说。"}, "sentence_index": 6, "correct_answer": "基团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的写作基团很扎实。", "explanation": "这里应该用〈基础〉。基团是化学术语，指分子中的原子组合，不能用来说写作的根基。"}, {"text": "我把这个基团煮熟后吃了。", "explanation": "这里把“基团”当成了〈食材〉的意思，指可以煮来吃的东西。基团是分子中的原子组合，不能煮熟吃。"}, {"text": "这张桌子的基团很结实，坐上去不会晃。", "explanation": "这里应该用〈部件〉。基团是化学术语，指分子中的原子组合，不能指桌子的组成部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个分子里有三根基团，它们由原子组成。", "corrected_sentence": "这个分子里有三个基团，它们由原子组成。", "error_description": "量词用错。“基团”应该用“个”，“根”只用于细长的东西，不能用来数基团。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个分子都有相同地基团。", "corrected_sentence": "这两个分子都有相同的基团。", "error_description": "结构助词用错。“相同”修饰名词“基团”，应用“的”，说“相同的基团”；“地”用于修饰动词，不能用在名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdd204d-8870-4865-a718-73d4965e8f56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
