INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25578, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个小东西粘在另一个东西上面，很难分开。", "primary_collocate": null, "pronunciation": "fù zhuó", "ipa": "fu˥˩ ʈʂuo˧˥", "syllable_count": 2, "sentences": [{"text": "小贝壳紧紧附着在石头上。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一片树叶附着在车窗上，怎么也吹不掉。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "口香糖附着在鞋底，很难弄下来。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小虫子附着在玻璃上，一动也不动。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一只小蚂蚁附着在他的袖子上，怎么也甩不掉。", "target_word": "附着", "complexity_tier": "T3", "furigana": "yī zhī xiǎo mǎyǐ fùzhuó zài tā de xiùzi shàng, zěnme yě shuǎi bu diào。", "sentence_source": "generated"}, {"text": "这张小贴纸附着在书上，撕不下来。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鱼身上附着一些白色的小点。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜗牛附着在墙上，慢慢往上爬。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "头发上附着了一些雪，他笑着拍掉。", "target_word": "附着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小螃蟹附着在船边的木头上。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "附着了", "label": "体标（了）"}, {"form": "附着力", "label": "复合词"}, {"form": "附着物", "label": "复合词"}], "register": "书面", "sense_fingerprint": "小东西粘在别的东西上面，很难分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f70ce21-a5b1-4c2c-be9e-0c290ce26038') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25578, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "附着", "is_correct": true, "explanation": "小贝壳紧紧附着在石头上，表示小东西粘得很牢，符合句意。"}, {"text": "跳", "is_correct": false, "explanation": "语义：贝壳不能跳，与紧紧粘住石头的意思不合。"}, {"text": "唱", "is_correct": false, "explanation": "配价：唱需要歌曲等宾语，不能说唱在石头上。"}, {"text": "吹", "is_correct": false, "explanation": "语义：吹指用气流推动，贝壳不会因被吹而粘在石头上。"}], "explanations": {"附着": "小贝壳紧紧附着在石头上，表示小东西粘得很牢，符合句意。", "跳": "语义：贝壳不能跳，与紧紧粘住石头的意思不合。", "唱": "配价：唱需要歌曲等宾语，不能说唱在石头上。", "吹": "语义：吹指用气流推动，贝壳不会因被吹而粘在石头上。"}, "sentence_index": 0, "correct_answer": "附着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从不附着父母生活，凡事都靠自己。", "explanation": "这里应该用〈依附〉。附着指小东西粘在物体表面，靠他人生活要用依附。"}, {"text": "一头大象附着在树下，慢慢睡着了。", "explanation": "这里应该用〈躺〉。附着指小东西粘在物体上，大象休息要说躺。"}, {"text": "这座大楼附着在河边，很高大。", "explanation": "这里应该用〈矗立〉。附着指小东西粘在物体表面，大楼是固定矗立，不能说附着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "附着", "is_correct": true, "explanation": "鱼身上附着一些白色的小点，表示小点粘在鱼身上，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃的动作要求宾语是食物，白色的小点不能被吃在鱼身上。"}, {"text": "闻", "is_correct": false, "explanation": "语义：闻是嗅觉动作，与小点粘在鱼身上的意思不符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：穿用于衣物鞋袜，不能与白色的小点搭配。"}], "explanations": {"附着": "鱼身上附着一些白色的小点，表示小点粘在鱼身上，符合句意。", "吃": "语义：吃的动作要求宾语是食物，白色的小点不能被吃在鱼身上。", "闻": "语义：闻是嗅觉动作，与小点粘在鱼身上的意思不符。", "穿": "搭配：穿用于衣物鞋袜，不能与白色的小点搭配。"}, "sentence_index": 6, "correct_answer": "附着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小鸟附着在树枝上，唱了一首歌。", "explanation": "这里应该用〈停〉。附着指小东西粘在物体表面、难以分开，小鸟停在树枝上不是黏附。"}, {"text": "妈妈附着毛巾，跑去开门了。", "explanation": "这里应该用〈拿〉。附着是不及物的，指小东西粘在物体上，不能直接带“毛巾”作宾语表示拿着。"}, {"text": "老人附着拐杖慢慢走。", "explanation": "这里应该用〈拄〉。附着指小东西粘在物体上，人拿拐杖走路要说拄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只小蜘蛛附着着在窗角上，一动不动。", "corrected_sentence": "一只小蜘蛛附着在窗角上，一动不动。", "error_description": "错误：“着”重复使用。“附着”后只用一个“在”字结构，应说“附着在窗角上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜗牛附着树干上，爬得很慢。", "corrected_sentence": "蜗牛附着在树干上，爬得很慢。", "error_description": "错误：「附着」后缺少介词「在」。应说「附着在树干上」，不能直接接名词「树干上」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bfe198b-5b59-449a-9b60-efd19db7884f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
