INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25582, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "淡水是没有咸味的水，可以喝。", "primary_collocate": null, "pronunciation": "dàn shuǐ", "ipa": "tan˥˩ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "海水太咸了，不能喝，要喝淡水。", "target_word": "淡水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在岛上找到了一些淡水。", "target_word": "淡水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出海前，船员带了很多淡水。", "target_word": "淡水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这口井里的水不咸，是淡水。", "target_word": "淡水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙漠里最重要的是食物和淡水。", "target_word": "淡水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把淡水倒进杯子里喝。", "target_word": "淡水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的井里有淡水，村民每天来打水。", "target_word": "淡水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船上的淡水不多，大家只能少喝一点。", "target_word": "淡水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种机器能把海水变成淡水。", "target_word": "淡水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岛上没有河，人们只能靠雨水获得淡水。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "zhè ge dǎo shàng méi yǒu hé, rén men zhǐ néng kào yǔ shuǐ huò dé dàn shuǐ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "淡水湖", "label": "复合"}, {"form": "淡水鱼", "label": "复合"}], "register": "中性", "sense_fingerprint": "没有咸味、可以喝的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de9a87f-9352-48aa-a1f5-bcc350764b12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25582, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "淡水", "is_correct": true, "explanation": "淡水：没有咸味、可以喝的水，与前句“不能喝”形成对照。"}, {"text": "咸水", "is_correct": false, "explanation": "语义：咸水仍是咸的，不能喝，与“要喝”相矛盾。"}, {"text": "煤油", "is_correct": false, "explanation": "语义：煤油有毒，不能拿来喝，句意不符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“喝”的对象应是液体，“喝空气”不搭配。"}], "explanations": {"淡水": "淡水：没有咸味、可以喝的水，与前句“不能喝”形成对照。", "咸水": "语义：咸水仍是咸的，不能喝，与“要喝”相矛盾。", "煤油": "语义：煤油有毒，不能拿来喝，句意不符。", "空气": "搭配：“喝”的对象应是液体，“喝空气”不搭配。"}, "sentence_index": 0, "correct_answer": "淡水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "淡水很咸，不能直接喝。", "explanation": "这里应该用〈海水〉。淡水是没有咸味、可以喝的水，不能说“很咸”；咸的是海水。"}, {"text": "腌鸡蛋要用淡水，味道很咸。", "explanation": "这里应该用〈盐水〉。淡水没有咸味，腌鸡蛋用的盐水才会咸。"}, {"text": "淡水不能喝，喝了会口渴。", "explanation": "这里应该用〈咸水〉。淡水是可以喝的水，不能说“不能喝”；“不能喝、会口渴”的是咸水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "淡水", "is_correct": true, "explanation": "淡水：可以取用的淡水，井里有它，村民才天天来打水。"}, {"text": "火", "is_correct": false, "explanation": "搭配：“打水”的对象是液体，与“火”不搭配。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：井里不可能有钢琴，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的外观，不是井里能有的东西，句意不合。"}], "explanations": {"淡水": "淡水：可以取用的淡水，井里有它，村民才天天来打水。", "火": "搭配：“打水”的对象是液体，与“火”不搭配。", "钢琴": "语义：井里不可能有钢琴，句意不通。", "颜色": "语义：颜色是事物的外观，不是井里能有的东西，句意不合。"}, "sentence_index": 6, "correct_answer": "淡水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "船长带了一条淡水，分给大家。", "explanation": "量词错误：“条”用于细长的东西，淡水应说“一瓶淡水”或“一桶淡水”。"}, {"text": "他们在岛上找到了一些淡水，用它来点火取暖。", "explanation": "这里应该用〈木柴〉。淡水是可以喝的水，不能用来点火；取暖要用木柴。"}, {"text": "妈妈给我倒了一片淡水。", "explanation": "量词错误：“片”用于扁平的东西，淡水应说“一杯淡水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "船上装了一片淡水，够大家喝三天。", "corrected_sentence": "船上装了一桶淡水，够大家喝三天。", "error_description": "量词错误：“片”用于扁平的东西，淡水是液体，应说“一桶淡水”或“一瓶淡水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔民把干净地淡水装上了小船。", "corrected_sentence": "渔民把干净的淡水装上了小船。", "error_description": "结构助词错误：“干净”修饰“淡水”，二者之间应用“的”，此处误用“地”；“地”用于动词前作状语。应说“干净的淡水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
