INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25584, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工厂里做东西的工作。", "primary_collocate": null, "pronunciation": "gōng yè", "ipa": "kʊŋ˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市的工业很发达。", "target_word": "工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业需要很多电和水。", "target_word": "工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的家乡没有工业，大家都种地。", "target_word": "工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的工业发展得很快。", "target_word": "工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业会带来污染，要注意环境。", "target_word": "工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业对国家的经济很重要。", "target_word": "工业", "complexity_tier": "T3", "furigana": "gōngyè", "sentence_source": "generated"}, {"text": "以前这里只有农业，现在有了工业。", "target_word": "工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学的是工业方面的知识。", "target_word": "工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区靠工业赚了很多钱。", "target_word": "工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的工业比南方发达。", "target_word": "工业", "complexity_tier": "T3", "furigana": "gōngyè", "sentence_source": "generated"}], "morphological_forms": [{"form": "轻工业", "label": "复合词"}, {"form": "重工业", "label": "复合词"}, {"form": "工业区", "label": "复合词"}, {"form": "工业化", "label": "复合词"}], "register": "中性", "sense_fingerprint": "工业：名词，用机器在工厂里生产物品的行业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be7eb40f-7d8a-4232-9c49-ff679e0a5a7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25584, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "工业", "is_correct": true, "explanation": "gōng yè 对应“工业”，指用机器在工厂里生产物品的行业。"}, {"text": "公益", "is_correct": false, "explanation": "gōng yì 与 gōng yè 的韵母不同（yì 与 yè），意思是为公众谋利益的事业。"}, {"text": "钢业", "is_correct": false, "explanation": "gāng 与 gōng 韵母不同（ang 与 ong），声调相同，意思是钢铁行业。"}, {"text": "工艺", "is_correct": false, "explanation": "gōng yì 与 gōng yè 的韵母不同（yì 与 yè），意思是手工技艺。"}, {"text": "共业", "is_correct": false, "explanation": "gòng yè 与 gōng yè 声调不同，是佛教用语，指共同的业报。"}], "explanations": {"工业": "gōng yè 对应“工业”，指用机器在工厂里生产物品的行业。", "公益": "gōng yì 与 gōng yè 的韵母不同（yì 与 yè），意思是为公众谋利益的事业。", "钢业": "gāng 与 gōng 韵母不同（ang 与 ong），声调相同，意思是钢铁行业。", "工艺": "gōng yì 与 gōng yè 的韵母不同（yì 与 yè），意思是手工技艺。", "共业": "gòng yè 与 gōng yè 声调不同，是佛教用语，指共同的业报。"}, "sentence_index": null, "correct_answer": "工业"}, "level_3": {"options": [{"text": "工业", "is_correct": true, "explanation": "“工业”是行业，可以与“发达”搭配，符合“这个城市的……很发达”，是正确答案。"}, {"text": "森林", "is_correct": false, "explanation": "语义：森林是植物群落，不是行业，不能说“发达”。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言是交流工具，城市的语言不能说“发达”。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“发达”多用于行业、经济、交通，“人口”是数量，不说发达。"}], "explanations": {"工业": "“工业”是行业，可以与“发达”搭配，符合“这个城市的……很发达”，是正确答案。", "森林": "语义：森林是植物群落，不是行业，不能说“发达”。", "语言": "语义：语言是交流工具，城市的语言不能说“发达”。", "人口": "搭配：“发达”多用于行业、经济、交通，“人口”是数量，不说发达。"}, "sentence_index": 0, "correct_answer": "工业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在一家工业上班。", "explanation": "这里应该用〈工厂〉。工业指行业，不是具体的单位，不能用来说在哪一家企业上班。"}, {"text": "我最喜欢吃的水果是工业。", "explanation": "这里应该用〈苹果〉。工业指工厂生产领域，不是水果，不能说“水果是工业”。"}, {"text": "我今天的工业很多，要做到很晚。", "explanation": "这里应该用〈工作〉。工业指行业，不指每天要做的事情，“工作很多”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工业", "is_correct": true, "explanation": "“工业”是产业，与“只有农业”形成对比，“现在有了工业”符合语境，是正确答案。"}, {"text": "寒假", "is_correct": false, "explanation": "语义：寒假是一段假期，不是产业，无法与“农业”构成对比。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物品，不是产业，与“只有农业”的对比不相合。"}, {"text": "车祸", "is_correct": false, "explanation": "语义：车祸是突发事故，不是可以发展的产业，与“只有农业”的对比不相合。"}], "explanations": {"工业": "“工业”是产业，与“只有农业”形成对比，“现在有了工业”符合语境，是正确答案。", "寒假": "语义：寒假是一段假期，不是产业，无法与“农业”构成对比。", "眼镜": "语义：眼镜是物品，不是产业，与“只有农业”的对比不相合。", "车祸": "语义：车祸是突发事故，不是可以发展的产业，与“只有农业”的对比不相合。"}, "sentence_index": 6, "correct_answer": "工业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的工业是医生，每天救死扶伤。", "explanation": "这里应该用〈职业〉。工业指工厂生产领域，不能用来指一个人的职业。"}, {"text": "我的工业是计算机，学得很好。", "explanation": "这里应该用〈专业〉。工业指工厂生产领域，不能用来指所学的专业。"}, {"text": "他每天早上喝工业。", "explanation": "这里应该用〈牛奶〉。工业不是饮品，不能用“喝”来搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个省的工业发展的很快。", "corrected_sentence": "这个省的工业发展得很快。", "error_description": "补语标记错误：程度补语应用“得”，不能用“的”，应说“发展得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个省的一座工业很发达。", "corrected_sentence": "这个省的工业很发达。", "error_description": "量词错误：“工业”是抽象的行业名称，不能用“座”计量，应直接说“这个省的工业很发达”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25586, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "迅速", "is_correct": true, "explanation": "正确。“迅速”表示快、速度高，与“缓慢”互为反义。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容声音小或环境静，与“缓慢”没有反义关系。"}, {"text": "热烈", "is_correct": false, "explanation": "“热烈”形容情绪或场面，与“缓慢”没有反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”形容清楚、分明，与“缓慢”没有反义关系。"}], "correct_answer": "迅速", "explanations": {"迅速": "正确。“迅速”表示快、速度高，与“缓慢”互为反义。", "安静": "“安静”形容声音小或环境静，与“缓慢”没有反义关系。", "热烈": "“热烈”形容情绪或场面，与“缓慢”没有反义关系。", "清晰": "“清晰”形容清楚、分明，与“缓慢”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25586, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "迅速", "is_correct": true, "explanation": "正确。“迅速”表示快、速度高，与“缓慢”互为反义。"}, {"text": "平坦", "is_correct": false, "explanation": "“平坦”形容地面或路面，与“缓慢”没有反义关系。"}, {"text": "繁忙", "is_correct": false, "explanation": "“繁忙”形容事务多、很忙，与“缓慢”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外表好看，与“缓慢”没有反义关系。"}], "correct_answer": "迅速", "explanations": {"迅速": "正确。“迅速”表示快、速度高，与“缓慢”互为反义。", "平坦": "“平坦”形容地面或路面，与“缓慢”没有反义关系。", "繁忙": "“繁忙”形容事务多、很忙，与“缓慢”没有反义关系。", "漂亮": "“漂亮”形容外表好看，与“缓慢”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25586, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是动作很慢，不快。", "primary_collocate": null, "pronunciation": "huǎn màn", "ipa": "xwan˨˩˦ man˥˩", "syllable_count": 2, "sentences": [{"text": "老人的动作很缓慢，走路要很久。", "target_word": "缓慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水缓慢地向前流着。", "target_word": "缓慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的发展很缓慢。", "target_word": "缓慢", "complexity_tier": "T3", "furigana": "zhè zuò chéng shì de fā zhǎn hěn huǎn màn。", "sentence_source": "generated"}, {"text": "车堵在路上，车子只能缓慢地往前走。", "target_word": "缓慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚生病，说话也变得缓慢了。", "target_word": "缓慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电梯门缓慢地打开了。", "target_word": "缓慢", "complexity_tier": "T3", "furigana": "diàn tī mén huǎn màn de dǎ kāi le。", "sentence_source": "generated"}, {"text": "老师缓慢地读了一遍课文，大家都听清楚了。", "target_word": "缓慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济增长缓慢，很多人找不到工作。", "target_word": "缓慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雪天，火车开得很缓慢。", "target_word": "缓慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作进展很缓慢，经理有点儿不高兴。", "target_word": "缓慢", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "缓慢地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "动作、速度、进展很慢，不快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae0a5167-b7a0-4535-b648-c4ab11c8f416') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25586, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缓慢", "is_correct": true, "explanation": "正确。「缓慢」形容动作、速度慢，与“动作很……，走路要很久”相符。"}, {"text": "迅速", "is_correct": false, "explanation": "语义：“迅速”是快，与后文“走路要很久”矛盾。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不能用来形容动作。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”可形容身体或动作灵活，但与后文“走路要很久”所说的慢不合。"}], "explanations": {"缓慢": "正确。「缓慢」形容动作、速度慢，与“动作很……，走路要很久”相符。", "迅速": "语义：“迅速”是快，与后文“走路要很久”矛盾。", "明亮": "搭配：“明亮”形容光线或颜色，不能用来形容动作。", "柔软": "语义：“柔软”可形容身体或动作灵活，但与后文“走路要很久”所说的慢不合。"}, "sentence_index": 0, "correct_answer": "缓慢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的手表缓慢了十分钟。", "explanation": "这里应该用〈慢〉。表走得比标准时间迟，要说“慢”；“缓慢”只形容动作、速度或进展慢。"}, {"text": "两国之间的紧张局势逐渐缓慢了。", "explanation": "这里应该用〈缓和〉。紧张的局势变得平稳要说“缓和”，“缓慢”只说速度慢。"}, {"text": "这个房间很缓慢。", "explanation": "这里应该用〈宽敞〉。房间的大小用“宽敞”，“缓慢”不能用来形容空间或事物的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25586, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缓慢", "is_correct": true, "explanation": "正确。“缓慢地”修饰“读”，与“大家都听清楚了”相符。"}, {"text": "模糊", "is_correct": false, "explanation": "语义：“模糊”与后文“大家都听清楚了”矛盾。"}, {"text": "含糊", "is_correct": false, "explanation": "语义：“含糊”指说话不清楚，与“大家都听清楚了”矛盾。"}, {"text": "潦草", "is_correct": false, "explanation": "语义：“潦草”指字迹不工整或做事草率，与后文“大家都听清楚了”矛盾。"}], "explanations": {"缓慢": "正确。“缓慢地”修饰“读”，与“大家都听清楚了”相符。", "模糊": "语义：“模糊”与后文“大家都听清楚了”矛盾。", "含糊": "语义：“含糊”指说话不清楚，与“大家都听清楚了”矛盾。", "潦草": "语义：“潦草”指字迹不工整或做事草率，与后文“大家都听清楚了”矛盾。"}, "sentence_index": 6, "correct_answer": "缓慢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他缓慢地打了个喷嚏。", "explanation": "这里应该用〈突然〉。打喷嚏是瞬间发生的动作，“缓慢”只用于动作进行得慢的情况。"}, {"text": "他缓慢地考上了大学。", "explanation": "这里应该用〈顺利〉。考上大学是一次完成的结果，“缓慢”不能修饰这种结果。"}, {"text": "这两个人的身高很缓慢。", "explanation": "这里应该用〈高〉。身高用高矮描述，“缓慢”不能用来形容人的身材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他缓慢的走进了房间。", "corrected_sentence": "他缓慢地走进了房间。", "error_description": "「缓慢」作状语修饰动词时要用“地”，不能用“的”。应说“他缓慢地走进了房间”，不能说“他缓慢的走进了房间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器运行的很缓慢。", "corrected_sentence": "这台机器运行得很缓慢。", "error_description": "动词后引出补语要用“得”，应说“运行得很缓慢”，这里误用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cee9096-0427-4b41-aa43-60d0541773df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
