INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25588, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "纳米是很小很小的长度单位，比头发丝还要小很多很多。", "primary_collocate": null, "pronunciation": "nà mǐ", "ipa": "na˥˩ mi˨˩˦", "syllable_count": 2, "sentences": [{"text": "一纳米比头发丝细得多。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "纳米是很小很小的长度单位。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灰尘比一纳米大得多。", "target_word": "纳米", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一根头发有好几万纳米那么粗。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小东西只有几纳米大。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "眼睛看不到纳米大小的东西。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用纳米来量，能测出很小东西的大小。", "target_word": "纳米", "complexity_tier": "T3", "furigana": "nà mǐ", "sentence_source": "generated"}, {"text": "哥哥问我：“纳米有多小？”", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师用头发丝来讲纳米有多小。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上说纳米比一粒沙子小得多。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "纳米技术", "label": "复合词"}, {"form": "纳米材料", "label": "复合词"}, {"form": "纳米级", "label": "复合词"}, {"form": "納米", "label": "繁体"}], "register": "中性", "sense_fingerprint": "极小的长度单位，比头发丝小得多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5af2ec-2319-44fd-ab0e-6a7a7c95acf2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纳米", "is_correct": true, "explanation": "“纳米”是极小的长度单位，与“一……比头发丝细得多”相合。"}, {"text": "纬度", "is_correct": false, "explanation": "语义：“纬度”是地理坐标，不能用来比较粗细。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不能用来比较头发丝的粗细。"}, {"text": "分贝", "is_correct": false, "explanation": "语义：“分贝”是声音强度单位，与粗细无关。"}], "explanations": {"纳米": "“纳米”是极小的长度单位，与“一……比头发丝细得多”相合。", "纬度": "语义：“纬度”是地理坐标，不能用来比较粗细。", "体重": "搭配：“体重”不能用来比较头发丝的粗细。", "分贝": "语义：“分贝”是声音强度单位，与粗细无关。"}, "sentence_index": 0, "correct_answer": "纳米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这袋面粉重三纳米。", "explanation": "这里应该用〈千克〉。“纳米”是长度单位，不能用来表示重量。"}, {"text": "我存的钱有好几万纳米。", "explanation": "这里应该用〈元〉。“纳米”是长度单位，不能用来计算钱数。"}, {"text": "这颗灰尘的年龄有几百纳米。", "explanation": "这里应该用〈岁〉。“纳米”是长度单位，不能用来说年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纳米", "is_correct": true, "explanation": "“用纳米来量”指用纳米这个单位测量，与“能测出很小东西的大小”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用尺子一类的单位来量。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能用来测量很小东西的大小。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：“香味”不能用来量，与“测出大小”的语境不符。"}], "explanations": {"纳米": "“用纳米来量”指用纳米这个单位测量，与“能测出很小东西的大小”相合。", "颜色": "语义：颜色不能用尺子一类的单位来量。", "声音": "语义：声音不能用来测量很小东西的大小。", "香味": "搭配：“香味”不能用来量，与“测出大小”的语境不符。"}, "sentence_index": 6, "correct_answer": "纳米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个路程有三纳米长。", "explanation": "这里应该用〈公里〉。“纳米”只用于很小的长度，不能说路程。"}, {"text": "这次旅行用了三纳米的时间。", "explanation": "这里应该用〈天〉或〈小时〉。“纳米”是长度单位，不能用来计时间。"}, {"text": "这件衣服比一纳米贵得多。", "explanation": "这里应该用〈一块钱〉。“纳米”是长度单位，不能用来比较价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗沙子只有几百个纳米大。", "corrected_sentence": "这颗沙子只有几百纳米大。", "error_description": "“纳米”作长度单位，前面不能加量词“个”，数量词直接放在前面，应为“几百纳米大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种颗粒比一个纳米大得多。", "corrected_sentence": "这种颗粒比一纳米大得多。", "error_description": "“纳米”作长度单位，前面的数量词“一”后不能加量词“个”，应为“一纳米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb758d7-0c84-4011-8583-a3808326bbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25590, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25590, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25590, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "鸿沟是很大的不同，就像一条大河把两边分开了。", "primary_collocate": null, "pronunciation": "hóng gōu", "ipa": "xʊŋ˧˥ kou˥˥", "syllable_count": 2, "sentences": [{"text": "他们的想法不同，中间有一条鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和我之间好像有一道鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市和农村的生活水平存在着巨大的鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和他做朋友，但年龄是一道鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要缩小大家之间的鸿沟，先要多说话。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们之间的鸿沟，不是一天形成的。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习成绩的鸿沟让这个孩子很难过。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种看法之间有一条很深的鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用笑容填平了彼此之间的鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说不同的语言，会在人们之间留下鸿沟。", "target_word": "鸿沟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道鸿沟", "label": "量词"}, {"form": "一条鸿沟", "label": "量词"}, {"form": "鴻溝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很大的不同，像大河把两边分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93f1010e-ee55-4e33-9cf5-8af6804f420b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25590, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鸿沟", "is_correct": true, "explanation": "鸿沟指很大的不同，与“想法不同”的语境相符。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子是拴东西的器物，不是想法上的不同，“中间有一条绳子”不能指分歧。"}, {"text": "项链", "is_correct": false, "explanation": "语义：项链是首饰，与想法上的分歧无关，句子不通。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾是保暖的衣物，与想法上的差异无关，句子不通。"}], "explanations": {"鸿沟": "鸿沟指很大的不同，与“想法不同”的语境相符。", "绳子": "语义：绳子是拴东西的器物，不是想法上的不同，“中间有一条绳子”不能指分歧。", "项链": "语义：项链是首饰，与想法上的分歧无关，句子不通。", "围巾": "语义：围巾是保暖的衣物，与想法上的差异无关，句子不通。"}, "sentence_index": 0, "correct_answer": "鸿沟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的成绩只差两分，却有一道相差两分的鸿沟。", "explanation": "这里应该用〈差距〉。鸿沟不能用“相差两分”这样的数量来计算，说数量上的差别要用差距。"}, {"text": "我家到他家有三公里的鸿沟。", "explanation": "这里应该用〈距离〉。“三公里”是距离的计量单位，鸿沟指抽象的差异，不能用公里计算。"}, {"text": "他每天都要给这道鸿沟浇水。", "explanation": "这里应该用〈花〉。鸿沟是抽象的差异，不能浇水；应说给花浇水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鸿沟", "is_correct": true, "explanation": "鸿沟指很大的不同或隔阂，作主语与“让这个孩子很难过”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是成绩之间的差异，“学习成绩的天气”说不通。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是喝的东西，与学习成绩上的差别无关，句子不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，指东西或事物，与书面叙述不协调，也不能表示成绩之间的差异。"}], "explanations": {"鸿沟": "鸿沟指很大的不同或隔阂，作主语与“让这个孩子很难过”相符。", "天气": "语义：天气不是成绩之间的差异，“学习成绩的天气”说不通。", "饮料": "语义：饮料是喝的东西，与学习成绩上的差别无关，句子不通。", "玩意儿": "语域：“玩意儿”是口语，指东西或事物，与书面叙述不协调，也不能表示成绩之间的差异。"}, "sentence_index": 6, "correct_answer": "鸿沟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们终于把彼此之间的鸿沟解开了。", "explanation": "这里应该用〈误会〉。“解开”用于误会、疙瘩，鸿沟表示很大的不同，不能被解开。"}, {"text": "这场争论中，双方的鸿沟越来越激化。", "explanation": "这里应该用〈矛盾〉。“激化”用于矛盾、冲突，鸿沟表示很大的不同，不会激化。"}, {"text": "他们要和过去划清鸿沟。", "explanation": "这里应该用〈界限〉。“划清”搭配界限，鸿沟表示很大的不同，不能被划清。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次交流缩小了两家人之间的一颗鸿沟。", "corrected_sentence": "这次交流缩小了两家人之间的一道鸿沟。", "error_description": "量词用错：鸿沟是抽象的隔阂，应该用“道”，“颗”用于圆粒状的东西，不能用来计量鸿沟。正确的说法是“这次交流缩小了两家人之间的一道鸿沟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次交流把两代人之间的鸿沟缩大了。", "corrected_sentence": "这次交流把两代人之间的鸿沟缩小了。", "error_description": "补语用错：“鸿沟”的差距要变少，补语应该是“小”，说“缩大”意思相反，也不地道。正确的说法是“把两代人之间的鸿沟缩小了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
