INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25592, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25592, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "冷凉的意思是天气不热，有一点冷，让人感觉很舒服。", "primary_collocate": null, "pronunciation": "lěng liáng", "ipa": "lɤŋ˨˩˦ ljɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "冷凉的天气让人睡得很好。", "target_word": "冷凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天来了，早晚的天气很冷凉。", "target_word": "冷凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天的夜里，山上的空气很冷凉。", "target_word": "冷凉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这种冷凉的天气，出去走走很舒服。", "target_word": "冷凉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停以后，屋子里变得冷凉了。", "target_word": "冷凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗外吹来一阵冷凉的风。", "target_word": "冷凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天的海边冷凉舒服，很多人来玩。", "target_word": "冷凉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢在冷凉的早晨跑步。", "target_word": "冷凉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在冷凉的树荫下，我们坐着聊天。", "target_word": "冷凉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天不太热，晚上有点冷凉。", "target_word": "冷凉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷涼", "label": "繁体"}, {"form": "冷凉气候", "label": "复合"}], "register": "书面", "sense_fingerprint": "冷凉：天气不热、有一点冷，让人感觉舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd41bb3f0-444d-44a7-aecf-74c5fab366ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25592, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "闷热", "is_correct": false, "explanation": "语义：“闷热”让人难受，与“睡得很好”矛盾。"}, {"text": "冷凉", "is_correct": true, "explanation": "“冷凉”指天气不热、略带凉意，让人睡得舒服，与句子语境相合。"}, {"text": "严寒", "is_correct": false, "explanation": "语义：“严寒”指天气极冷，不会让人睡得很好。"}, {"text": "喧闹", "is_correct": false, "explanation": "搭配：“喧闹”形容声音或场面，不能用来修饰天气。"}], "explanations": {"闷热": "语义：“闷热”让人难受，与“睡得很好”矛盾。", "冷凉": "“冷凉”指天气不热、略带凉意，让人睡得舒服，与句子语境相合。", "严寒": "语义：“严寒”指天气极冷，不会让人睡得很好。", "喧闹": "搭配：“喧闹”形容声音或场面，不能用来修饰天气。"}, "sentence_index": 0, "correct_answer": "冷凉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春节那天，他一个人过得很冷凉。", "explanation": "这里应该用〈冷清〉。冷凉只指温度，不能形容生活孤单、没有热闹，这种意思要说冷清。"}, {"text": "他对新同事的态度很冷凉，大家都不太敢和他说话。", "explanation": "这里应该用〈冷淡〉。冷凉只描述温度，不用来形容人的态度。"}, {"text": "他冷凉地笑了一下，大家都很害怕。", "explanation": "这里应该用〈冷笑〉。冷凉只描述温度，不能修饰笑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25592, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "炎热", "is_correct": false, "explanation": "语义：“炎热”与秋天和“舒服”矛盾，炎热的海边不让人觉得舒服。"}, {"text": "冷凉", "is_correct": true, "explanation": "“冷凉”略带凉意，秋天海边的这种感觉让人舒服，与“很多人来玩”相合。"}, {"text": "空旷", "is_correct": false, "explanation": "语义：“空旷”指没有人，与“很多人来玩”矛盾。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容坡度，不能用来描述海边的凉爽程度。"}], "explanations": {"炎热": "语义：“炎热”与秋天和“舒服”矛盾，炎热的海边不让人觉得舒服。", "冷凉": "“冷凉”略带凉意，秋天海边的这种感觉让人舒服，与“很多人来玩”相合。", "空旷": "语义：“空旷”指没有人，与“很多人来玩”矛盾。", "陡峭": "搭配：“陡峭”形容坡度，不能用来描述海边的凉爽程度。"}, "sentence_index": 6, "correct_answer": "冷凉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个冬天的夜里冷凉得让人直打哆嗦。", "explanation": "这里应该用〈寒冷〉。冷凉只表示略带凉意，冷得直打哆嗦要说寒冷。"}, {"text": "这几天冷凉得厉害，连湖面都结了冰。", "explanation": "这里应该用〈严寒〉。冷凉只表示略带寒意，冷到湖面结冰的程度要说严寒。"}, {"text": "冷凉的河水冻得人手指发麻。", "explanation": "这里应该用〈刺骨〉。冷凉只表示略带寒意，让手指发麻的寒冷要说刺骨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早晨的空气把冷凉了。", "corrected_sentence": "早晨的空气冷凉了。", "error_description": "“把”字句的宾语应是名词或动词性成分，形容词“冷凉”不能直接接在“把”后面。这里应说“空气冷凉了”，不能说“空气把冷凉了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖边的傍晚，一阵冷凉地风吹过水面。", "corrected_sentence": "湖边的傍晚，一阵冷凉的风吹过水面。", "error_description": "修饰名词要用“的”，不用“地”。这里应说“冷凉的风”，不能说“冷凉地风”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
