INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25594, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水占的地方，比如河、湖、海。", "primary_collocate": null, "pronunciation": "shuǐ yù", "ipa": "ʂueɪ˨˩˦ y˥˩", "syllable_count": 2, "sentences": [{"text": "地图上蓝色的是水域，绿色的是树林。", "target_word": "水域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的水域不大，只有一个小湖。", "target_word": "水域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐船穿过了一片很宽的水域。", "target_word": "水域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天水域结冰，船就不能走了。", "target_word": "水域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片水域里住着很多鸟。", "target_word": "水域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把船开到了另一片水域。", "target_word": "水域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个水域太危险，大家不要去。", "target_word": "水域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河连着两片水域。", "target_word": "水域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人在水域边上住了一辈子。", "target_word": "水域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，水域的水位升高了。", "target_word": "水域", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "水域面积", "label": "复合"}], "register": "中性", "sense_fingerprint": "河湖海等水占的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd41bb3f0-444d-44a7-aecf-74c5fab366ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25594, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陆地", "is_correct": false, "explanation": "语义：地图上的陆地不是蓝色的，与“蓝色的是”矛盾。"}, {"text": "水域", "is_correct": true, "explanation": "“水域”是水占的地方，地图上常用蓝色标示，与“蓝色的是”相合。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠在地图上不是蓝色，颜色与句子不符。"}, {"text": "草地", "is_correct": false, "explanation": "语义：草地在地图上通常是绿色，不会标成蓝色，与“蓝色的是”矛盾。"}], "explanations": {"陆地": "语义：地图上的陆地不是蓝色的，与“蓝色的是”矛盾。", "水域": "“水域”是水占的地方，地图上常用蓝色标示，与“蓝色的是”相合。", "沙漠": "语义：沙漠在地图上不是蓝色，颜色与句子不符。", "草地": "语义：草地在地图上通常是绿色，不会标成蓝色，与“蓝色的是”矛盾。"}, "sentence_index": 0, "correct_answer": "水域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民在这片水域里种了小麦。", "explanation": "这里应该用〈土地〉。水域是水占的地方，不能种庄稼，种小麦要说土地。"}, {"text": "他在医学水域很有名。", "explanation": "这里应该用〈领域〉。水域指水占的地方，不指专业范围，专业范围要说领域。"}, {"text": "这块水域上停满了汽车。", "explanation": "这里应该用〈空地〉。水域是水占的地方，汽车不能停在水上，停车的地方要说空地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25594, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饼干", "is_correct": false, "explanation": "搭配：“饼干”不是能“去”的地方，与“去”搭配不通。"}, {"text": "水域", "is_correct": true, "explanation": "“水域”指水占的地方，可能有危险，所以“太危险，大家不要去”很合理。"}, {"text": "积木", "is_correct": false, "explanation": "搭配：“去”要求地点作宾语，积木不能作为去的地方。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“课本”不是地方，不能说“去”。"}], "explanations": {"饼干": "搭配：“饼干”不是能“去”的地方，与“去”搭配不通。", "水域": "“水域”指水占的地方，可能有危险，所以“太危险，大家不要去”很合理。", "积木": "搭配：“去”要求地点作宾语，积木不能作为去的地方。", "课本": "搭配：“课本”不是地方，不能说“去”。"}, "sentence_index": 6, "correct_answer": "水域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的水域很高，山顶常年有雪。", "explanation": "这里应该用〈海拔〉。水域指水占的地方，不能用来说山的高低，说山的高度要说海拔。"}, {"text": "他的英语水域很高。", "explanation": "这里应该用〈水平〉。水域指水占的地方，不能用来说能力高低；英语的高低要说水平。"}, {"text": "这个杯子的水域很大。", "explanation": "这里应该用〈容量〉。水域指水占的地方，杯子能装多少水要说容量，不能说水域很大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖边有一座很大的水域。", "corrected_sentence": "湖边有一片很大的水域。", "error_description": "水域的量词应用“片”，不能用“座”，“座”多用于山和建筑。这里应说“一片很大的水域”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多鸟儿生活在这座水域里。", "corrected_sentence": "很多鸟儿生活在这片水域里。", "error_description": "错在量词：“水域”应用“片”，不能用“座”，“座”多用于山和建筑。这里应说“这片水域里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
