INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25596, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "标称就是官方说一个东西应该有的数值。", "primary_collocate": null, "pronunciation": "biāo chēng", "ipa": "piɑʊ̯˥ ʈʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这个水壶的标称容量是两升。", "target_word": "标称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台水泵的标称流量写在铭牌上。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子上写着标称重量是五百克。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电视的标称尺寸是五十五寸。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实际的重量比标称重量少了一点。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电池的标称电压是一点五伏。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买这种灯泡，要看标称功率。", "target_word": "标称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "标称的数值不一定和实际一样。", "target_word": "标称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台冰箱的标称温度范围是零到八度。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在检查这台机器的标称转速。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "標稱", "label": "繁体"}, {"form": "标称值", "label": "复合"}], "register": "书面", "sense_fingerprint": "标称：官方或说明书上写明的东西应有的数值，如标称重量、标称尺寸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd41bb3f0-444d-44a7-aecf-74c5fab366ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标称", "is_correct": true, "explanation": "正确。这里指水壶说明上标明的容量，单位是升。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是容量，不能用来修饰“容量”。"}, {"text": "手柄", "is_correct": false, "explanation": "搭配：手柄是部件，不能说手柄容量。"}, {"text": "外观", "is_correct": false, "explanation": "体貌：外观说的是外形，与能装多少（容量）不是一回事。"}], "explanations": {"标称": "正确。这里指水壶说明上标明的容量，单位是升。", "颜色": "语义：颜色不是容量，不能用来修饰“容量”。", "手柄": "搭配：手柄是部件，不能说手柄容量。", "外观": "体貌：外观说的是外形，与能装多少（容量）不是一回事。"}, "sentence_index": 0, "correct_answer": "标称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用尺子量出来，这张书桌的标称宽度是六十厘米。", "explanation": "这里应该用〈实测〉。标称是规格或说明上标明的数值，自己量出来的宽度要说实测宽度。"}, {"text": "这本书的标称销量是五十万册。", "explanation": "这里应该用〈发行量〉。标称指规格或说明上标明的数值，书籍印了多少、卖出多少要说发行量。"}, {"text": "我今天的标称体重是六十公斤。", "explanation": "这里应该用〈体重〉。标称只用于产品或说明书上的数值，个人的体重要说体重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标称", "is_correct": true, "explanation": "正确。买灯泡要看说明上标明的功率。"}, {"text": "包装", "is_correct": false, "explanation": "语义：包装不是功率，不能用来修饰“功率”。"}, {"text": "灯罩", "is_correct": false, "explanation": "搭配：灯罩是灯的外壳部件，不说灯罩功率。"}, {"text": "形状", "is_correct": false, "explanation": "体貌：形状说的是外形，与功率无关。"}], "explanations": {"标称": "正确。买灯泡要看说明上标明的功率。", "包装": "语义：包装不是功率，不能用来修饰“功率”。", "灯罩": "搭配：灯罩是灯的外壳部件，不说灯罩功率。", "形状": "体貌：形状说的是外形，与功率无关。"}, "sentence_index": 6, "correct_answer": "标称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每月的标称收入是八千元。", "explanation": "这里应该用〈月薪〉。标称只用于产品、设备规格上的数值，个人每个月挣的钱要说月薪。"}, {"text": "这个城市的标称人口是两百万。", "explanation": "这里应该用〈常住人口〉。标称只用于产品、设备的规格，统计城市住了多少人要说常住人口。"}, {"text": "今天的标称气温是三十度。", "explanation": "这里应该用〈实测〉。标称指规格或说明上标明的数值，今天实际测到的温度不能说标称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个保温杯的标称容量是五百千克。", "corrected_sentence": "这个保温杯的标称容量是五百毫升。", "error_description": "错在单位：容量用毫升或升，“千克”是重量的单位，应说“五百毫升”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台风扇的标称功率是六十度。", "corrected_sentence": "这台风扇的标称功率是六十瓦。", "error_description": "错在单位：功率的单位是瓦，应说“六十瓦”；“度”不用于量功率。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de301d7-9712-4db6-aa33-f8b1f22d98a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
