INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25604, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以给机器下命令，让它做事情。", "primary_collocate": null, "pronunciation": "kě biān chéng", "ipa": "kʰɤ˨˩ pjɛn˥ ʈʂʰɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "我家有一个可编程的小机器人。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个玩具车是可编程的，你可以教它走路。", "target_word": "可编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥送我一台可编程的小火车。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个可编程的机器人会按你的命令跳舞。", "target_word": "可编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说可编程的机器可以帮人做很多事。", "target_word": "可编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台洗衣机不是可编程的，只能用一种方式洗。", "target_word": "可编程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课上玩可编程的小汽车。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "可编程的机器人能给我们送水。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买一个可编程的玩具，自己写命令。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种可编程的玩具狗会听你的命令。", "target_word": "可编程", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "可编程的", "label": "定语形式"}, {"form": "可編程", "label": "繁体"}], "register": "中性", "sense_fingerprint": "可给机器下命令让它做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93f1010e-ee55-4e33-9cf5-8af6804f420b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25604, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可编程", "is_correct": true, "explanation": "可编程指可以给机器下命令让它做事，与“小机器人”相符。"}, {"text": "可食用", "is_correct": false, "explanation": "语义：可食用指能当食物吃，机器人不能被吃，句子说不通。"}, {"text": "可溶的", "is_correct": false, "explanation": "语义：可溶指能溶解在液体里，与小机器人无关，句子不通。"}, {"text": "可燃的", "is_correct": false, "explanation": "语义：可燃指能被点燃，与小机器人的功能无关，句子不通。"}], "explanations": {"可编程": "可编程指可以给机器下命令让它做事，与“小机器人”相符。", "可食用": "语义：可食用指能当食物吃，机器人不能被吃，句子说不通。", "可溶的": "语义：可溶指能溶解在液体里，与小机器人无关，句子不通。", "可燃的": "语义：可燃指能被点燃，与小机器人的功能无关，句子不通。"}, "sentence_index": 0, "correct_answer": "可编程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只小猫真可编程。", "explanation": "这里应该用〈可爱〉。“可编程”指可以给机器下命令，只用于机器，不能用来形容小猫。"}, {"text": "这场台风十分可编程。", "explanation": "这里应该用〈可怕〉。“可编程”指可以给机器下命令，台风是自然现象，不能被下命令。"}, {"text": "他是个可编程的人。", "explanation": "这里应该用〈可靠〉。“可编程”指可以给机器下命令，用来形容人不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可编程", "is_correct": true, "explanation": "可编程指可以给机器下命令让它做事，与“小汽车”的语境相符。"}, {"text": "可过滤的", "is_correct": false, "explanation": "语义：可过滤指能用滤网分离杂质，与玩小汽车无关，句子不通。"}, {"text": "可加热的", "is_correct": false, "explanation": "语义：可加热指能放在火上加热，玩小汽车不需要加热，句子不通。"}, {"text": "可冷冻的", "is_correct": false, "explanation": "语义：可冷冻指能放进冰箱保存，与在课上玩小汽车无关，句子不通。"}], "explanations": {"可编程": "可编程指可以给机器下命令让它做事，与“小汽车”的语境相符。", "可过滤的": "语义：可过滤指能用滤网分离杂质，与玩小汽车无关，句子不通。", "可加热的": "语义：可加热指能放在火上加热，玩小汽车不需要加热，句子不通。", "可冷冻的": "语义：可冷冻指能放进冰箱保存，与在课上玩小汽车无关，句子不通。"}, "sentence_index": 6, "correct_answer": "可编程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个人的行踪可编程。", "explanation": "这里应该用〈可疑〉。“可编程”只用于能按命令设定功能的机器，不能说人的行踪。"}, {"text": "这笔收入可编程。", "explanation": "这里应该用〈可观〉。“可编程”指能设定功能，不能用来形容收入数量多。"}, {"text": "这次机会真可编程。", "explanation": "这里应该用〈可惜〉。“可编程”指能按命令设定功能，不表示遗憾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台遥控车很可编程，能按指令行驶。", "corrected_sentence": "这台遥控车可编程，能按指令行驶。", "error_description": "程度副词用错：“可编程”不能用“很”修饰，应直接说“这台遥控车可编程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器人已经可编程着。", "corrected_sentence": "这台机器人已经可编程了。", "error_description": "动态助词用错：“已经”表示动作或变化已经完成，要用“了”，不能用“着”。正确的说法是“这台机器人已经可编程了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
