INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25606, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指由同一微生物祖先繁殖得到的纯种微生物，科学家常用它来做实验。", "primary_collocate": null, "pronunciation": "jūn zhū", "ipa": "tɕyn˥ ʈʂu˥", "syllable_count": 2, "sentences": [{"text": "科学家用这个菌株做实验。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菌株太小了，只能用显微镜看。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说这个菌株很安全。", "target_word": "菌株", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "实验前，要先把菌株培养好。", "target_word": "菌株", "complexity_tier": "T3", "furigana": "jūn zhū", "sentence_source": "generated"}, {"text": "桌上的盒子里放着一个菌株。", "target_word": "菌株", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种菌株不会让人生病。", "target_word": "菌株", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学生们观察了菌株的变化。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天给菌株换新的培养液。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个菌株是实验室里最重要的材料。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菌株死了，实验只好重新做。", "target_word": "菌株", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个菌株", "label": "量词"}, {"form": "工程菌株", "label": "复合"}, {"form": "野生菌株", "label": "复合"}], "register": "书面", "sense_fingerprint": "由单一微生物繁殖得到、供实验用的纯种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f995feb-01f2-46a0-bd0f-015ea5999b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "菌株", "is_correct": true, "explanation": "正确：菌株是科学家做实验时使用的微小生物，与“做实验”相符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是做实验的材料，科学家不会用作业做实验。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事不是实验的材料，无法用来做实验。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“做实验”的对象应是实验材料，“礼物”与之不搭配。"}], "explanations": {"菌株": "正确：菌株是科学家做实验时使用的微小生物，与“做实验”相符。", "作业": "语义：作业不是做实验的材料，科学家不会用作业做实验。", "故事": "语义：故事不是实验的材料，无法用来做实验。", "礼物": "搭配：“做实验”的对象应是实验材料，“礼物”与之不搭配。"}, "sentence_index": 0, "correct_answer": "菌株"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厨房水槽的角落里长满了菌株。", "explanation": "这里应该用〈细菌〉。水槽角落里滋生的是一般细菌，菌株指从某一微生物中分离出的纯种，不能泛指。"}, {"text": "草地上长满了菌株。", "explanation": "这里应该用〈蘑菇〉。菌株是实验室里的微生物纯种，不指草地上长出的蘑菇。"}, {"text": "做面包要先把菌株揉成面团。", "explanation": "这里应该用〈面粉〉。菌株是微生物纯种，不能揉成面团；做面包要用面粉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "菌株", "is_correct": true, "explanation": "正确：菌株会随时间发生变化，学生可以观察到它的变化。"}, {"text": "圆周率", "is_correct": false, "explanation": "语义：圆周率是固定常数，没有可观察的“变化”，与“观察……的变化”不合。"}, {"text": "真理", "is_correct": false, "explanation": "语义：真理被视为确定不变的道理，不能说“观察真理的变化”。"}, {"text": "三角形内角和", "is_correct": false, "explanation": "语义：三角形内角和恒为180度，不会有变化可供观察。"}], "explanations": {"菌株": "正确：菌株会随时间发生变化，学生可以观察到它的变化。", "圆周率": "语义：圆周率是固定常数，没有可观察的“变化”，与“观察……的变化”不合。", "真理": "语义：真理被视为确定不变的道理，不能说“观察真理的变化”。", "三角形内角和": "语义：三角形内角和恒为180度，不会有变化可供观察。"}, "sentence_index": 6, "correct_answer": "菌株"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "衣柜里挂满了菌株。", "explanation": "这里应该用〈衣服〉。衣柜里挂的是衣服，菌株是微生物纯种，不能挂在衣柜里。"}, {"text": "汽车里坐满了菌株。", "explanation": "这里应该用〈乘客〉。汽车里坐的是乘客，菌株不是人，不能说“坐满”。"}, {"text": "海边的沙滩上堆着很多菌株。", "explanation": "这里应该用〈沙子〉。沙滩上堆的是沙子，菌株指纯种微生物，不能用来堆放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们把一只菌株放进了培养皿里。", "corrected_sentence": "同学们把一个菌株放进了培养皿里。", "error_description": "量词“只”用于动物，菌株应使用量词“个”，应为“一个菌株”，而不是“一只菌株”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们在培养皿里发现了一片新菌株。", "corrected_sentence": "学生们在培养皿里发现了一种新菌株。", "error_description": "量词“片”用于叶子、平面等，菌株应用“个”或“种”，此处应为“一种新菌株”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
