INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25614, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "酶是身体里帮助食物变成能量的神奇小帮手。", "primary_collocate": null, "pronunciation": "méi", "ipa": "mei˧˥", "syllable_count": 1, "sentences": [{"text": "酶是身体里的小帮手。", "target_word": "酶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "吃饭以后，酶帮我们消化食物。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "嘴巴里有酶，所以饭会越嚼越甜。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有酶，身体就很难把食物变成能量。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，酶像一个小工人。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酶能让食物变成身体需要的能量。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的肚子里有很多酶。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酶让身体里的变化变得很快。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在课上学了什么是酶。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛奶里的糖需要一种酶来分解。", "target_word": "酶", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种酶", "label": "量词"}, {"form": "消化酶", "label": "复合词"}], "register": "中性", "sense_fingerprint": "身体里帮助食物变成能量的小帮手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93f1010e-ee55-4e33-9cf5-8af6804f420b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25614, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "酶", "is_correct": true, "explanation": "正确：酶 méi，指身体里帮助消化的物质。"}, {"text": "每", "is_correct": false, "explanation": "měi（第三声）与 méi（第二声）声调不同，意思是每个。"}, {"text": "美", "is_correct": false, "explanation": "měi 与 méi 声调不同，意思是美丽。"}, {"text": "陪", "is_correct": false, "explanation": "péi 与 méi 声母不同，意思是陪伴。"}, {"text": "门", "is_correct": false, "explanation": "mén 与 méi 韵母不同，意思是门。"}], "explanations": {"酶": "正确：酶 méi，指身体里帮助消化的物质。", "每": "měi（第三声）与 méi（第二声）声调不同，意思是每个。", "美": "měi 与 méi 声调不同，意思是美丽。", "陪": "péi 与 méi 声母不同，意思是陪伴。", "门": "mén 与 méi 韵母不同，意思是门。"}, "sentence_index": null, "correct_answer": "酶"}, "level_3": {"options": [{"text": "酶", "is_correct": true, "explanation": "正确：酶是身体里帮助食物变成能量的小帮手，符合句意。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒会危害身体，与句中“小帮手”的意思相反。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷偷窃财物，不能是帮助身体的小帮手。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“身体里的”后面一般不接玩具，句意也说不通。"}], "explanations": {"酶": "正确：酶是身体里帮助食物变成能量的小帮手，符合句意。", "病毒": "语义：病毒会危害身体，与句中“小帮手”的意思相反。", "小偷": "语义：小偷偷窃财物，不能是帮助身体的小帮手。", "玩具": "搭配：“身体里的”后面一般不接玩具，句意也说不通。"}, "sentence_index": 0, "correct_answer": "酶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "实验室里买了一条酶。", "explanation": "这里应该用〈种〉。“条”用于细长的物品，酶是一类物质，应说“一种酶”。"}, {"text": "酶能帮助身体抵抗感冒。", "explanation": "这里应该用〈维生素〉。酶催化化学反应，抵抗感冒靠的是维生素。"}, {"text": "酶能让骨头变得坚硬。", "explanation": "这里应该用〈钙〉。酶参与化学反应，不能让骨头变硬，应说钙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25614, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "酶", "is_correct": true, "explanation": "正确：酶 méi，指身体里帮助消化的物质。"}, {"text": "妹", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）声调不同，意思是妹妹。"}, {"text": "萌", "is_correct": false, "explanation": "méng 与 méi 韵母不同，意思是萌发。"}, {"text": "镁", "is_correct": false, "explanation": "měi 与 méi 声调不同，意思是镁元素。"}], "explanations": {"酶": "正确：酶 méi，指身体里帮助消化的物质。", "妹": "mèi（第四声）与 méi（第二声）声调不同，意思是妹妹。", "萌": "méng 与 méi 韵母不同，意思是萌发。", "镁": "měi 与 méi 声调不同，意思是镁元素。"}, "sentence_index": null, "correct_answer": "酶"}, "level_3": {"options": [{"text": "酶", "is_correct": true, "explanation": "正确：肚子里有很多酶，符合句意。"}, {"text": "钱", "is_correct": false, "explanation": "语义：肚子里有很多钱说不通，句中说的是帮助消化的物质。"}, {"text": "头发", "is_correct": false, "explanation": "语义：肚子里有很多头发不合常理，句中说的是帮助消化的物质。"}, {"text": "石子", "is_correct": false, "explanation": "搭配：“肚子里”一般不说有很多石子，句意不合常理。"}], "explanations": {"酶": "正确：肚子里有很多酶，符合句意。", "钱": "语义：肚子里有很多钱说不通，句中说的是帮助消化的物质。", "头发": "语义：肚子里有很多头发不合常理，句中说的是帮助消化的物质。", "石子": "搭配：“肚子里”一般不说有很多石子，句意不合常理。"}, "sentence_index": 6, "correct_answer": "酶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "酶能让汽车跑得更快。", "explanation": "这里应该用〈汽油〉。酶是催化剂，只加快体内的化学反应，不能让汽车加速，汽车需要的是汽油。"}, {"text": "酶能切割金属。", "explanation": "这里应该用〈激光〉。酶是催化剂，不能切割金属，切割金属靠激光。"}, {"text": "酶能把纸粘在一起。", "explanation": "这里应该用〈胶水〉。酶是催化剂，不能粘合物体，把纸粘在一起要用胶水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "身体里有很多只酶。", "corrected_sentence": "身体里有很多种酶。", "error_description": "错误形式是“很多只酶”，正确形式是“很多种酶”。酶是一类物质，应用“种”；“只”不能用于酶。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "胃里的一只消化酶会分解蛋白质。", "corrected_sentence": "胃里的一种消化酶会分解蛋白质。", "error_description": "错误形式是“一只消化酶”，正确形式是“一种消化酶”。酶是一类物质，应用量词“种”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157f74-f3bf-40b1-bcb0-6967ea302dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
