INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25620, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放在某个地方。", "primary_collocate": null, "pronunciation": "zhì yú", "ipa": "ʈʂɨ⁵¹ y³⁵", "syllable_count": 2, "sentences": [{"text": "他把花瓶置于桌子中间。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把书包置于椅子上。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把茶杯置于窗边。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把蛋糕置于冰箱中。", "target_word": "置于", "complexity_tier": "T3", "furigana": "māma bǎ dàngāo zhìyú bīngxiāng zhōng", "sentence_source": "generated"}, {"text": "他将钥匙置于门口的盒子中。", "target_word": "置于", "complexity_tier": "T3", "furigana": "tā jiāng yàoshi zhìyú ménkǒu de hézi zhōng", "sentence_source": "generated"}, {"text": "工人把箱子置于墙角。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把手机置于桌上，不要带进考场。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把照片置于相框中。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把灯置于床头，晚上看书方便。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把药置于孩子拿不到的地方。", "target_word": "置于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "把具体物品放到某个具体地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f995feb-01f2-46a0-bd0f-015ea5999b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "置于", "is_correct": true, "explanation": "正确。“置于”表示把花瓶放到桌子中间，符合语境。"}, {"text": "贴在", "is_correct": false, "explanation": "语义：“贴”指粘附在平面上，花瓶不能被贴在桌子中间。"}, {"text": "倒在", "is_correct": false, "explanation": "语义：“倒”指液体或散物倾出，花瓶不能被倒在桌子中间。"}, {"text": "堆在", "is_correct": false, "explanation": "配价：“堆”需要多件物品成堆，单个花瓶不能堆在桌子中间。"}], "explanations": {"置于": "正确。“置于”表示把花瓶放到桌子中间，符合语境。", "贴在": "语义：“贴”指粘附在平面上，花瓶不能被贴在桌子中间。", "倒在": "语义：“倒”指液体或散物倾出，花瓶不能被倒在桌子中间。", "堆在": "配价：“堆”需要多件物品成堆，单个花瓶不能堆在桌子中间。"}, "sentence_index": 0, "correct_answer": "置于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把礼物置于朋友。", "explanation": "这里应该用〈送给〉。置于指把物品放在某个地点，朋友不是放置的处所，应说送给。"}, {"text": "老师把作业置于学生。", "explanation": "这里应该用〈交给〉。置于指放在某个地点，人不能作为放置的处所，作业要交给学生。"}, {"text": "妈妈把包裹置于邻居。", "explanation": "这里应该用〈转交〉。置于指放置物品，把东西交到他人手中应说转交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "置于", "is_correct": true, "explanation": "正确。“置于”表示把手机放到桌上，符合请求语境。"}, {"text": "塞进", "is_correct": false, "explanation": "语义：“塞进”要求有容器，桌面不能被“塞进”。"}, {"text": "摔在", "is_correct": false, "explanation": "语域：“摔”带有粗暴动作的色彩，不符合请求放置物品的语境。"}, {"text": "挂在", "is_correct": false, "explanation": "搭配：“挂”接钩子、墙壁等，桌上不能用“挂在”。"}], "explanations": {"置于": "正确。“置于”表示把手机放到桌上，符合请求语境。", "塞进": "语义：“塞进”要求有容器，桌面不能被“塞进”。", "摔在": "语域：“摔”带有粗暴动作的色彩，不符合请求放置物品的语境。", "挂在": "搭配：“挂”接钩子、墙壁等，桌上不能用“挂在”。"}, "sentence_index": 6, "correct_answer": "置于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他总把这句话置于嘴边。", "explanation": "这里应该用〈挂在〉。置于指把具体物品放到具体地点，嘴边不是可放置物品的地点，这种说法应说挂在嘴边。"}, {"text": "他从不把别人置于眼里。", "explanation": "这里应该用〈放在〉。置于用于具体地点，对人的看法要说放在眼里。"}, {"text": "他把这次演讲置于下个星期。", "explanation": "这里应该用〈安排在〉。置于指把事物放在某个位置或状态，时间安排要说安排在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把笔记本置于在书架的最上层。", "corrected_sentence": "她把笔记本置于书架的最上层。", "error_description": "“置于”已含介词“于”，其后不能再接“在”，属于于、在重复。应说“置于书架的最上层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那袋大米置于着厨房的角落。", "corrected_sentence": "他把那袋大米置于厨房的角落。", "error_description": "“置于”后不能直接接动态助词“着”，应说“他把那袋大米置于厨房的角落”。“置于”是书面动词，“着”不能紧跟其后，应删去“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
