INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25622, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里像管道一样的东西，血液在里面流来流去。", "primary_collocate": null, "pronunciation": "xún huán xì tǒng", "ipa": "ɕyn˧˥ xwan˧˥ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "身体里的循环系统像水管一样。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "血液在循环系统里不停地流。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我的循环系统很健康。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们画了人的循环系统。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "循环系统里的血流得很快。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用图给孩子讲循环系统。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道循环系统在身体的哪里吗？", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "循环系统要是堵住了，人会生病。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步以后，循环系统工作得更快。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，循环系统遍布全身。", "target_word": "循环系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "血液循环系统", "label": "复合"}], "register": "口语", "sense_fingerprint": "身体里像管道、让血液流动的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7833e8da-174d-473c-8fad-ba990596ff35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "循环系统", "is_correct": true, "explanation": "“身体里的循环系统”指身体里像水管一样输送血液的部分，句意成立。"}, {"text": "书架", "is_correct": false, "explanation": "语义：书架是家具，不是身体里像水管一样的东西，句子说不通。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘挂在窗前，不会出现在身体里，与“身体里的”相冲突。"}, {"text": "篮球", "is_correct": false, "explanation": "搭配：“身体里的”后不能接球类，篮球不是身体内部的结构。"}], "explanations": {"循环系统": "“身体里的循环系统”指身体里像水管一样输送血液的部分，句意成立。", "书架": "语义：书架是家具，不是身体里像水管一样的东西，句子说不通。", "窗帘": "语义：窗帘挂在窗前，不会出现在身体里，与“身体里的”相冲突。", "篮球": "搭配：“身体里的”后不能接球类，篮球不是身体内部的结构。"}, "sentence_index": 0, "correct_answer": "循环系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈买了一本循环系统。", "explanation": "这里不能用〈本〉。“本”计量书籍；循环系统指身体里像管道一样的结构，应该用〈套〉。"}, {"text": "循环系统每分钟呼吸十几次。", "explanation": "这里应该用〈肺〉。呼吸是肺的功能，循环系统负责输送血液，不能“呼吸”。"}, {"text": "他的循环系统昨天跑去踢足球了。", "explanation": "〈循环系统〉指身体里像管道一样的结构，不是人，不能去踢足球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "循环系统", "is_correct": true, "explanation": "“你知道循环系统在身体的哪里吗”问的是循环系统位于身体的什么位置，句子成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是身体的部件，问它“在身体的哪里”没有意义。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不会位于身体内部，句子不通。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：“在身体的哪里”一般接身体部位或器官，电话不能作为身体内部的部件。"}], "explanations": {"循环系统": "“你知道循环系统在身体的哪里吗”问的是循环系统位于身体的什么位置，句子成立。", "天气": "语义：天气不是身体的部件，问它“在身体的哪里”没有意义。", "冰箱": "语义：冰箱是家电，不会位于身体内部，句子不通。", "电话": "搭配：“在身体的哪里”一般接身体部位或器官，电话不能作为身体内部的部件。"}, "sentence_index": 6, "correct_answer": "循环系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都去循环系统里游泳。", "explanation": "〈循环系统〉是身体内部的结构，不能作为游泳的场所，“去……里游泳”的地点应是水池或水域。"}, {"text": "妈妈用循环系统切菜。", "explanation": "〈循环系统〉指身体里输送血液的结构，不是厨房用具，不能用来切菜。"}, {"text": "他把循环系统挂在墙上当装饰。", "explanation": "〈循环系统〉是身体内部的结构，不能被挂在墙上当装饰品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个人得循环系统很健康。", "corrected_sentence": "这个人的循环系统很健康。", "error_description": "错误：“得”；正确：“的”。“得”是补语标志，修饰名词时要用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "身体里有一把循环系统。", "corrected_sentence": "身体里有一套循环系统。", "error_description": "错误：“一把”；正确：“一套”。循环系统是成套的器官系统，应用量词“套”，“把”用于有柄的器具。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25623, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25623, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25623, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "解药是能让人不再生病或中毒的药。", "primary_collocate": null, "pronunciation": "jiě yào", "ipa": "tɕjɛ˨˩˦ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "小明喝错了东西，要快点吃解药。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶是解药，那瓶是毒药。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "解药在医生手里，他正在给病人用。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃了解药以后，他不难受了。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "故事里的公主喝了毒水，王子去找解药。", "target_word": "解药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种毒很少见，医院里没有解药。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他中毒了，必须马上找到解药。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "解药很贵，一小瓶要一千块钱。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有中毒的人不要乱吃解药。", "target_word": "解药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗吃了有毒的东西，医生给它打了解药。", "target_word": "解药", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一瓶解药", "label": "量词"}, {"form": "一剂解药", "label": "量词"}, {"form": "解藥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "中毒或生病后吃的、能让人好起来的药", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58fcc8cb-7a7f-4d32-9843-a69e1fc8fe4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25623, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毒药", "is_correct": false, "explanation": "语义：吃毒药会加重中毒，与“快点吃”让人好起来的目的相反。"}, {"text": "解药", "is_correct": true, "explanation": "正确：“小明喝错了东西，要快点吃解药”符合语境，“解药”能让人不再中毒。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不能解除喝错东西带来的中毒，与急救语境不符。"}, {"text": "毒蘑菇", "is_correct": false, "explanation": "搭配：“快点吃”后接的应是能帮助康复的东西，“毒蘑菇”是有害之物，不搭配这种急救用法。"}], "explanations": {"毒药": "语义：吃毒药会加重中毒，与“快点吃”让人好起来的目的相反。", "解药": "正确：“小明喝错了东西，要快点吃解药”符合语境，“解药”能让人不再中毒。", "饼干": "语义：饼干不能解除喝错东西带来的中毒，与急救语境不符。", "毒蘑菇": "搭配：“快点吃”后接的应是能帮助康复的东西，“毒蘑菇”是有害之物，不搭配这种急救用法。"}, "sentence_index": 0, "correct_answer": "解药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜要放点解药才好吃。", "explanation": "这里应该用〈调料〉。调料用于调味；解药指能让人不再生病或中毒的药，不用来给菜调味。"}, {"text": "头发油，用解药洗一洗。", "explanation": "这里应该用〈洗发水〉。洗发水用于清洁头发；解药指能让人不再生病或中毒的药，不用来洗头。"}, {"text": "打了解药以后，他不容易生病了。", "explanation": "这里应该用〈疫苗〉。疫苗用于预防，解药用于在中毒或生病后让人好起来，不用于预防。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25623, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纸牌", "is_correct": false, "explanation": "语义：纸牌不能解除中毒，“必须马上找到”纸牌救治不了中毒的人，句意不通。"}, {"text": "解药", "is_correct": true, "explanation": "正确：“他中毒了，必须马上找到解药”符合语境，“解药”能让中毒的人好起来。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不能解毒，与中毒急需救治的语境不符。"}, {"text": "谎言", "is_correct": false, "explanation": "搭配：“找到”后接“谎言”不成立，应说“揭穿谎言”，不说“找到谎言”。"}], "explanations": {"纸牌": "语义：纸牌不能解除中毒，“必须马上找到”纸牌救治不了中毒的人，句意不通。", "解药": "正确：“他中毒了，必须马上找到解药”符合语境，“解药”能让中毒的人好起来。", "课本": "语义：课本不能解毒，与中毒急需救治的语境不符。", "谎言": "搭配：“找到”后接“谎言”不成立，应说“揭穿谎言”，不说“找到谎言”。"}, "sentence_index": 6, "correct_answer": "解药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人每天要吃解药，身体才好。", "explanation": "这里应该用〈维生素〉。维生素用于补充营养，解药用于解除毒性或疾病的作用，不用于日常补充营养。"}, {"text": "手术前，护士给他注射解药。", "explanation": "这里应该用〈麻醉剂〉。麻醉剂用于手术前使人暂时失去知觉；解药用于解毒，不用于手术麻醉。"}, {"text": "他很累，喝了解药就精神了。", "explanation": "这里应该用〈提神饮料〉。提神饮料用于让人振作、消除疲劳；解药指能让人不再生病或中毒的药，疲劳不是病，不用来提神。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他误吞了毒药，医生正在给他一根解药。", "corrected_sentence": "他误吞了毒药，医生正在给他一粒解药。", "error_description": "量词错误：“根”用于细长的东西，解药是药片或药丸，应说“一粒解药”，不说“一根解药”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子误服了毒，医院马上送来一把解药。", "corrected_sentence": "孩子误服了毒，医院马上送来一剂解药。", "error_description": "量词错误：解药应用“剂”“粒”等，“把”用于有柄的东西，不说“一把解药”。目标词“解药”的量词用错了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
