INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25626, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情时用掉的能量。", "primary_collocate": null, "pronunciation": "néng hào", "ipa": "nɤŋ˧˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "跑步的能耗比走路大。", "target_word": "能耗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "手机玩游戏时，能耗很大。", "target_word": "能耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天人体的能耗会增加。", "target_word": "能耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小风扇能耗很低，用一天只要一度电。", "target_word": "能耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机和电视，哪个能耗更高？", "target_word": "能耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车慢一点，能耗会少一些。", "target_word": "能耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天运动，身体的能耗比较高。", "target_word": "能耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡觉时人的能耗最小。", "target_word": "能耗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电脑开着不用，也有能耗。", "target_word": "能耗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家换了新灯泡，能耗少了一半。", "target_word": "能耗", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "低能耗", "label": "复合"}, {"form": "高能耗", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事或使用东西时用掉的能量多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58fcc8cb-7a7f-4d32-9843-a69e1fc8fe4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25626, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能耗", "is_correct": true, "explanation": "正确：跑步比走路消耗的能量多，“跑步的能耗比走路大”符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“比…大”用于比较数量或程度，颜色不能用这种格式来比较。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历指受教育程度，与跑步和走路的比较无关，放在这里说不通。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数是文字的数量，不是跑步的属性，放在这里说不通。"}], "explanations": {"能耗": "正确：跑步比走路消耗的能量多，“跑步的能耗比走路大”符合句意。", "颜色": "搭配：“比…大”用于比较数量或程度，颜色不能用这种格式来比较。", "学历": "语义：学历指受教育程度，与跑步和走路的比较无关，放在这里说不通。", "字数": "语义：字数是文字的数量，不是跑步的属性，放在这里说不通。"}, "sentence_index": 0, "correct_answer": "能耗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天的能耗很充沛，跑了五公里还不累。", "explanation": "这里应该用〈能量〉。能耗指消耗掉的能量，“充沛”形容的是拥有的体力或能量，不能用来形容能耗。"}, {"text": "这个风扇的能耗很快，屋里很快就凉快了。", "explanation": "这里应该用〈风速〉。能耗指消耗的能量，“快”形容的是风速，不能用来形容能耗。"}, {"text": "这台风扇的能耗很长，用了十年还能转。", "explanation": "这里应该用〈寿命〉。能耗指消耗掉的能量，“长”形容的是使用时间，不能用来形容能耗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "能耗", "is_correct": true, "explanation": "正确：运动越多，身体消耗的能量越多，“身体的能耗比较高”符合句意。"}, {"text": "词汇量", "is_correct": false, "explanation": "语义：词汇量指掌握的词的数量，与运动无关，不能说“身体的词汇量比较高”。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“音量”指声音的大小，身体不能说“音量比较高”。"}, {"text": "篇幅", "is_correct": false, "explanation": "语义：篇幅指文章或内容的长短，不能用来形容身体。"}], "explanations": {"能耗": "正确：运动越多，身体消耗的能量越多，“身体的能耗比较高”符合句意。", "词汇量": "语义：词汇量指掌握的词的数量，与运动无关，不能说“身体的词汇量比较高”。", "音量": "搭配：“音量”指声音的大小，身体不能说“音量比较高”。", "篇幅": "语义：篇幅指文章或内容的长短，不能用来形容身体。"}, "sentence_index": 6, "correct_answer": "能耗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼的能耗很充足，夏天不怕停电。", "explanation": "这里应该用〈电量〉。能耗指消耗的量，“充足”形容的是供应的量，不能说“能耗充足”。"}, {"text": "这位老人的能耗很强，跑步很快。", "explanation": "这里应该用〈体力〉。能耗指消耗的能量，不能用来形容人的体力，“很强”说的是体力。"}, {"text": "这台音箱的能耗很响，屋里都听得见。", "explanation": "这里应该用〈声音〉。能耗指消耗的能量，“响”形容的是声音的大小，不能用来形容能耗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25626, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "换了节能灯以后，我家的能耗降起来了。", "corrected_sentence": "换了节能灯以后，我家的能耗降下来了。", "error_description": "补语错误：“降起来”应为“降下来”。“降”表示数量减少，要用补语“下来”；“起来”表示开始并持续，不能用来表示能耗减少。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25626, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经把能耗降低。", "corrected_sentence": "我们已经把能耗降低了。", "error_description": "语法错误：“已经”表示动作已经完成，“把”字句的谓语后要带“了”，应说“我们已经把能耗降低了”，不能说“我们已经把能耗降低”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
