INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25630, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "用起来好不好用。", "primary_collocate": null, "pronunciation": "shǐ yòng xìng néng", "ipa": "ʂɻ̩˨˩˦ jʊŋ˥˩ ɕiŋ˥˩ nɤŋ˧˥", "syllable_count": 4, "sentences": [{"text": "买手机前，我先看它的使用性能。", "target_word": "使用性能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把雨伞的使用性能很不错。", "target_word": "使用性能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友说这台洗衣机使用性能很好。", "target_word": "使用性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格不高，使用性能也不差。", "target_word": "使用性能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种杯子的使用性能让我很满意。", "target_word": "使用性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新键盘的使用性能比旧的好多了。", "target_word": "使用性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房用品的使用性能最重要。", "target_word": "使用性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这辆自行车的使用性能不太满意。", "target_word": "使用性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个锅的使用性能差别很大。", "target_word": "使用性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人更看重家电的使用性能。", "target_word": "使用性能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "东西用起来好不好用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58fcc8cb-7a7f-4d32-9843-a69e1fc8fe4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使用性能", "is_correct": true, "explanation": "正确：买手机前看“使用性能”，指用起来好不好用，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高形容人的外形，手机不能用“身高”来描述。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历指受教育程度，与买手机无关，放在这里说不通。"}, {"text": "情绪", "is_correct": false, "explanation": "语义：情绪属于心理状态，手机没有情绪，放在这里说不通。"}], "explanations": {"使用性能": "正确：买手机前看“使用性能”，指用起来好不好用，符合句意。", "身高": "体貌：身高形容人的外形，手机不能用“身高”来描述。", "学历": "语义：学历指受教育程度，与买手机无关，放在这里说不通。", "情绪": "语义：情绪属于心理状态，手机没有情绪，放在这里说不通。"}, "sentence_index": 0, "correct_answer": "使用性能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把伞的使用性能很漂亮。", "explanation": "这里应该用〈外观〉。使用性能指东西用起来的效果，“漂亮”形容的是外观。"}, {"text": "这个包的使用性能很贵。", "explanation": "这里应该用〈价格〉。使用性能说的是好不好用，“贵”形容的是价格。"}, {"text": "这台洗衣机的使用性能很小，半夜用也不吵。", "explanation": "这里应该用〈噪音〉。使用性能指产品用起来的效果，“很小”和“不吵”说的是噪音，不能用来形容使用性能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使用性能", "is_correct": true, "explanation": "正确：厨房用品最看重实际用起来好不好，“使用性能最重要”符合句意。"}, {"text": "肤色", "is_correct": false, "explanation": "体貌：肤色是人或动物的外表特征，厨房用品没有肤色。"}, {"text": "人数", "is_correct": false, "explanation": "语义：人数指人的数量，不是厨房用品的属性，放在这里说不通。"}, {"text": "辈分", "is_correct": false, "explanation": "语义：辈分指家族中的世代次序，厨房用品没有辈分，放在这里说不通。"}], "explanations": {"使用性能": "正确：厨房用品最看重实际用起来好不好，“使用性能最重要”符合句意。", "肤色": "体貌：肤色是人或动物的外表特征，厨房用品没有肤色。", "人数": "语义：人数指人的数量，不是厨房用品的属性，放在这里说不通。", "辈分": "语义：辈分指家族中的世代次序，厨房用品没有辈分，放在这里说不通。"}, "sentence_index": 6, "correct_answer": "使用性能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人的使用性能很强，跑步很快。", "explanation": "这里应该用〈体力〉。使用性能指产品用起来的效果，不能用来形容人的身体力量。"}, {"text": "这个牌子的使用性能很有名。", "explanation": "这里应该用〈品牌〉。使用性能说的是效果，“有名”形容的是品牌。"}, {"text": "这台家电的使用性能很重，搬起来很费劲。", "explanation": "这里应该用〈重量〉。使用性能指产品用起来的效果，“很重”和“搬起来很费劲”说的是重量，不能用来形容使用性能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把剪刀的使用性能好很。", "corrected_sentence": "这把剪刀的使用性能很好。", "error_description": "语序错误：“好很”应为“很好”。“很”是修饰形容词的程度副词，要放在“好”的前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把这台吸尘器的使用性能改进。", "corrected_sentence": "妈妈把这台吸尘器的使用性能改进了。", "error_description": "语法错误：“把”字句的谓语“改进”后要带“了”等成分，表示动作完成。应说“妈妈把这台吸尘器的使用性能改进了”，不能说“妈妈把这台吸尘器的使用性能改进”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
