INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25632, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西拿出来。", "primary_collocate": null, "pronunciation": "tí qǔ", "ipa": "tʰi˧˥ tɕʰy˨˩", "syllable_count": 2, "sentences": [{"text": "我去银行提取了五百块钱。", "target_word": "提取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请带好身份证来提取行李。", "target_word": "提取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从卡里提取了一点现金。", "target_word": "提取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以在机场提取你的行李。", "target_word": "提取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个机器可以提取现金。", "target_word": "提取", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从保险箱里提取了一份文件。", "target_word": "提取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忘了密码，无法提取存款。", "target_word": "提取", "complexity_tier": "T3", "furigana": "wǒ wàng le mì mǎ, wú fǎ tí qǔ cún kuǎn", "sentence_source": "generated"}, {"text": "他到仓库提取了三箱东西。", "target_word": "提取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要先输入密码，再提取现金。", "target_word": "提取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "取款机一次只能提取两千块。", "target_word": "提取", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "提取了", "label": "体标"}, {"form": "提取过", "label": "体标"}, {"form": "提取出来", "label": "复合"}], "register": "中性", "sense_fingerprint": "从银行、仓库、机器或文件等存放的地方把钱或东西取出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d8b840b-ee01-4694-9784-5eb6724c58e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25632, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提取", "is_correct": true, "explanation": "“提取”：从银行取出钱，与“银行”和“五百块钱”相符。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”说水平、质量，不能说“提高五百块钱”。"}, {"text": "提醒", "is_correct": false, "explanation": "语义：“提醒”是使人想起某事，不能用于取钱。"}, {"text": "提拔", "is_correct": false, "explanation": "配价：“提拔”的对象须是人，不能以“五百块钱”为宾语。"}], "explanations": {"提取": "“提取”：从银行取出钱，与“银行”和“五百块钱”相符。", "提高": "搭配：“提高”说水平、质量，不能说“提高五百块钱”。", "提醒": "语义：“提醒”是使人想起某事，不能用于取钱。", "提拔": "配价：“提拔”的对象须是人，不能以“五百块钱”为宾语。"}, "sentence_index": 0, "correct_answer": "提取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中提取了第一名。", "explanation": "这里应该用〈取得〉。“提取”指把存放的钱或东西拿出来，名次、成绩要用“取得”。"}, {"text": "公司临时提取了这次会议。", "explanation": "这里应该用〈取消〉。“提取”只能用于存放的东西，会议、计划要用“取消”。"}, {"text": "学校为优秀学生提取了一场比赛。", "explanation": "这里应该用〈举办〉。“提取”指从存放的地方拿出东西，比赛要用“举办”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25632, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提取", "is_correct": true, "explanation": "“提取”：从存款中取出钱，与“存款”和“无法”的语境相符。"}, {"text": "输入", "is_correct": false, "explanation": "搭配：“输入”用于密码、数据，不能说“输入存款”。"}, {"text": "观看", "is_correct": false, "explanation": "语义：“观看”指看视频、比赛，与“存款”不搭。"}, {"text": "倾听", "is_correct": false, "explanation": "配价：“倾听”的对象须是人或声音，不能以“存款”为宾语。"}], "explanations": {"提取": "“提取”：从存款中取出钱，与“存款”和“无法”的语境相符。", "输入": "搭配：“输入”用于密码、数据，不能说“输入存款”。", "观看": "语义：“观看”指看视频、比赛，与“存款”不搭。", "倾听": "配价：“倾听”的对象须是人或声音，不能以“存款”为宾语。"}, "sentence_index": 6, "correct_answer": "提取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校提取了三百名新生。", "explanation": "这里应该用〈录取〉。“提取”只用于存放的东西，不能用于人，招收学生要用“录取”。"}, {"text": "他提取了自己的错误。", "explanation": "这里应该用〈承认〉。“提取”用于可以拿出来的东西，不能用于错误，表示接受错误要用“承认”。"}, {"text": "领导提取了这次会议的气氛。", "explanation": "这里应该用〈营造〉。“提取”只用于能拿出来的东西，会议气氛要用“营造”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在机场提取三件行李。", "corrected_sentence": "我昨天在机场提取了三件行李。", "error_description": "漏掉了动态助词“了”。表示已完成的过去动作，要在“提取”后加“了”，应说“昨天在机场提取了三件行李”；漏掉“了”，句子就不能表示已完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在柜台提取很快。", "corrected_sentence": "他在柜台提取得很快。", "error_description": "补语标记“得”漏掉了。“很快”是状态补语，要用“得”连接到动词后，应说“提取得很快”；漏掉“得”，“提取很快”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
