INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25638, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政府定的规则和法律，大家都要遵守。", "primary_collocate": null, "pronunciation": "zhèng cè fǎ guī", "ipa": "tʂɤŋ˥˩ tsʰɤ˥˩ fa˨˩˦ kweɪ˥", "syllable_count": 4, "sentences": [{"text": "在这个国家生活，要遵守政策法规。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，开店前要先看政策法规。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不懂政策法规，生意很容易出问题。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位记者经常写关于政策法规的文章。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府公布了新的政策法规，大家都在讨论。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车、交税都有政策法规，不能随便做。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司有专人负责研究政策法规。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国人来这里工作，要先学政策法规。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为不知道政策法规，所以交了罚款。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个市民都应该了解基本的政策法规。", "target_word": "政策法规", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套政策法规", "label": "量词"}, {"form": "政策法規", "label": "繁体"}], "register": "书面", "sense_fingerprint": "政府规定的、人人必须遵守的规则和法律", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499dcf25-efda-40b6-ac5d-8424935f606b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25638, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政策法规", "is_correct": true, "explanation": "正确：“遵守”的对象是政府规定的规则和法律，“政策法规”正合适。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“遵守”后应接规则、制度，不能接“手机”这类物品。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是人需要遵守的规定。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“遵守”不能接“口味”，口味不是可以遵守的对象。"}], "explanations": {"政策法规": "正确：“遵守”的对象是政府规定的规则和法律，“政策法规”正合适。", "手机": "搭配：“遵守”后应接规则、制度，不能接“手机”这类物品。", "天气": "语义：天气是自然现象，不是人需要遵守的规定。", "口味": "搭配：“遵守”不能接“口味”，口味不是可以遵守的对象。"}, "sentence_index": 0, "correct_answer": "政策法规"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家的政策法规规定晚上十点睡觉。", "explanation": "这里应该用〈家规〉。政策法规指政府制定的规则和法律，家庭内部的规定不说政策法规。"}, {"text": "他做事的政策法规是诚实守信。", "explanation": "这里应该用〈原则〉。政策法规指政府定的规则和法律，个人做事的准则不能说政策法规。"}, {"text": "这个村的政策法规是每年春节包饺子。", "explanation": "这里应该用〈习俗〉。政策法规是政府制定的规定，村里的习惯不能说政策法规。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政策法规", "is_correct": true, "explanation": "正确：“负责研究”的对象是规定和法律，“政策法规”符合语境。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“负责研究”不能搭配“午饭”，午饭不是可以研究的对象。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是个人的日子，不是需要专人研究的规定或资料。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步不是需要专人研究的对象，放入句中句意不通。"}], "explanations": {"政策法规": "正确：“负责研究”的对象是规定和法律，“政策法规”符合语境。", "午饭": "搭配：“负责研究”不能搭配“午饭”，午饭不是可以研究的对象。", "生日": "语义：生日是个人的日子，不是需要专人研究的规定或资料。", "脚步": "语义：脚步不是需要专人研究的对象，放入句中句意不通。"}, "sentence_index": 6, "correct_answer": "政策法规"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的政策法规很详细。", "explanation": "这里应该用〈说明书〉。政策法规指法律规范，机器的操作说明不能说政策法规。"}, {"text": "他每天练习的政策法规很难。", "explanation": "这里应该用〈曲子〉。政策法规指法律规范，练习的乐曲不能说政策法规。"}, {"text": "我们班的政策法规是每周更新一次。", "explanation": "这里应该用〈板报〉。政策法规是政府制定的规定，班里的板报不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要认真遵守这把政策法规。", "corrected_sentence": "我们要认真遵守这套政策法规。", "error_description": "量词错误：“政策法规”应用“套”计量（一套政策法规），“把”用于有柄的东西，不能用来计量政策法规。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司这块政策法规需要更新。", "corrected_sentence": "我们公司这套政策法规需要更新。", "error_description": "量词错误：“政策法规”应用“套”计量（一套政策法规），“块”用于成块的东西，不能用来计量政策法规。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
