INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25639, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不要的东西扔掉或不再用了。", "primary_collocate": null, "pronunciation": "fèi qì", "ipa": "fei˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "这些废弃的旧衣服可以送人。", "target_word": "废弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把废弃的箱子扔了。", "target_word": "废弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有一个废弃的小房子。", "target_word": "废弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他废弃了坏掉的手机。", "target_word": "废弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆车坏了，早就废弃不用了。", "target_word": "废弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河边有很多废弃的瓶子。", "target_word": "废弃", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校废弃了旧桌子，换上新的。", "target_word": "废弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要随便废弃还能用的东西。", "target_word": "废弃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把废弃的纸盒收集起来。", "target_word": "废弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条废弃的路没有人走。", "target_word": "废弃", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "废弃了", "label": "体标"}, {"form": "废弃物", "label": "复合"}, {"form": "廢棄", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把不要的东西扔掉或不再使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f995feb-01f2-46a0-bd0f-015ea5999b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25639, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废弃", "is_correct": true, "explanation": "正确：“废弃”作定语修饰“旧衣服”，指不要的旧衣服，语境相符。"}, {"text": "崭新", "is_correct": false, "explanation": "语义：“崭新”指全新的，与“旧衣服”矛盾。"}, {"text": "锋利", "is_correct": false, "explanation": "语义：“锋利”说刀具的刃口，不能修饰衣服。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容体型或外形，不用来说衣服的状态。"}], "explanations": {"废弃": "正确：“废弃”作定语修饰“旧衣服”，指不要的旧衣服，语境相符。", "崭新": "语义：“崭新”指全新的，与“旧衣服”矛盾。", "锋利": "语义：“锋利”说刀具的刃口，不能修饰衣服。", "高大": "体貌：“高大”形容体型或外形，不用来说衣服的状态。"}, "sentence_index": 0, "correct_answer": "废弃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个哭着找妈妈的孩子，他也废弃了。", "explanation": "“废弃”用于物品，不用于人；说人要用〈抛弃〉。"}, {"text": "他废弃了这支笔，只是暂时放一放，过几天还要用。", "explanation": "这里应该用〈搁置〉。废弃指永久不再用，“暂时放一放、过几天还要用”与之矛盾；暂时不用应说搁置。"}, {"text": "他把这个问题废弃了，然后又开始研究它。", "explanation": "这里应该用〈搁置〉。废弃是不再考虑，“又开始研究”与之矛盾；暂时放下、之后还要处理的问题应说搁置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25639, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废弃", "is_correct": true, "explanation": "正确：“学校废弃了旧桌子，换上新的”指不再使用旧桌子，语境相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赏识美好的事物，与“换上新的”的处理方式不合。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能支配“桌子”，不能说“唱旧桌子”。"}, {"text": "吞", "is_correct": false, "explanation": "搭配：“吞”只能接可以吞食的东西，桌子不能吞。"}], "explanations": {"废弃": "正确：“学校废弃了旧桌子，换上新的”指不再使用旧桌子，语境相符。", "欣赏": "语义：“欣赏”指赏识美好的事物，与“换上新的”的处理方式不合。", "唱": "搭配：“唱”不能支配“桌子”，不能说“唱旧桌子”。", "吞": "搭配：“吞”只能接可以吞食的东西，桌子不能吞。"}, "sentence_index": 6, "correct_answer": "废弃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他废弃了老朋友，只和新朋友玩。", "explanation": "“废弃”用于物品，不用于人；说人要用〈疏远〉或〈抛弃〉。"}, {"text": "他废弃了这辆车，然后又开着它去上班。", "explanation": "这里应该用〈保留〉。废弃是不要了，后文又开车去上班，前后矛盾；仍要使用的车应说保留。"}, {"text": "他把这个好主意废弃了，决定马上去做。", "explanation": "这里应该用〈采纳〉。废弃是不要了，与“决定马上去做”矛盾；好主意应说采纳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小朋友不应该随便废弃了玩具。", "corrected_sentence": "小朋友不应该随便废弃玩具。", "error_description": "“不应该”表示道理上的要求，不能与完成体“了”同用；应说“不应该随便废弃玩具”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25639, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子早就废弃用了。", "corrected_sentence": "这间屋子早就废弃不用了。", "error_description": "“废弃”后要说“废弃不用”，缺少“不”；“废弃用了”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
