INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25642, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西变成像石头一样硬，里面有矿物。", "primary_collocate": null, "pronunciation": "kuàng huà", "ipa": "kʰwɑŋ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "这棵树倒在水里，几千年后矿化了。", "target_word": "矿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一块矿化的木头。", "target_word": "矿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骨头矿化以后，摸起来像石头。", "target_word": "矿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条鱼的化石已经完全矿化了。", "target_word": "矿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "矿化的贝壳又硬又重。", "target_word": "矿化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老树根在地下矿化成了石头。", "target_word": "矿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块矿化的骨头很硬。", "target_word": "矿化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木棍埋在含矿物质很多的水里，会慢慢矿化。", "target_word": "矿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头矿化后不容易烂。", "target_word": "矿化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我捡到一块矿化的树枝。", "target_word": "矿化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "矿化了", "label": "体标"}, {"form": "矿化过", "label": "体标"}], "register": "中性", "sense_fingerprint": "东西变得像石头一样硬，里面有矿物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58fcc8cb-7a7f-4d32-9843-a69e1fc8fe4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "矿化", "is_correct": true, "explanation": "“矿化”指树木在水中或地下经过地质作用变成矿物，与“倒在水里”和“几千年后”相符。"}, {"text": "融化", "is_correct": false, "explanation": "搭配：“融化”多指冰雪、金属等受热变液体，不说树融化。"}, {"text": "燃烧", "is_correct": false, "explanation": "语义：“燃烧”与“倒在水里”的情境矛盾，浸水的树木不会燃烧。"}, {"text": "开花", "is_correct": false, "explanation": "语义：“开花”与“几千年后”的地质过程不符，埋在地下或水中的树木不会开花。"}], "explanations": {"矿化": "“矿化”指树木在水中或地下经过地质作用变成矿物，与“倒在水里”和“几千年后”相符。", "融化": "搭配：“融化”多指冰雪、金属等受热变液体，不说树融化。", "燃烧": "语义：“燃烧”与“倒在水里”的情境矛盾，浸水的树木不会燃烧。", "开花": "语义：“开花”与“几千年后”的地质过程不符，埋在地下或水中的树木不会开花。"}, "sentence_index": 0, "correct_answer": "矿化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这颗铁钉在潮湿的空气里矿化了。", "explanation": "这里应该用〈生锈〉。矿化指物质变成矿物，金属在潮湿空气中氧化只说生锈。"}, {"text": "这块面包已经矿化了。", "explanation": "这里应该用〈烧焦〉。矿化指物质变成矿物，食物被烤黑只说烧焦。"}, {"text": "这袋大米放久了，已经矿化了。", "explanation": "这里应该用〈发霉〉。矿化指物质变成矿物，食物长出霉斑只说发霉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "矿化", "is_correct": true, "explanation": "“矿化”指骨头变成石头样的硬物，修饰“骨头”，与“很硬”相符。"}, {"text": "松软", "is_correct": false, "explanation": "语义：“松软”指质地疏松，与“很硬”的描述矛盾。"}, {"text": "腐朽", "is_correct": false, "explanation": "语义：“腐朽”指腐烂变质，与“很硬”的状态相反。"}, {"text": "透明", "is_correct": false, "explanation": "体貌：“透明”描写外观，骨头不能形容为透明，且与句意不符。"}], "explanations": {"矿化": "“矿化”指骨头变成石头样的硬物，修饰“骨头”，与“很硬”相符。", "松软": "语义：“松软”指质地疏松，与“很硬”的描述矛盾。", "腐朽": "语义：“腐朽”指腐烂变质，与“很硬”的状态相反。", "透明": "体貌：“透明”描写外观，骨头不能形容为透明，且与句意不符。"}, "sentence_index": 6, "correct_answer": "矿化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "衣服晾在阳光下，很快就矿化了。", "explanation": "这里应该用〈晒干〉。矿化指物质变成矿物，衣服在阳光下变干只说晒干。"}, {"text": "这颗鸡蛋煮了很久，已经矿化了。", "explanation": "这里应该用〈煮老〉。矿化指东西变成像石头一样的矿物，鸡蛋煮久了只说煮老。"}, {"text": "这锅汤已经矿化了。", "explanation": "这里应该用〈熬干〉。矿化指物质变成矿物，汤煮到水分耗尽只说熬干。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根树枝已经很矿化了。", "corrected_sentence": "这根树枝已经矿化了。", "error_description": "错误：程度副词“很”不修饰结果性动词“矿化”。应去掉“很”，说“已经矿化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根矿化地树枝很硬。", "corrected_sentence": "这根矿化的树枝很硬。", "error_description": "错误：修饰名词“树枝”要用“的”，不用“地”。应说“矿化的树枝”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3abf3765-27f6-4edf-98ec-8583b210da1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
