INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25644, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "骨头是动物身体里面硬硬的东西。", "primary_collocate": null, "pronunciation": "gǔ tou", "ipa": "ku˨˩˦ tʰou", "syllable_count": 2, "sentences": [{"text": "猫不喜欢吃骨头。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗把骨头埋在地下。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有一块大骨头。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只鸡的骨头很小。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃完肉，把骨头放在盘子里。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有恐龙的骨头。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骨头很硬，我咬不动。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边找到一块鱼的骨头。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗汤是用牛的骨头做的。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友，别把骨头扔在地上。", "target_word": "骨头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一根骨头", "label": "量词"}, {"form": "一块骨头", "label": "量词"}, {"form": "鱼骨头", "label": "复合"}], "register": "中性", "sense_fingerprint": "动物身体里面硬硬的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd70a85e3-8683-4acb-9c19-ccb5efd1bd2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25644, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "骨头", "is_correct": true, "explanation": "正确答案：骨头（gǔ tou），指动物身体里硬硬的东西。"}, {"text": "苦头", "is_correct": false, "explanation": "苦头（kǔ tou）与骨头（gǔ tou）只有声母不同：k 送气，g 不送气，声调相同，意思是吃苦头、受苦。"}, {"text": "狗头", "is_correct": false, "explanation": "狗头（gǒu tou）与骨头（gǔ tou）只差韵母 u 与 ou，声调相同，意思是狗的头。"}, {"text": "裤头", "is_correct": false, "explanation": "裤头（kù tou）与骨头第一音节声母 k 与 g 不同，声调为第四声，意思是短裤或内裤。"}], "explanations": {"骨头": "正确答案：骨头（gǔ tou），指动物身体里硬硬的东西。", "苦头": "苦头（kǔ tou）与骨头（gǔ tou）只有声母不同：k 送气，g 不送气，声调相同，意思是吃苦头、受苦。", "狗头": "狗头（gǒu tou）与骨头（gǔ tou）只差韵母 u 与 ou，声调相同，意思是狗的头。", "裤头": "裤头（kù tou）与骨头第一音节声母 k 与 g 不同，声调为第四声，意思是短裤或内裤。"}, "sentence_index": null, "correct_answer": "骨头"}, "level_3": {"options": [{"text": "骨头", "is_correct": true, "explanation": "正确：骨头是动物身体里的硬组织，猫能吃，符合句子的语境。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被吃，与“吃”的对象不合。"}, {"text": "香烟", "is_correct": false, "explanation": "配价：“吃”的宾语应为食物，香烟要说“抽”，不说吃香烟。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是食物，猫不可能吃汽车。"}], "explanations": {"骨头": "正确：骨头是动物身体里的硬组织，猫能吃，符合句子的语境。", "空气": "语义：空气不能被吃，与“吃”的对象不合。", "香烟": "配价：“吃”的宾语应为食物，香烟要说“抽”，不说吃香烟。", "汽车": "语义：汽车不是食物，猫不可能吃汽车。"}, "sentence_index": 0, "correct_answer": "骨头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的骨头很结实。", "explanation": "这里应该用〈骨架〉。骨头指动物体内的骨，机器的框架要说“骨架”。"}, {"text": "这个苹果的骨头很甜。", "explanation": "这里应该用〈果核〉。骨头指动物体内的骨，果实中间的硬核要说“果核”。"}, {"text": "桌子上放着一张骨头。", "explanation": "这里应该用〈根〉或〈块〉。骨头是条状或块状，不用“张”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骨头", "is_correct": true, "explanation": "正确：骨头很硬，咬不动，是骨头的典型特点。"}, {"text": "豆腐", "is_correct": false, "explanation": "语义：豆腐柔软，与“很硬”相反，不能说豆腐很硬。"}, {"text": "棉花", "is_correct": false, "explanation": "搭配：棉花蓬松柔软，不与“很硬”搭配。"}, {"text": "泡沫", "is_correct": false, "explanation": "语义：泡沫轻软易碎，与“很硬”相矛盾。"}], "explanations": {"骨头": "正确：骨头很硬，咬不动，是骨头的典型特点。", "豆腐": "语义：豆腐柔软，与“很硬”相反，不能说豆腐很硬。", "棉花": "搭配：棉花蓬松柔软，不与“很硬”搭配。", "泡沫": "语义：泡沫轻软易碎，与“很硬”相矛盾。"}, "sentence_index": 6, "correct_answer": "骨头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座房子的骨头是钢筋做的。", "explanation": "这里应该用〈框架〉。骨头指动物体内的骨，房屋的结构要说“框架”。"}, {"text": "我在草地上捡到一扇骨头。", "explanation": "这里应该用〈根〉或〈块〉。“扇”用于门窗，骨头不能用“扇”计量。"}, {"text": "他是班里的骨头，学习很努力。", "explanation": "这里应该用〈骨干〉。骨头指动物体内的骨，班里的核心成员要说“骨干”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "狗在院子里挖出了一朵骨头。", "corrected_sentence": "狗在院子里挖出了一根骨头。", "error_description": "错误：“一朵骨头”。“朵”用于花朵、云朵等，骨头应用“根”或“块”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厨师用一张骨头熬汤。", "corrected_sentence": "厨师用一块骨头熬汤。", "error_description": "错误：“一张骨头”，正确：“一块骨头”。“张”用于平面的东西，骨头应用“根”或“块”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
