INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25646, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "加一点点东西。", "primary_collocate": null, "pronunciation": "jiā yì diǎn", "ipa": "tɕja˥ i˥˩ tjɛn˨˩˦", "syllable_count": 3, "sentences": [{"text": "面太淡，我加一点酱油。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "粥里加一点盐更好吃。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子里加一点冰，果汁会更凉。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的作文可以加一点例子。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花瓶里加一点水，花就不会死。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕太酸，给它加一点糖。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路有点滑，加一点沙子会好走。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饺子馅儿里加一点肉更香。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤快好了，最后加一点葱花。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶太淡，加一点奶粉。", "target_word": "加一点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加一点点", "label": "重叠"}, {"form": "加点儿", "label": "口语"}], "register": "口语", "sense_fingerprint": "加入一点点东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd70a85e3-8683-4acb-9c19-ccb5efd1bd2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25646, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加一点", "is_correct": true, "explanation": "正确：面太淡，加少量酱油正合语境。"}, {"text": "倒掉一点", "is_correct": false, "explanation": "语义：面太淡应加酱油，倒掉酱油与语境相反。"}, {"text": "喝一点", "is_correct": false, "explanation": "配价：“喝”要求饮品作宾语，酱油是调料，不说喝酱油。"}, {"text": "洗一点", "is_correct": false, "explanation": "搭配：酱油不用“洗”，“洗”与酱油搭配不当。"}], "explanations": {"加一点": "正确：面太淡，加少量酱油正合语境。", "倒掉一点": "语义：面太淡应加酱油，倒掉酱油与语境相反。", "喝一点": "配价：“喝”要求饮品作宾语，酱油是调料，不说喝酱油。", "洗一点": "搭配：酱油不用“洗”，“洗”与酱油搭配不当。"}, "sentence_index": 0, "correct_answer": "加一点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给我加一点生日。", "explanation": "这里应该用〈过〉。加一点指增添少量，过生日要说“过”。"}, {"text": "周末我要加一点电影。", "explanation": "这里应该用〈看〉。加一点指增添少量，看电影要说“看”。"}, {"text": "你这样做是在给大家加一点乱。", "explanation": "这里应该用〈添〉。“加一点”指增添具体的东西，“加一点乱”说不通，固定说法是“添乱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加一点", "is_correct": true, "explanation": "正确：路滑时加少量沙子能增加摩擦，符合语境。"}, {"text": "减一点", "is_correct": false, "explanation": "语义：路滑时要加沙子，减沙子与语境相反。"}, {"text": "吃一点", "is_correct": false, "explanation": "配价：“吃”的宾语应为食物，沙子不能吃。"}, {"text": "擦一点", "is_correct": false, "explanation": "搭配：沙子不用“擦”，“擦”与沙子搭配不当。"}], "explanations": {"加一点": "正确：路滑时加少量沙子能增加摩擦，符合语境。", "减一点": "语义：路滑时要加沙子，减沙子与语境相反。", "吃一点": "配价：“吃”的宾语应为食物，沙子不能吃。", "擦一点": "搭配：沙子不用“擦”，“擦”与沙子搭配不当。"}, "sentence_index": 6, "correct_answer": "加一点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在比赛中加一点金牌。", "explanation": "这里应该用〈赢得〉。加一点不能用来指获得荣誉，应说“赢得金牌”。"}, {"text": "他每天都会加一点睡觉。", "explanation": "这里应该用〈多〉。“加一点”只能接具体的事物，不能接动作“睡觉”，应说“多睡觉”。"}, {"text": "他加一点我们的班级。", "explanation": "这里应该用〈加入〉。加一点指给某物增加少量，不能用来指加入班级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "粥太稀，我刚加一点糖。", "corrected_sentence": "粥太稀，我刚加了一点糖。", "error_description": "错误：“刚加一点糖”，正确：“刚加了一点糖”。表示动作已完成，动词“加”后应加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汤有点咸，我加了一点了水。", "corrected_sentence": "汤有点咸，我加了一点水。", "error_description": "错误：“加了一点了水”，多出一个“了”。正确：“加了一点水”，“了”只需出现一次，紧跟动词“加”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
