INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25648, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把花种在土里，让它长大、开花。", "primary_collocate": null, "pronunciation": "yǎng huā", "ipa": "jɑŋ˨˩ xuɑ˥", "syllable_count": 2, "sentences": [{"text": "春天到了，我想在家养花。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "养花需要好土，也需要水。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王周末喜欢在院子里养花。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱养花，因为工作太忙。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "养花的时候，要把花种在土里。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说养花可以让人心情好。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次养花，不知道多久浇一次水。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起去买花盆养花吧。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在窗台上养花，每天看着它们长大。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷养花二十年了，家里很漂亮。", "target_word": "养花", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "养了花", "label": "体标"}, {"form": "养过花", "label": "体标"}], "register": "中性", "sense_fingerprint": "把花种在土里并照料使其长大开花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8dcf6e-820e-41d6-966b-7b4656bddf4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25648, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "养花", "is_correct": true, "explanation": "正确：养花指把花种在土里并照料，使其长大开花。"}, {"text": "氧化", "is_correct": false, "explanation": "氧化（yǎnghuà）与养花（yǎnghuā）只有第二个音节声调不同，意思是物质与氧结合。"}, {"text": "眼花", "is_correct": false, "explanation": "眼花（yǎnhuā）与养花（yǎnghuā）第一个音节韵尾不同（an 与 ang），意思是视物模糊。"}, {"text": "养活", "is_correct": false, "explanation": "养活（yǎnghuó）与养花（yǎnghuā）第二个音节声调不同，意思是供养、维持生计。"}, {"text": "赏花", "is_correct": false, "explanation": "赏花（shǎnghuā）与养花（yǎnghuā）第一个音节声母不同，意思是观赏花开。"}], "explanations": {"养花": "正确：养花指把花种在土里并照料，使其长大开花。", "氧化": "氧化（yǎnghuà）与养花（yǎnghuā）只有第二个音节声调不同，意思是物质与氧结合。", "眼花": "眼花（yǎnhuā）与养花（yǎnghuā）第一个音节韵尾不同（an 与 ang），意思是视物模糊。", "养活": "养活（yǎnghuó）与养花（yǎnghuā）第二个音节声调不同，意思是供养、维持生计。", "赏花": "赏花（shǎnghuā）与养花（yǎnghuā）第一个音节声母不同，意思是观赏花开。"}, "sentence_index": null, "correct_answer": "养花"}, "level_3": {"options": [{"text": "养花", "is_correct": true, "explanation": "正确：“我想在家养花”，养花是在家里栽种照料花草，符合语境。"}, {"text": "出国", "is_correct": false, "explanation": "语义：“出国”需要去别的地方，“在家”与之矛盾，句子不通。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”指没按时到达，不能说在家里做，与“春天到了，我想在家”的意愿不合。"}, {"text": "失恋", "is_correct": false, "explanation": "语义：“失恋”是情感经历，不是可以在家主动去做的事，与句子的意愿冲突。"}], "explanations": {"养花": "正确：“我想在家养花”，养花是在家里栽种照料花草，符合语境。", "出国": "语义：“出国”需要去别的地方，“在家”与之矛盾，句子不通。", "迟到": "语义：“迟到”指没按时到达，不能说在家里做，与“春天到了，我想在家”的意愿不合。", "失恋": "语义：“失恋”是情感经历，不是可以在家主动去做的事，与句子的意愿冲突。"}, "sentence_index": 0, "correct_answer": "养花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去郊外养花，欣赏满山的桃花。", "explanation": "这里应该用〈赏花〉。养花指栽种照料，欣赏盛开的花应说赏花。"}, {"text": "孩子们在山坡上养花，采了很多野花。", "explanation": "这里应该用〈采花〉。养花要长期栽培，摘取野花应说采花。"}, {"text": "他去花店养花，准备情人节送给我。", "explanation": "这里应该用〈买花〉。养花是栽培过程，在花店挑选现成的花应说买花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "养花", "is_correct": true, "explanation": "正确：“我第一次养花，不知道多久浇一次水”，指第一次栽种照料花草，符合语境。"}, {"text": "做饭", "is_correct": false, "explanation": "语义：“做饭”与“多久浇一次水”的浇水语境无关，不能与后半句配合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”与浇水没有关系，“不知道多久浇一次水”不能接在考试之后。"}, {"text": "包饺子", "is_correct": false, "explanation": "语义：“包饺子”与“浇一次水”的语境毫不相关，前后句意思对不上。"}], "explanations": {"养花": "正确：“我第一次养花，不知道多久浇一次水”，指第一次栽种照料花草，符合语境。", "做饭": "语义：“做饭”与“多久浇一次水”的浇水语境无关，不能与后半句配合。", "考试": "语义：“考试”与浇水没有关系，“不知道多久浇一次水”不能接在考试之后。", "包饺子": "语义：“包饺子”与“浇一次水”的语境毫不相关，前后句意思对不上。"}, "sentence_index": 6, "correct_answer": "养花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶每天在客厅养花，把剪下的花装进花瓶里。", "explanation": "这里应该用〈插花〉。养花指把花种在土里，把剪下的花装进花瓶应说插花。"}, {"text": "情人节那天，他给我养花当礼物。", "explanation": "这里应该用〈送花〉。养花是栽培过程，不能当作礼物送人；赠送花束应说送花。"}, {"text": "她很喜欢养花的香味，每次经过都停下来。", "explanation": "这里应该用〈闻〉。养花指栽培，不指香气；闻花的香味才是对的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小时候养花过，现在很喜欢园艺。", "corrected_sentence": "他小时候养过花，现在很喜欢园艺。", "error_description": "错误形式：“养花过”。正确形式：“养过花”。“养花”是离合词，经历体标记“过”应放在“养”的后面、“花”的前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他第一次了养花，总是忘记浇水。", "corrected_sentence": "他第一次养花，总是忘记浇水。", "error_description": "错误形式：“了养花”。正确形式：“养花”。动态助词“了”不能放在动词“养花”之前，这里的句子不需要“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
