INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25650, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多小东西连在一起变成大东西。", "primary_collocate": null, "pronunciation": "jù hé fǎn yìng", "ipa": "tɕy˥˩ xɤ˧˥ fan˨˩˦ iŋ˥˩", "syllable_count": 4, "sentences": [{"text": "很多小分子连在一起，这就是聚合反应。", "target_word": "聚合反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小分子经过聚合反应，变成了长长的大分子。", "target_word": "聚合反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聚合反应就像把小珠子串成一条长项链。", "target_word": "聚合反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用珠子说明什么是聚合反应。", "target_word": "聚合反应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种聚合反应能让小分子越连越长。", "target_word": "聚合反应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们看着聚合反应一点一点地进行。", "target_word": "聚合反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做塑料瓶要用到聚合反应。", "target_word": "聚合反应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "聚合反应后，液体变成了硬硬的固体。", "target_word": "聚合反应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上画了聚合反应的过程图。", "target_word": "聚合反应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小分子在聚合反应中一个接一个地连起来。", "target_word": "聚合反应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种聚合反应", "label": "量词"}, {"form": "聚合反應", "label": "繁体"}], "register": "书面", "sense_fingerprint": "许多小分子连接成大分子的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f995feb-01f2-46a0-bd0f-015ea5999b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25650, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聚合反应", "is_correct": true, "explanation": "正确：“这就是聚合反应”概括“很多小分子连在一起”的过程，语义相符。"}, {"text": "分解反应", "is_correct": false, "explanation": "语义：“分解反应”指物质分开，与“小分子连在一起”的意思相反。"}, {"text": "珠子", "is_correct": false, "explanation": "搭配：“这就是”后接的应是过程名称，“珠子”不能概括小分子连接的过程。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”不是化学过程，不能用来概括“小分子连在一起”。"}], "explanations": {"聚合反应": "正确：“这就是聚合反应”概括“很多小分子连在一起”的过程，语义相符。", "分解反应": "语义：“分解反应”指物质分开，与“小分子连在一起”的意思相反。", "珠子": "搭配：“这就是”后接的应是过程名称，“珠子”不能概括小分子连接的过程。", "温度": "语义：“温度”不是化学过程，不能用来概括“小分子连在一起”。"}, "sentence_index": 0, "correct_answer": "聚合反应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们有一个聚合反应。", "explanation": "这里应该用〈聚会〉。聚会指朋友、同学相聚；聚合反应是很多小东西连成大东西，不能指人的聚会。"}, {"text": "老师宣布了聚合反应的时间。", "explanation": "这里应该用〈集合〉。集合指人到一处，宣布的是“集合的时间”；聚合反应指小东西连成大东西，不能指人的集合。"}, {"text": "这个班的聚合反应很强。", "explanation": "这里应该用〈凝聚力〉。凝聚力指团体的团结程度；聚合反应专指很多小东西连成大东西，不能指集体的团结。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聚合反应", "is_correct": true, "explanation": "正确：“用到聚合反应”指用这一反应生产塑料瓶，语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是制造塑料瓶的方法，与句意不合。"}, {"text": "化学家", "is_correct": false, "explanation": "配价：“用到”后接材料或方法，不能接人“化学家”。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：“鸡蛋”是食物，不是生产塑料瓶的手段。"}], "explanations": {"聚合反应": "正确：“用到聚合反应”指用这一反应生产塑料瓶，语境相符。", "天气": "语义：“天气”不是制造塑料瓶的方法，与句意不合。", "化学家": "配价：“用到”后接材料或方法，不能接人“化学家”。", "鸡蛋": "语义：“鸡蛋”是食物，不是生产塑料瓶的手段。"}, "sentence_index": 6, "correct_answer": "聚合反应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "糖在热水里很快就聚合反应了。", "explanation": "这里应该用〈溶解〉。糖溶于水是物理过程，不是小分子连成大分子。"}, {"text": "冰块的聚合反应很快。", "explanation": "这里应该用〈融化〉。融化是固体变成液体，不是小东西连成大东西，不能用聚合反应。"}, {"text": "他对老师的批评做了聚合反应。", "explanation": "这里应该用〈回应〉。聚合反应指很多小东西连成大东西，不能指人对批评作出的应对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只重要的聚合反应。", "corrected_sentence": "这是一种重要的聚合反应。", "error_description": "“聚合反应”的量词应用“种”或“次”，不用“只”；“只”用于动物或单个器物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种小分子聚合反应中会连成长链。", "corrected_sentence": "这种小分子在聚合反应中会连成长链。", "error_description": "“聚合反应”表示过程发生的范围，前面要加介词“在”，说“在……中”；缺少“在”，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c895ac1-e207-45a0-ac6b-c297a5c07b84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
