INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25652, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指所有的人。", "primary_collocate": null, "pronunciation": "rén rén", "ipa": "ʐən˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "看到那只小狗，人人都笑了。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个道理，人人都懂。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个城市，人人都骑自行车上班。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人人为我，我为人人。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的歌很有名，人人都会唱。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始前，人人都在认真准备。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好习惯对人人都有好处。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，人人都带着伞。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏很简单，人人都能玩。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年到了，人人都很高兴。", "target_word": "人人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "泛指在场或某个范围内的所有人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8dcf6e-820e-41d6-966b-7b4656bddf4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25652, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人人", "is_correct": true, "explanation": "正确：“看到那只小狗，人人都笑了”，“人人”泛指在场的所有人，与“都笑了”的全体反应相符。"}, {"text": "他", "is_correct": false, "explanation": "语义：“他”指一个人，与“都笑了”的全体反应不合。"}, {"text": "诸位", "is_correct": false, "explanation": "语域：“诸位”是对听众的书面敬称，不适合作为描述在场人反应的主语。"}, {"text": "某人", "is_correct": false, "explanation": "语义：“某人”指不确定的一个人，与“都”表示的全体含义矛盾。"}], "explanations": {"人人": "正确：“看到那只小狗，人人都笑了”，“人人”泛指在场的所有人，与“都笑了”的全体反应相符。", "他": "语义：“他”指一个人，与“都笑了”的全体反应不合。", "诸位": "语域：“诸位”是对听众的书面敬称，不适合作为描述在场人反应的主语。", "某人": "语义：“某人”指不确定的一个人，与“都”表示的全体含义矛盾。"}, "sentence_index": 0, "correct_answer": "人人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛，人人都没有输，只有一个队输了。", "explanation": "这里应该用〈大多数〉。“人人”指全体，没有例外；只有一个队输了应说大多数。"}, {"text": "这是我人人的事，别人不用管。", "explanation": "这里应该用〈个人〉。“个人的事”修饰自己的事情，“人人”指全体，不能说“我人人的事”。"}, {"text": "这个城市的人人有三百万。", "explanation": "这里应该用〈人口〉。“人人”指每个人，不表示总人数；城市的总人数应说人口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人人", "is_correct": true, "explanation": "正确：“好习惯对人人都有好处”，“人人”泛指所有的人，与“都有好处”搭配。"}, {"text": "某人", "is_correct": false, "explanation": "语义：“某人”指不确定的一个人，与“都有好处”要求的全体含义不合。"}, {"text": "一人", "is_correct": false, "explanation": "语义：“一人”指单个人，与“都有好处”要求的全体含义不合。"}, {"text": "对方", "is_correct": false, "explanation": "语义：“对方”指与己方相对的另一方，与“好习惯对谁都有好处”的泛指语境不合。"}], "explanations": {"人人": "正确：“好习惯对人人都有好处”，“人人”泛指所有的人，与“都有好处”搭配。", "某人": "语义：“某人”指不确定的一个人，与“都有好处”要求的全体含义不合。", "一人": "语义：“一人”指单个人，与“都有好处”要求的全体含义不合。", "对方": "语义：“对方”指与己方相对的另一方，与“好习惯对谁都有好处”的泛指语境不合。"}, "sentence_index": 6, "correct_answer": "人人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司正在招聘，希望找到很多人人。", "explanation": "这里应该用〈人才〉。“人人”指每一个人，不指有能力的人；招聘应说人才。"}, {"text": "新年到了，人人中有一半很高兴，另一半不高兴。", "explanation": "这里应该用〈有些人〉。“人人”指全体，没有例外；只有一半人高兴应说有些人。"}, {"text": "新年到了，爷爷给每个人人都发了红包。", "explanation": "这里应该用〈人〉。“人人”是代词，不能跟在“每个”后面作单位；“每个人都”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气很热，一人人都在喝水。", "corrected_sentence": "天气很热，人人都在喝水。", "error_description": "错误形式：“一人人”。正确形式：“人人”。“人人”是代词，不能与数量词“一”组合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么热的天，人人们都想吃冰。", "corrected_sentence": "这么热的天，人人都想吃冰。", "error_description": "错误形式：“人人们”。正确形式：“人人”。“人人”已表示全体，后面不能再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
