INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25656, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把饭吃完后剩下的。", "primary_collocate": null, "pronunciation": "chī shèng", "ipa": "ʈʂʰɻ̩˥ ʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "吃剩的饭不要倒掉，明天还能吃。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打包了吃剩的饺子带回家。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天菜做多了，我们吃剩了一半。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "午饭后，桌上放着吃剩的米饭。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗吃剩的汤已经凉了。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃剩的面条放久了会坏。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把吃剩的饭倒进了垃圾桶。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子吃剩的饭，妈妈接着吃了。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃剩的鸡肉可以明天做汤。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里有昨天吃剩的蛋糕。", "target_word": "吃剩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吃剩了", "label": "体标"}], "register": "中性", "sense_fingerprint": "饭后剩下没吃完的饭菜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7bcf024-40e1-464a-b19b-d6126447d7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25656, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃剩", "is_correct": true, "explanation": "吃剩：吃完后剩下的，修饰“饭”，指可以留着再吃的剩饭。"}, {"text": "变质", "is_correct": false, "explanation": "语义：“变质”的饭已经坏了，与“明天还能吃”矛盾。"}, {"text": "切碎", "is_correct": false, "explanation": "搭配：“切碎”多用于菜、肉，不说“切碎的饭”。"}, {"text": "发霉", "is_correct": false, "explanation": "语义：发霉的饭不能吃，与“明天还能吃”相反。"}], "explanations": {"吃剩": "吃剩：吃完后剩下的，修饰“饭”，指可以留着再吃的剩饭。", "变质": "语义：“变质”的饭已经坏了，与“明天还能吃”矛盾。", "切碎": "搭配：“切碎”多用于菜、肉，不说“切碎的饭”。", "发霉": "语义：发霉的饭不能吃，与“明天还能吃”相反。"}, "sentence_index": 0, "correct_answer": "吃剩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子把碗里的米饭都吃剩了。", "explanation": "这里应该用〈吃光〉。吃剩指吃完后留下的部分，“都吃剩了”说明没有剩余，应说“吃光”。"}, {"text": "我们吃剩了整整一个下午。", "explanation": "这里应该用〈浪费〉。吃剩只用于饭菜等食物，时间不能“吃剩”，应说“浪费了整个下午”。"}, {"text": "书架上吃剩了一本旧字典。", "explanation": "这里应该用〈剩下〉。吃剩只用于吃过的食物，字典没有被吃过，应说“剩下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃剩", "is_correct": true, "explanation": "吃剩：吃完后剩下的，修饰“饭”，指没吃完、被扔掉的饭。"}, {"text": "吃光", "is_correct": false, "explanation": "语义：吃光后就没有饭可倒，与“倒进垃圾桶”矛盾。"}, {"text": "享用", "is_correct": false, "explanation": "语域：“享用”偏书面、郑重，说“享用的饭”不自然，与口语语境“倒进垃圾桶”不合。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：饭已吞进肚里，不会再被倒进垃圾桶。"}], "explanations": {"吃剩": "吃剩：吃完后剩下的，修饰“饭”，指没吃完、被扔掉的饭。", "吃光": "语义：吃光后就没有饭可倒，与“倒进垃圾桶”矛盾。", "享用": "语域：“享用”偏书面、郑重，说“享用的饭”不自然，与口语语境“倒进垃圾桶”不合。", "吞下": "语义：饭已吞进肚里，不会再被倒进垃圾桶。"}, "sentence_index": 6, "correct_answer": "吃剩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些蔬菜上吃剩了不少农药。", "explanation": "这里应该用〈残留〉。农药附着在蔬菜上，应说“残留”；吃剩只用于被吃过的食物。"}, {"text": "周末我吃剩了一场球赛。", "explanation": "这里应该用〈看完〉。球赛是看的，不是吃的，吃剩只用于食物。"}, {"text": "他终于把作业吃剩了。", "explanation": "这里应该用〈做完〉。作业要做完，不能“吃剩”，吃剩只用于食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把吃剩地饺子冻进了冰箱。", "corrected_sentence": "妈妈把吃剩的饺子冻进了冰箱。", "error_description": "“吃剩”修饰“饺子”，要用“的”，不能用“地”（“地”用于动词、形容词前作状语）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想把吃剩地汤热一热。", "corrected_sentence": "我想把吃剩的汤热一热。", "error_description": "“吃剩”修饰“汤”，要用“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
