INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25660, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水果的皮就是水果外面那层可以剥掉或吃掉的东西。", "primary_collocate": null, "pronunciation": "shuǐ guǒ pí", "ipa": "ʂweɪ˨˩˦ kwo˨˩˦ pʰi˧˥", "syllable_count": 3, "sentences": [{"text": "水果皮上常常有农药。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃苹果时，有人不削水果皮。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他剥开水果皮，吃里面的果肉。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果皮是红色的，很好看。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果皮要洗干净才能吃。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道哪些水果皮可以吃吗？", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把水果皮剥掉，放在盘子旁边。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果皮和果肉的味道不一样。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩把水果皮扔在了路上。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果皮又薄又软。", "target_word": "水果皮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块水果皮", "label": "量词"}, {"form": "一片水果皮", "label": "量词"}], "register": "中性", "sense_fingerprint": "水果外面可剥可吃的皮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7bcf024-40e1-464a-b19b-d6126447d7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25660, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水果皮", "is_correct": true, "explanation": "水果皮：水果外面可剥可吃的皮，是农药常附着的地方。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮上不会有农药，与句意不符。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁不会沾上农药，与句意矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”后一般说“中”，不说“空气上”。"}], "explanations": {"水果皮": "水果皮：水果外面可剥可吃的皮，是农药常附着的地方。", "月亮": "语义：月亮上不会有农药，与句意不符。", "钢铁": "语义：钢铁不会沾上农药，与句意矛盾。", "空气": "搭配：“空气”后一般说“中”，不说“空气上”。"}, "sentence_index": 0, "correct_answer": "水果皮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我爱喝新鲜的水果皮。", "explanation": "这里应该用〈果汁〉。喝的是液体，水果皮不能喝，应说“新鲜的果汁”。"}, {"text": "这颗橘子的水果皮很多汁。", "explanation": "这里应该用〈果肉〉。多汁说的是果肉，水果皮是外层的皮。"}, {"text": "他把桃子的水果皮种进了花盆里。", "explanation": "这里应该用〈果核〉。桃核里有种子，能种出桃树；水果皮没有种子，不能用来播种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25660, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水果皮", "is_correct": true, "explanation": "水果皮：水果外面的皮，可以剥掉后放在盘子旁边。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不能剥，与句意不符。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不能被剥掉，与句意矛盾。"}, {"text": "地板", "is_correct": false, "explanation": "搭配：“剥”不搭配“地板”，地板一般说“撬”或“拆”。"}], "explanations": {"水果皮": "水果皮：水果外面的皮，可以剥掉后放在盘子旁边。", "钥匙": "语义：钥匙不能剥，与句意不符。", "玻璃": "语义：玻璃不能被剥掉，与句意矛盾。", "地板": "搭配：“剥”不搭配“地板”，地板一般说“撬”或“拆”。"}, "sentence_index": 6, "correct_answer": "水果皮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的水果皮很光滑。", "explanation": "这里应该用〈皮肤〉。水果皮指水果的外皮，不能用来指人的皮肤。"}, {"text": "他喜欢读水果皮。", "explanation": "这里应该用〈书〉。“读”的对象是书籍等文字材料，水果皮不能读。"}, {"text": "妹妹戴着水果皮出门了。", "explanation": "这里应该用〈帽子〉。“戴”用于帽子、眼镜等，水果皮不能戴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把水果皮掉剥了，只吃果肉。", "corrected_sentence": "他把水果皮剥掉了，只吃果肉。", "error_description": "“掉”是结果补语，必须紧接在“剥”后面，应说“剥掉了”，不能说“掉剥了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在书里夹了两根水果皮。", "corrected_sentence": "我在书里夹了两片水果皮。", "error_description": "“水果皮”的量词用“片”或“块”，不能用“根”（“根”用于细长的物品）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae601c2-2197-4720-9241-627f965dae00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
