INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25674, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25674, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西坏了，有难闻的气味。", "primary_collocate": null, "pronunciation": "fā chòu", "ipa": "fa⁵⁵ ʈʂʰou̯⁵¹", "syllable_count": 2, "sentences": [{"text": "厨房的垃圾没有倒，已经发臭了。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太热，菜放一晚上就发臭。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗汤发臭了，别喝了。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水沟里的水发臭，蚊子也很多。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的运动鞋好久没洗，开始发臭。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虾不放进冰箱，很快就会发臭。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过期的豆腐发臭了，倒掉吧。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞋子湿着放在鞋柜里，很容易发臭。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾车来晚了，路边的垃圾都发臭了。", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你闻，这个盒子里的肉是不是发臭了？", "target_word": "发臭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发臭了", "label": "完成体"}, {"form": "发臭过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "东西坏了散发难闻气味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffaa23c-0615-48bd-8fdc-16ab6fa2cc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25674, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发臭", "is_correct": true, "explanation": "发臭：垃圾没倒而腐坏，散发臭味，与句意相符。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”指植物长出芽，垃圾不会发芽。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”只用于金属，垃圾不能说生锈。"}, {"text": "开花", "is_correct": false, "explanation": "语义：“开花”指植物开放，与垃圾腐坏无关。"}], "explanations": {"发臭": "发臭：垃圾没倒而腐坏，散发臭味，与句意相符。", "发芽": "语义：“发芽”指植物长出芽，垃圾不会发芽。", "生锈": "搭配：“生锈”只用于金属，垃圾不能说生锈。", "开花": "语义：“开花”指植物开放，与垃圾腐坏无关。"}, "sentence_index": 0, "correct_answer": "发臭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花园里的玫瑰香味发臭了。", "explanation": "这里应该用〈散发〉。散发指向外发出气味，可以搭配香味；发臭只指东西腐败后有臭味，不能用于香味。"}, {"text": "屋子里的烟雾发臭了。", "explanation": "这里应该用〈弥漫〉。弥漫指烟雾等充满一片；发臭只指东西腐败后有臭味，不能形容烟雾。"}, {"text": "教室里的铃声发臭了。", "explanation": "这里应该用〈响起〉。响起指声音发出来；发臭只指东西腐败后有臭味，不能用于声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发臭", "is_correct": true, "explanation": "发臭：豆腐过期后变质，散发臭味，与“倒掉吧”的语境相符。"}, {"text": "发亮", "is_correct": false, "explanation": "语义：“发亮”指发光，与豆腐变质无关。"}, {"text": "长高", "is_correct": false, "explanation": "搭配：“长高”不能用于豆腐。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”指发出歌声，与豆腐过期无关，句子不通。"}], "explanations": {"发臭": "发臭：豆腐过期后变质，散发臭味，与“倒掉吧”的语境相符。", "发亮": "语义：“发亮”指发光，与豆腐变质无关。", "长高": "搭配：“长高”不能用于豆腐。", "唱歌": "语义：“唱歌”指发出歌声，与豆腐过期无关，句子不通。"}, "sentence_index": 6, "correct_answer": "发臭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一进门，咖啡的香味发臭而来。", "explanation": "这里应该用〈扑鼻〉。扑鼻形容香味直冲鼻子；发臭只指东西腐败后有臭味，不能形容香味。"}, {"text": "午后的阳光发臭了。", "explanation": "这里应该用〈照〉。照指光线射到某处；发臭只指东西腐败后有难闻的气味，不能形容光线。"}, {"text": "浴室里的水汽发臭了。", "explanation": "这里应该用〈冒〉。冒指水汽、热气等向上升起；发臭只指东西腐败后有难闻的气味，不能形容水汽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房的垃圾两天没倒，已经很发臭了。", "corrected_sentence": "厨房的垃圾两天没倒，已经发臭了。", "error_description": "程度副词误加：“发臭”是动词，前面不能加“很”，应说“已经发臭了”，不说“很发臭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双旧袜子湿着放在鞋柜里，很容易发臭地。", "corrected_sentence": "这双旧袜子湿着放在鞋柜里，很容易发臭。", "error_description": "多余的“地”：“地”用于状语后修饰动词，不能加在句末的“发臭”后面，应删去，说“很容易发臭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '390014e4-9541-425b-a25d-805292f15ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
