INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25678, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25678, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西用掉或拿走以后，还有一部分没有用掉或拿走。", "primary_collocate": null, "pronunciation": "shèng xià", "ipa": "ʂəŋ˥˩ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "衣服洗完后，盆里剩下一点水。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先拿，剩下的留给我。", "target_word": "剩下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买了票以后，我只剩下十块钱。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书架上的书拿走了，只剩下几本旧杂志。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家分了蛋糕，我这里还剩下一块。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱里的牛奶喝了一半，只剩下半瓶。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做完作业后，他还剩下一个小时的自由时间。", "target_word": "剩下", "complexity_tier": "T3", "furigana": "shèng xià", "sentence_source": "generated"}, {"text": "我把零食都吃了，一点也没剩下。", "target_word": "剩下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们才走了一半，还剩下十公里。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水只剩下一点点，不够大家喝了。", "target_word": "剩下", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "剩下了", "label": "体标：了"}, {"form": "剩下来", "label": "趋向补语"}, {"form": "剩下的", "label": "的字结构"}], "register": "中性", "sense_fingerprint": "东西用掉或拿走后还有一部分没动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7463c093-f860-4636-af40-85cf1daafb3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25678, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剩下", "is_correct": true, "explanation": "剩下：衣服洗完后盆里留存的部分，与句意相符。"}, {"text": "吸收", "is_correct": false, "explanation": "语义：水被吸收后不会留在盆里，与句意相反。"}, {"text": "倒掉", "is_correct": false, "explanation": "语义：倒掉的水不会留在盆里，与句意相反。"}, {"text": "装满", "is_correct": false, "explanation": "搭配：「装满」与「一点」语义矛盾，不能搭配。"}], "explanations": {"剩下": "剩下：衣服洗完后盆里留存的部分，与句意相符。", "吸收": "语义：水被吸收后不会留在盆里，与句意相反。", "倒掉": "语义：倒掉的水不会留在盆里，与句意相反。", "装满": "搭配：「装满」与「一点」语义矛盾，不能搭配。"}, "sentence_index": 0, "correct_answer": "剩下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈去市场剩下了两斤鱼。", "explanation": "这里应该用〈买〉。剩下表示用掉后余留，不表示去市场买到东西。"}, {"text": "我今天剩下了一封信，很开心。", "explanation": "这里应该用〈收到〉。剩下表示余留，不表示收到别人寄来的东西。"}, {"text": "他不小心剩下了一个杯子。", "explanation": "这里应该用〈落下〉。剩下表示余留，不表示不小心把东西留在某处；忘在某处应说落下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剩下", "is_correct": true, "explanation": "剩下：做完作业后仍留存的时间，句意成立。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：自由时间不能吃掉，与句意不符。"}, {"text": "倒掉", "is_correct": false, "explanation": "语义：时间不能倒掉，与句意不符。"}, {"text": "带走", "is_correct": false, "explanation": "搭配：说时间留存一般用「剩下」或「用掉」，不能说「带走」自由时间。"}], "explanations": {"剩下": "剩下：做完作业后仍留存的时间，句意成立。", "吃掉": "语义：自由时间不能吃掉，与句意不符。", "倒掉": "语义：时间不能倒掉，与句意不符。", "带走": "搭配：说时间留存一般用「剩下」或「用掉」，不能说「带走」自由时间。"}, "sentence_index": 6, "correct_answer": "剩下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去邮局剩下了一封信。", "explanation": "这里应该用〈寄〉。去邮局是寄信，剩下表示余留，不表示把信寄出。"}, {"text": "他向朋友剩下了三本书。", "explanation": "这里应该用〈借〉。向朋友借书是借，剩下表示余留，不能用来说借入。"}, {"text": "他用抹布剩下了桌子。", "explanation": "这里应该用〈擦〉。用抹布做的是擦，剩下表示余留，不能用来说擦拭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桶里还剩下完一点油。", "corrected_sentence": "桶里还剩下一点油。", "error_description": "「剩下完一点油」错，「完」表示用尽，与「剩下」的留存义矛盾，应删去「完」，说「还剩下一点油」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车上被剩下两个座位。", "corrected_sentence": "车上还剩下两个座位。", "error_description": "「车上被剩下两个座位」错，「剩下」表示余留，不能用被字句，此处「被」应换为「还」，说「车上还剩下两个座位」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
