INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25680, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把食物弄熟。", "primary_collocate": null, "pronunciation": "zuò fàn", "ipa": "tswɔ˥˩ fan˥˩", "syllable_count": 2, "sentences": [{"text": "我们在山上用小火炉做饭。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在河边生火做饭，天黑才吃。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个锅很大，可以用来做饭。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "停电了，电饭锅不能用，没法做饭。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农村的老房子还用柴火做饭。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生宿舍不让用大功率电器做饭。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用电磁炉做饭又快又干净。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "露营时我们用燃气灶做饭，很方便。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用高压锅做饭，二十分钟就熟了。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳能灶可以在院子里做饭。", "target_word": "做饭", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "做了饭", "label": "体标：了"}, {"form": "做过饭", "label": "体标：过"}, {"form": "做完饭", "label": "结果补语"}], "register": "口语", "sense_fingerprint": "用炉灶等炊具加热，把食物弄熟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7463c093-f860-4636-af40-85cf1daafb3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25680, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "做饭", "is_correct": true, "explanation": "做饭（zuò fàn）：用炉灶加热、把食物弄熟，为正确答案。"}, {"text": "做法", "is_correct": false, "explanation": "fǎ（第三声）与 fàn（第四声）声调不同，「做法」意思是方法、做的办法。"}, {"text": "做反", "is_correct": false, "explanation": "fǎn（第三声）与 fàn（第四声）声调不同，「做反」意思是做得与原来相反。"}, {"text": "罪犯", "is_correct": false, "explanation": "zuì 与 zuò 韵母不同，「罪犯」（zuì fàn）意思是犯罪的人。"}], "explanations": {"做饭": "做饭（zuò fàn）：用炉灶加热、把食物弄熟，为正确答案。", "做法": "fǎ（第三声）与 fàn（第四声）声调不同，「做法」意思是方法、做的办法。", "做反": "fǎn（第三声）与 fàn（第四声）声调不同，「做反」意思是做得与原来相反。", "罪犯": "zuì 与 zuò 韵母不同，「罪犯」（zuì fàn）意思是犯罪的人。"}, "sentence_index": null, "correct_answer": "做饭"}, "level_3": {"options": [{"text": "做饭", "is_correct": true, "explanation": "做饭：用小火炉加热、把食物弄熟，与「小火炉」搭配。"}, {"text": "看书", "is_correct": false, "explanation": "语义：用小火炉看书不合常理，句子说的是用炉子加热食物。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与用炉子加热食物无关。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：用小火炉跳舞不合常理，与句中用炉子加热食物的动作不符。"}], "explanations": {"做饭": "做饭：用小火炉加热、把食物弄熟，与「小火炉」搭配。", "看书": "语义：用小火炉看书不合常理，句子说的是用炉子加热食物。", "唱歌": "语义：唱歌与用炉子加热食物无关。", "跳舞": "语义：用小火炉跳舞不合常理，与句中用炉子加热食物的动作不符。"}, "sentence_index": 0, "correct_answer": "做饭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚坐下，就拿起菜单开始做饭。", "explanation": "这里应该用〈点菜〉。拿菜单点菜是点餐，做饭是用炉灶把食物弄熟，二者不能互换。"}, {"text": "妈妈早上去超市做饭。", "explanation": "这里应该用〈买菜〉。去超市是买菜，做饭要回家用炉灶进行。"}, {"text": "吃完饭，他去柜台做饭。", "explanation": "这里应该用〈付钱〉。去柜台是付钱，做饭是把食物弄熟，不表示结账。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做饭", "is_correct": true, "explanation": "做饭：用电磁炉加热、烹制食物，句意成立。"}, {"text": "擦洗", "is_correct": false, "explanation": "语义：擦洗是清洁，不是用电磁炉加热食物的过程。"}, {"text": "切菜", "is_correct": false, "explanation": "语义：切菜不依靠电磁炉加热，句中的「快」和「干净」与切菜无对应。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：「打扫」需要处所或物件作宾语，「用电磁炉打扫」残缺，不成立。"}], "explanations": {"做饭": "做饭：用电磁炉加热、烹制食物，句意成立。", "擦洗": "语义：擦洗是清洁，不是用电磁炉加热食物的过程。", "切菜": "语义：切菜不依靠电磁炉加热，句中的「快」和「干净」与切菜无对应。", "打扫": "配价：「打扫」需要处所或物件作宾语，「用电磁炉打扫」残缺，不成立。"}, "sentence_index": 6, "correct_answer": "做饭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每周六去理发店做饭。", "explanation": "这里应该用〈理发〉。去理发店是理发，做饭要用炉灶把食物弄熟，不在理发店里进行。"}, {"text": "周末我们去歌厅做饭。", "explanation": "这里应该用〈唱歌〉。去歌厅是唱歌，做饭要用炉灶加热食物。"}, {"text": "周末我们去游泳池做饭。", "explanation": "这里应该用〈游泳〉。去游泳池是游泳，做饭要用炉灶把食物弄熟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们做饭完了，就出发吧。", "corrected_sentence": "他们做完饭了，就出发吧。", "error_description": "「做饭完」错，结果补语「完」应紧接动词，应说「做完饭」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用高压锅做饭得很快，二十分钟就好了。", "corrected_sentence": "他用高压锅做饭做得很快，二十分钟就好了。", "error_description": "「做饭得很快」错，补语前动词「做」需要重复，应说「做饭做得很快」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
