INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25686, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从里面到外面。", "primary_collocate": null, "pronunciation": "chū lái", "ipa": "tʂʰu˥ lai˧˥", "syllable_count": 2, "sentences": [{"text": "里面太黑，我想出来。", "target_word": "出来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从教室里出来，去操场玩。", "target_word": "出来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你快从水里出来，别感冒了。", "target_word": "出来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子着火了，大家都跑出来了。", "target_word": "出来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们从学校里走出来。", "target_word": "出来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "兔子从洞里跳出来了。", "target_word": "出来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从电梯里出来，向我走来。", "target_word": "出来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟从窗户里飘出来。", "target_word": "出来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老鼠从洞里钻出来，又跑回去了。", "target_word": "出来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟从笼子里飞出来了。", "target_word": "出来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "出来了", "label": "体标（了）"}, {"form": "出来过", "label": "体标（过）"}, {"form": "出來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词/趋向：人或物从里面到外面来，如从屋里出来、飞出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ce08054-efb3-4993-b681-b57e21c2f1ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25686, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出来", "is_correct": true, "explanation": "“我想出来”表示想离开屋里的黑暗环境，是朝外移动，符合句意。"}, {"text": "起来", "is_correct": false, "explanation": "语义：“想起来”表示回想，与“里面太黑”的语境无关。"}, {"text": "进来", "is_correct": false, "explanation": "语义：进来是朝里移动，说话人已在里面，与想离开的语境相反。"}, {"text": "亮起来", "is_correct": false, "explanation": "搭配：“亮起来”指变亮，不能作“我想”的动作，句意不通。"}], "explanations": {"出来": "“我想出来”表示想离开屋里的黑暗环境，是朝外移动，符合句意。", "起来": "语义：“想起来”表示回想，与“里面太黑”的语境无关。", "进来": "语义：进来是朝里移动，说话人已在里面，与想离开的语境相反。", "亮起来": "搭配：“亮起来”指变亮，不能作“我想”的动作，句意不通。"}, "sentence_index": 0, "correct_answer": "出来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们从院子外面出来，一个个都满头大汗。", "explanation": "这里应该用〈进来〉。出来表示从里往外，“从院子外面”进入院子要用进来。"}, {"text": "他往屋里出来，拿了一把伞。", "explanation": "这里应该用〈进去〉。出来表示从里往外，“往屋里”是向内移动，要用进去。"}, {"text": "他沿着楼梯往楼上出来，找到了妈妈。", "explanation": "这里应该用〈上去〉。出来表示从里往外，“往楼上”是向上移动，要用上去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出来", "is_correct": true, "explanation": "“从电梯里出来”指从电梯内走到外面，与“向我走来”的方向一致。"}, {"text": "进去", "is_correct": false, "explanation": "语义：进去指向内移动，与“从电梯里出来”的方向相反，句子前后矛盾。"}, {"text": "上去", "is_correct": false, "explanation": "搭配：“从电梯里上去”搭配不当，不用于描述从电梯内走出的动作。"}, {"text": "回去", "is_correct": false, "explanation": "语义：回去指返回原处，与“向我走来”的朝向相反。"}], "explanations": {"出来": "“从电梯里出来”指从电梯内走到外面，与“向我走来”的方向一致。", "进去": "语义：进去指向内移动，与“从电梯里出来”的方向相反，句子前后矛盾。", "上去": "搭配：“从电梯里上去”搭配不当，不用于描述从电梯内走出的动作。", "回去": "语义：回去指返回原处，与“向我走来”的朝向相反。"}, "sentence_index": 6, "correct_answer": "出来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从沉睡中醒出来了，一时想不起发生了什么。", "explanation": "这里应该用〈过来〉。醒来、恢复知觉要用“过来”，“出来”不能表示这种状态变化。"}, {"text": "天气渐渐暖和出来了。", "explanation": "这里应该用〈起来〉。表示状态开始变化要用“起来”，不能用“出来”。"}, {"text": "听了这番话，他一下子安静出来了。", "explanation": "这里应该用〈下来〉。表示情绪由激动转为平静要用“下来”，“出来”不能表示这种变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她慢慢地从水里走出来来。", "corrected_sentence": "她慢慢地从水里走出来。", "error_description": "重复：“出来”的“来”字被重复，应说“她慢慢地从水里走出来”，不能说“走出来来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鸟从笼子里飞出来来，落在我面前。", "corrected_sentence": "小鸟从笼子里飞出来，落在我面前。", "error_description": "重复：“出来”的“来”字被重复，应说“小鸟从笼子里飞出来，落在我面前”，不能说“飞出来来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
