INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25690, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或工具在东西里转圈，让它们混在一起。", "primary_collocate": null, "pronunciation": "jiǎo bàn", "ipa": "tɕjɑʊ̯˨˩˦ pan˥˩", "syllable_count": 2, "sentences": [{"text": "酸奶太稠了，你先搅拌几下再吃。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸拿着筷子，在碗里搅拌鸡蛋。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把颜料和水搅拌在一起，颜色就变浅了。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙拉要搅拌均匀，每片菜才有酱。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边搅拌，一边往锅里加糖。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用小勺子搅拌杯子里的果汁。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做面包时，先把水和面粉搅拌成面团。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "粥快糊了，她赶紧搅拌了几下。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用力搅拌，不然盐不容易化开。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用长勺搅拌锅里的汤，怕它烧焦。", "target_word": "搅拌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搅拌了", "label": "体标（了）"}, {"form": "搅拌着", "label": "体标（着）"}, {"form": "搅拌过", "label": "体标（过）"}, {"form": "搅拌搅拌", "label": "重叠"}, {"form": "搅拌机", "label": "复合"}, {"form": "攪拌", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在东西里转圈使它们混在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ce08054-efb3-4993-b681-b57e21c2f1ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搅拌", "is_correct": true, "explanation": "正确：搅拌能让酸奶变稀均匀，与“先……几下再吃”相配。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿切断食物，酸奶不能这样处理。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是抹去污物，不能用来处理稠酸奶。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：“剪”要用剪刀等工具，不能与“酸奶”搭配。"}], "explanations": {"搅拌": "正确：搅拌能让酸奶变稀均匀，与“先……几下再吃”相配。", "咬": "语义：“咬”是用牙齿切断食物，酸奶不能这样处理。", "擦": "语义：“擦”是抹去污物，不能用来处理稠酸奶。", "剪": "搭配：“剪”要用剪刀等工具，不能与“酸奶”搭配。"}, "sentence_index": 0, "correct_answer": "搅拌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "喝之前，先把饮料瓶搅拌一下。", "explanation": "这里应该用〈晃〉。搅拌作用于瓶中的内容物；晃动饮料瓶要用“晃”。"}, {"text": "把豆子搅拌在水里一夜。", "explanation": "这里应该用〈泡〉。泡是把东西浸在水中；搅拌是转动混合，不能表示浸泡。"}, {"text": "他把头发搅拌了几下，就出门了。", "explanation": "这里应该用〈梳〉。梳头要用梳子；搅拌是在混合物中转动，不能用于头发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搅拌", "is_correct": true, "explanation": "正确：搅拌能把水和面粉混合成面团，与“成面团”相配。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆开、分解，水和面粉不能拆成面团。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗，把水和面粉洗成面团意思不通。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”的结果是块或片，不能与“成面团”搭配。"}], "explanations": {"搅拌": "正确：搅拌能把水和面粉混合成面团，与“成面团”相配。", "拆": "语义：“拆”是拆开、分解，水和面粉不能拆成面团。", "洗": "语义：“洗”是清洗，把水和面粉洗成面团意思不通。", "切": "搭配：“切”的结果是块或片，不能与“成面团”搭配。"}, "sentence_index": 6, "correct_answer": "搅拌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力搅拌了那张纸，把它撕成了两半。", "explanation": "这里应该用〈撕〉。撕是用力把纸扯开；搅拌是转动混合，不能用来撕纸。"}, {"text": "他用抹布搅拌桌子。", "explanation": "这里应该用〈擦〉。擦是抹去桌面的污物；搅拌不能用来擦桌子。"}, {"text": "拿扫帚把地搅拌干净。", "explanation": "这里应该用〈扫〉。扫是清除灰尘，搅拌不能用来清扫地面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他搅拌很均匀。", "corrected_sentence": "他搅拌得很均匀。", "error_description": "错误形式：“搅拌很均匀”；正确形式：“搅拌得很均匀”。动词后带形容词作补语时要用“得”引出，漏掉“得”就不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我刚才搅拌了过这锅汤。", "corrected_sentence": "我刚才搅拌过这锅汤。", "error_description": "错误形式：“搅拌了过”；正确形式：“搅拌过”。表示曾经做过某个动作时只用“过”，“了”和“过”不能同时用在同一动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dec0f0e-69e3-4ce0-b29d-bf055e4647d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
