INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25692, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "盖住容器口的东西。", "primary_collocate": null, "pronunciation": "gài zi", "ipa": "kaɪ˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "我忘了盖上盖子，饼干都软了。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖罐的盖子丢了，糖里进了蚂蚁。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力拧，可是盖子怎么也打不开。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盖子太小，盖不住那个锅。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水壶的盖子是塑料做的。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盖子打开后，香味一下子跑了出来。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把垃圾桶的盖子盖上。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫跳上去，碰掉了茶壶的盖子。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酸奶的盖子上有一层薄膜。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤快熬好了，你把盖子盖上，别让热气跑掉。", "target_word": "盖子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个盖子", "label": "量词"}, {"form": "盖儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "盖住容器口的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7463c093-f860-4636-af40-85cf1daafb3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25692, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盖子", "is_correct": true, "explanation": "正确答案：盖子（gài zi）是盖住容器口的东西。"}, {"text": "袋子", "is_correct": false, "explanation": "袋子（dài zi）：dài 与 gài 声母不同（d/g），意思是装东西的口袋。"}, {"text": "太子", "is_correct": false, "explanation": "太子（tài zi）：tài 与 gài 只差声母（t/g），声调相同，意思是帝王的继承人。"}, {"text": "个子", "is_correct": false, "explanation": "个子（gè zi）：gè 与 gài 韵母不同（e/ai），意思是身高。"}, {"text": "麦子", "is_correct": false, "explanation": "麦子（mài zi）：mài 与 gài 只差声母（m/g），声调相同，意思是小麦。"}], "explanations": {"盖子": "正确答案：盖子（gài zi）是盖住容器口的东西。", "袋子": "袋子（dài zi）：dài 与 gài 声母不同（d/g），意思是装东西的口袋。", "太子": "太子（tài zi）：tài 与 gài 只差声母（t/g），声调相同，意思是帝王的继承人。", "个子": "个子（gè zi）：gè 与 gài 韵母不同（e/ai），意思是身高。", "麦子": "麦子（mài zi）：mài 与 gài 只差声母（m/g），声调相同，意思是小麦。"}, "sentence_index": null, "correct_answer": "盖子"}, "level_3": {"options": [{"text": "盖子", "is_correct": true, "explanation": "盖子能把饼干罐封住，防止饼干变软，符合“忘了盖上盖子”。"}, {"text": "被子", "is_correct": false, "explanation": "语义：被子不能盖住饼干罐，与“饼干都软了”的语境不符。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：盖住容器用“盖上”，窗户要用“关”。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：眼睛要用“闭”，不说“盖上”。"}], "explanations": {"盖子": "盖子能把饼干罐封住，防止饼干变软，符合“忘了盖上盖子”。", "被子": "语义：被子不能盖住饼干罐，与“饼干都软了”的语境不符。", "窗户": "搭配：盖住容器用“盖上”，窗户要用“关”。", "眼睛": "搭配：眼睛要用“闭”，不说“盖上”。"}, "sentence_index": 0, "correct_answer": "盖子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一张盖子，盖不住那个锅。", "explanation": "这里的量词用错了。“张”用于纸、桌子这类平的东西，盖子是立体的器具，不能用“张”来数。"}, {"text": "这个盖子太小，装不下那些饭。", "explanation": "这里应该用〈饭盒〉。盖子是盖在容器口上的，不能用来装饭。"}, {"text": "他用盖子切了一棵白菜。", "explanation": "这里应该用〈菜刀〉。盖子是盖在容器口上的，不能用来切菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25692, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "盖子", "is_correct": true, "explanation": "正确答案：盖子（gài zi）是盖住容器口的东西。"}, {"text": "癞子", "is_correct": false, "explanation": "癞子（lài zi）：lài 与 gài 只差声母（l/g），声调相同，意思是麻将里的百搭牌。"}, {"text": "带子", "is_correct": false, "explanation": "带子（dài zi）：dài 与 gài 只差声母（d/g），声调相同，意思是带状物。"}, {"text": "鸽子", "is_correct": false, "explanation": "鸽子（gē zi）：gē 与 gài 声母相同，韵母与声调不同，意思是鸟类。"}], "explanations": {"盖子": "正确答案：盖子（gài zi）是盖住容器口的东西。", "癞子": "癞子（lài zi）：lài 与 gài 只差声母（l/g），声调相同，意思是麻将里的百搭牌。", "带子": "带子（dài zi）：dài 与 gài 只差声母（d/g），声调相同，意思是带状物。", "鸽子": "鸽子（gē zi）：gē 与 gài 声母相同，韵母与声调不同，意思是鸟类。"}, "sentence_index": null, "correct_answer": "盖子"}, "level_3": {"options": [{"text": "盖子", "is_correct": true, "explanation": "盖子是可以盖上的部分，符合“请把垃圾桶的盖子盖上”。"}, {"text": "门", "is_correct": false, "explanation": "搭配：盖的是容器上的盖，门要用“关”，不说“盖上”。"}, {"text": "把手", "is_correct": false, "explanation": "语义：把手不能被盖上，与“盖上”的动作不符。"}, {"text": "轮子", "is_correct": false, "explanation": "语义：轮子不能被盖上，垃圾桶上不存在这种盖。"}], "explanations": {"盖子": "盖子是可以盖上的部分，符合“请把垃圾桶的盖子盖上”。", "门": "搭配：盖的是容器上的盖，门要用“关”，不说“盖上”。", "把手": "语义：把手不能被盖上，与“盖上”的动作不符。", "轮子": "语义：轮子不能被盖上，垃圾桶上不存在这种盖。"}, "sentence_index": 6, "correct_answer": "盖子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "盖子里的水烧开了。", "explanation": "这里应该用〈水壶〉。盖子不能盛水，也不是盛水的容器。"}, {"text": "他用盖子削苹果。", "explanation": "这里应该用〈水果刀〉。盖子是盖在容器口上的，不能用来削东西。"}, {"text": "孩子拿着盖子舀汤。", "explanation": "这里应该用〈勺子〉。盖子是盖在容器口上的，不能用来舀汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拿起一条盖子，看了看。", "corrected_sentence": "他拿起一个盖子，看了看。", "error_description": "量词错误：盖子应用通用量词「个」；「条」用于细长的东西，不能用来数盖子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我盖子放在桌上。", "corrected_sentence": "我把盖子放在桌上。", "error_description": "把字句漏掉“把”：盖子是被放置的对象，须用“把”引出，应说“我把盖子放在桌上”，不说“我盖子放在桌上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2448619-7937-4347-b409-14c167b9f3ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
