INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25706, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西用火烧掉。", "primary_collocate": null, "pronunciation": "fén shāo", "ipa": "fən˧˥ ʂɑʊ˥˥", "syllable_count": 2, "sentences": [{"text": "他把旧照片全都焚烧了。", "target_word": "焚烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民在田里焚烧干草。", "target_word": "焚烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要在公园里焚烧垃圾。", "target_word": "焚烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们决定焚烧这些没用的文件。", "target_word": "焚烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "焚烧塑料会放出有害气体。", "target_word": "焚烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争中，敌人焚烧了村子。", "target_word": "焚烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祭祀时，人们焚烧纸钱。", "target_word": "焚烧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林边上禁止焚烧任何东西。", "target_word": "焚烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人焚烧完枯枝，就回家了。", "target_word": "焚烧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把没用的信件放进炉子里焚烧。", "target_word": "焚烧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "焚烧了", "label": "体标"}, {"form": "焚烧着", "label": "体标"}, {"form": "焚烧过", "label": "体标"}], "register": "中性", "sense_fingerprint": "有意把物品放进火里烧掉，如信件、纸钱、枯草", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ae535a-9ea1-4936-80af-cc9fd7df8a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焚烧", "is_correct": true, "explanation": "正确。「他把旧照片全都焚烧了」中，焚烧指把照片烧掉。"}, {"text": "扫", "is_correct": false, "explanation": "搭配：「扫」多用于灰尘、落叶，不能说扫照片。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」指进食，照片不能吃。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」指歌唱，照片不能唱。"}], "explanations": {"焚烧": "正确。「他把旧照片全都焚烧了」中，焚烧指把照片烧掉。", "扫": "搭配：「扫」多用于灰尘、落叶，不能说扫照片。", "吃": "语义：「吃」指进食，照片不能吃。", "唱": "语义：「唱」指歌唱，照片不能唱。"}, "sentence_index": 0, "correct_answer": "焚烧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春天的雪在阳光下焚烧了。", "explanation": "这里应该用〈融化〉。雪受热是融化，焚烧指烧毁，不能用于雪。"}, {"text": "这台机器能焚烧空气。", "explanation": "这里应该用〈净化〉。净化指去除空气中的杂质，焚烧指烧毁物品，机器不能焚烧空气。"}, {"text": "她把脏碗放进洗碗机里焚烧。", "explanation": "这里应该用〈清洗〉。清洗指用水或洗涤剂去除餐具上的污物，焚烧是用火烧毁，碗放进机器去污应说清洗，不能说焚烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焚烧", "is_correct": true, "explanation": "正确。祭祀时人们焚烧纸钱，是把纸钱烧掉的习俗。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：「嚼」指用牙齿咀嚼食物，纸钱不能嚼来用于祭祀。"}, {"text": "挖", "is_correct": false, "explanation": "语义：「挖」指从土中取出东西，与祭祀用纸钱的动作无关。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：「喂」用于人、动物等进食，不能说喂纸钱。"}], "explanations": {"焚烧": "正确。祭祀时人们焚烧纸钱，是把纸钱烧掉的习俗。", "嚼": "语义：「嚼」指用牙齿咀嚼食物，纸钱不能嚼来用于祭祀。", "挖": "语义：「挖」指从土中取出东西，与祭祀用纸钱的动作无关。", "喂": "搭配：「喂」用于人、动物等进食，不能说喂纸钱。"}, "sentence_index": 6, "correct_answer": "焚烧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民用水焚烧麦田。", "explanation": "这里应该用〈灌溉〉。灌溉是用水浇地，水不能用来焚烧麦田。"}, {"text": "妈妈用平底锅焚烧鸡蛋。", "explanation": "这里应该用〈煎〉。煎是用少量油加热食物，焚烧是烧毁，做鸡蛋不能说焚烧。"}, {"text": "面团在温暖的地方焚烧了。", "explanation": "这里应该用〈发酵〉。发酵是面团受微生物作用而膨胀，温暖处的面团不会焚烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们曾经焚烧了过这些旧文件。", "corrected_sentence": "他们曾经焚烧过这些旧文件。", "error_description": "表示经历过某事要用动词后的「过」，「了」与「过」不能同时出现。正确形式是「焚烧过」，「焚烧了过」错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把旧信焚烧。", "corrected_sentence": "他把旧信焚烧了。", "error_description": "「把」字句中，动词后通常要带「了」或其他补语，句子才完整。正确形式是「把旧信焚烧了」，「他把旧信焚烧」语义不完整。", "correct_sentence_indices": [6, 7, 8]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25710, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现象", "is_correct": true, "explanation": "与“本质”构成反义：现象指事物表现于外的样子，与其内在根本属性相对。"}, {"text": "声音", "is_correct": false, "explanation": "不构成反义：声音与“本质”之间没有对立关系。"}, {"text": "桌子", "is_correct": false, "explanation": "不构成反义：桌子是具体事物，与“本质”不是对立概念。"}, {"text": "雨水", "is_correct": false, "explanation": "不构成反义：雨水与“本质”没有对立关系。"}], "correct_answer": "现象", "explanations": {"现象": "与“本质”构成反义：现象指事物表现于外的样子，与其内在根本属性相对。", "声音": "不构成反义：声音与“本质”之间没有对立关系。", "桌子": "不构成反义：桌子是具体事物，与“本质”不是对立概念。", "雨水": "不构成反义：雨水与“本质”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25710, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现象", "is_correct": true, "explanation": "与“本质”构成反义：现象指事物表现于外的样子，与其内在根本属性相对。"}, {"text": "价格", "is_correct": false, "explanation": "不构成反义：价格与“本质”没有对立关系。"}, {"text": "花朵", "is_correct": false, "explanation": "不构成反义：花朵是具体事物，与“本质”不是对立概念。"}, {"text": "乐器", "is_correct": false, "explanation": "不构成反义：乐器与“本质”之间没有对立关系。"}], "correct_answer": "现象", "explanations": {"现象": "与“本质”构成反义：现象指事物表现于外的样子，与其内在根本属性相对。", "价格": "不构成反义：价格与“本质”没有对立关系。", "花朵": "不构成反义：花朵是具体事物，与“本质”不是对立概念。", "乐器": "不构成反义：乐器与“本质”之间没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25710, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "就是它本来的样子。", "primary_collocate": null, "pronunciation": "qí běn zhì", "ipa": "tɕʰi˧˥ pən˨˩ ʈʂɹ̩˥˩", "syllable_count": 3, "sentences": [{"text": "这家店看着很大，其本质只是个仓库。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩具再漂亮，其本质还是玩具。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴上很凶，其本质是个好人。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果糖看起来不同，其本质都是糖。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换了名字，其本质并没有变。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛，其本质是两种想法的比较。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两款产品包装完全不同，其本质却是一样的。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的规则很多，其本质很简单。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看书不是为了炫耀，其本质是学习。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机再新，其本质还是打电话的工具。", "target_word": "其本质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "它本来的样子，根本的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12bffa6a-c330-4612-90ca-b7a2113d6df9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "其本质", "is_correct": true, "explanation": "正确：“其本质”指它本来的样子，此处说店的实际性质，与“看着很大”形成对比。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是金额，不能说明店的本来性质，“只是个仓库”不成立。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是外观，与“只是个仓库”所说的性质无关。"}, {"text": "灯光", "is_correct": false, "explanation": "语义：灯光是照明的光线，不能说“只是个仓库”，与句意不符。"}], "explanations": {"其本质": "正确：“其本质”指它本来的样子，此处说店的实际性质，与“看着很大”形成对比。", "价格": "语义：价格是金额，不能说明店的本来性质，“只是个仓库”不成立。", "颜色": "语义：颜色是外观，与“只是个仓库”所说的性质无关。", "灯光": "语义：灯光是照明的光线，不能说“只是个仓库”，与句意不符。"}, "sentence_index": 0, "correct_answer": "其本质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这箱苹果，其本质有二十个。", "explanation": "〈其本质〉指事物本来的样子，不能用来计数，这里把它当作〈数量〉来用。应说「这箱苹果有二十个」。"}, {"text": "这间教室，其本质在操场上。", "explanation": "〈其本质〉指事物本来的样子，这里却当作〈位置〉来用，说它在某个地方。应说「这间教室在操场旁边」。"}, {"text": "这颗糖，其本质卖五块钱。", "explanation": "〈其本质〉指事物本来的样子，这里把它当作〈价格〉来用，说它卖多少钱。应说「这颗糖卖五块钱」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "其本质", "is_correct": true, "explanation": "正确：“其本质”指事物内在的根本性质，与“包装完全不同”形成对比，是两款产品实际相同之处。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲与“两款产品”无关，“歌曲却是一样的”不通。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵与“两款产品”无关，“花朵却是一样的”不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是产品的根本性质，“天气却是一样的”与“包装完全不同”的对比不通。"}], "explanations": {"其本质": "正确：“其本质”指事物内在的根本性质，与“包装完全不同”形成对比，是两款产品实际相同之处。", "歌曲": "语义：歌曲与“两款产品”无关，“歌曲却是一样的”不通。", "花朵": "语义：花朵与“两款产品”无关，“花朵却是一样的”不通。", "天气": "语义：天气不是产品的根本性质，“天气却是一样的”与“包装完全不同”的对比不通。"}, "sentence_index": 6, "correct_answer": "其本质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影，其本质昨天就上映了。", "explanation": "〈其本质〉指事物本来的样子，不能作为“上映”的主语，这里把它当作〈影片〉来用。应说「这部电影昨天就上映了」。"}, {"text": "这台收音机，其本质很大声。", "explanation": "〈其本质〉是抽象的本来样子，不能用来描述声音的大小，这里把它当作〈音量〉来用。应说「这台收音机的声音很大」。"}, {"text": "这只猫，其本质跑得很快。", "explanation": "〈其本质〉不能作为动作的主语，这里把它当作〈动物〉来用。应说「这只猫跑得很快」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电脑外壳很旧，很其本质还是好的。", "corrected_sentence": "这台电脑外壳很旧，其本质还是好的。", "error_description": "“其本质”是名词性成分，前面不能加副词“很”，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校的名声很大，其本质了是个培训班。", "corrected_sentence": "这所学校的名声很大，其本质是个培训班。", "error_description": "“了”是动态助词，不能用在名词性的“其本质”之后，应删去“了”，说“其本质是个培训班”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
