INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25712, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个东西里的一些部分，合起来就是它。", "primary_collocate": null, "pronunciation": "zǔ chéng bù fen", "ipa": "tsu˨˩ ʈʂʰɤŋ˧˥ pu˥˩ fən", "syllable_count": 4, "sentences": [{"text": "请把电脑的各个组成部分摆在桌上。", "target_word": "组成部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的组成部分很多。", "target_word": "组成部分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道自行车有哪些组成部分吗？", "target_word": "组成部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先看一下手机的组成部分。", "target_word": "组成部分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花的组成部分有花瓣、花蕊和花茎。", "target_word": "组成部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具有十个组成部分，要自己装。", "target_word": "组成部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钟表拆开，看每个组成部分。", "target_word": "组成部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的组成部分包括墙、门和屋顶。", "target_word": "组成部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的组成部分有封面和正文。", "target_word": "组成部分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车最重要的组成部分是发动机。", "target_word": "组成部分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "一件具体物品由哪些零件或部件合成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ae535a-9ea1-4936-80af-cc9fd7df8a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25712, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "组成部分", "is_correct": true, "explanation": "组成部分指具体物件由哪些部件合成。此处说电脑的各个部件，语义吻合。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间”是空间场所，不是电脑的部件，“各个房间摆在桌上”说不通。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不能与“电脑的”搭配，二者没有领属关系。"}, {"text": "零食", "is_correct": false, "explanation": "语义：“零食”指可吃的食品，不是电脑的构成部件，句意荒谬。"}], "explanations": {"组成部分": "组成部分指具体物件由哪些部件合成。此处说电脑的各个部件，语义吻合。", "房间": "语义：“房间”是空间场所，不是电脑的部件，“各个房间摆在桌上”说不通。", "作业": "搭配：“作业”不能与“电脑的”搭配，二者没有领属关系。", "零食": "语义：“零食”指可吃的食品，不是电脑的构成部件，句意荒谬。"}, "sentence_index": 0, "correct_answer": "组成部分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们先看一下手机的一扇组成部分。", "explanation": "这里应该用〈个〉。“扇”用于门、窗等，不用来计量手机的零件。"}, {"text": "我们先看一下手机的一条组成部分。", "explanation": "这里应该用〈个〉。“条”用于河流、道路等细长的东西，不用来计量手机的部件。"}, {"text": "我们先看一下手机的一座组成部分。", "explanation": "这里应该用〈个〉。“座”用于山、桥、建筑等大型固定物，手机零件不能用“座”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "组成部分", "is_correct": true, "explanation": "组成部分指具体物件的各个部件。拆开钟表后看每个部件，语义吻合。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”的对象应是看得见的东西，“声音”应与“听”搭配，“看每个声音”搭配不当。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指商品的价值，与拆开钟表后观察各部分的情境无关。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是气象状况，不能在拆开钟表时被“看每个”观察。"}], "explanations": {"组成部分": "组成部分指具体物件的各个部件。拆开钟表后看每个部件，语义吻合。", "声音": "搭配：“看”的对象应是看得见的东西，“声音”应与“听”搭配，“看每个声音”搭配不当。", "价格": "语义：“价格”指商品的价值，与拆开钟表后观察各部分的情境无关。", "天气": "语义：“天气”是气象状况，不能在拆开钟表时被“看每个”观察。"}, "sentence_index": 6, "correct_answer": "组成部分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车最重要的一本组成部分是发动机。", "explanation": "这里应该用〈个〉。“本”用于书籍、册子，不用来计量汽车的部件。"}, {"text": "汽车最重要的一张组成部分是发动机。", "explanation": "这里应该用〈个〉。“张”用于纸、桌子等平面的东西，不用来计量发动机这类部件。"}, {"text": "汽车最重要的一把组成部分是发动机。", "explanation": "这里应该用〈个〉。“把”用于有柄的器具，不用来计量汽车的组成部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把收音机的每本组成部分全部拆开了。", "corrected_sentence": "他把收音机的每个组成部分全部拆开了。", "error_description": "量词误用：“组成部分”前的量词应为“个”，“本”用于书籍、册子，不能用来计量收音机的部件，应为「每个组成部分」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把收音机拆开，看每根组成部分。", "corrected_sentence": "他把收音机拆开，看每个组成部分。", "error_description": "量词误用：“根”用于细长的条状物，不能用来计量组成部分，“每”后应用“个”，应说「每个组成部分」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
