INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25714, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "处置就是对事情或物品进行处理，按情况加以安排、解决，比如把问题解决掉、把旧东西处理掉。", "primary_collocate": null, "pronunciation": "chǔ zhì", "ipa": "ʈʂʰu˨˩ ʈʂɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "遇到麻烦事，要冷静处置。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题，村里很快就处置好了。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师正在处置课堂上的小争吵。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的旧家具，你打算怎么处置？", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他处置事情一向很果断。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次火灾，消防队处置得很及时。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区的垃圾要按规定处置。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这件投诉，客服中心已经处置了。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们先别急，我来处置这件事。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理没有马上处置这个问题。", "target_word": "处置", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处置了", "label": "体标"}, {"form": "处置过", "label": "体标"}, {"form": "处置方式", "label": "复合"}, {"form": "处置权", "label": "复合"}], "register": "书面", "sense_fingerprint": "处理事情或物品，加以安排解决", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12bffa6a-c330-4612-90ca-b7a2113d6df9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25714, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "处置", "is_correct": true, "explanation": "处置（chǔ zhì）：正确答案，意思是处理事情、把问题解决掉。"}, {"text": "主治", "is_correct": false, "explanation": "声母不同：zhǔ 的 zh 与 chǔ 的 ch 不同，意思是医生治疗疾病。"}, {"text": "储值", "is_correct": false, "explanation": "第二个音节声调不同：zhí 与 zhì 不同，意思是把钱存入以备使用。"}, {"text": "初志", "is_correct": false, "explanation": "第一个音节声调不同：chū 与 chǔ 不同，意思是最初的志向。"}, {"text": "初值", "is_correct": false, "explanation": "两个音节的声调都不同：chū、zhí 与 chǔ、zhì 不同，意思是最初的数值。"}], "explanations": {"处置": "处置（chǔ zhì）：正确答案，意思是处理事情、把问题解决掉。", "主治": "声母不同：zhǔ 的 zh 与 chǔ 的 ch 不同，意思是医生治疗疾病。", "储值": "第二个音节声调不同：zhí 与 zhì 不同，意思是把钱存入以备使用。", "初志": "第一个音节声调不同：chū 与 chǔ 不同，意思是最初的志向。", "初值": "两个音节的声调都不同：chū、zhí 与 chǔ、zhì 不同，意思是最初的数值。"}, "sentence_index": null, "correct_answer": "处置"}, "level_3": {"options": [{"text": "处置", "is_correct": true, "explanation": "处置：意思是冷静地处理麻烦事，符合句意。"}, {"text": "原谅", "is_correct": false, "explanation": "配价：“原谅”的宾语应是人或过错，麻烦事不能被原谅。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指享有快乐或好的事物，麻烦事不能用享受。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象是客人或意见，不能说欢迎麻烦事。"}], "explanations": {"处置": "处置：意思是冷静地处理麻烦事，符合句意。", "原谅": "配价：“原谅”的宾语应是人或过错，麻烦事不能被原谅。", "享受": "语义：“享受”指享有快乐或好的事物，麻烦事不能用享受。", "欢迎": "搭配：“欢迎”的对象是客人或意见，不能说欢迎麻烦事。"}, "sentence_index": 0, "correct_answer": "处置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很会处置自己的午饭，大家都说他吃得香。", "explanation": "这里应该用〈吃〉。处置用于事情或问题，吃饭应说吃。"}, {"text": "我们处置了一场精彩的音乐会。", "explanation": "这里应该用〈欣赏〉。处置用于事情或问题，观看音乐会应说欣赏。"}, {"text": "我们处置了一个安静的周末。", "explanation": "这里应该用〈度过〉。处置用于事情或问题，一段时间应说度过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "处置", "is_correct": true, "explanation": "处置：意思是按规定处理垃圾，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指喜爱美好的事物，垃圾不能被欣赏。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”要求带指人的宾语，垃圾不能被感谢。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”的宾语应是申请、计划等，不能说批准垃圾。"}], "explanations": {"处置": "处置：意思是按规定处理垃圾，符合句意。", "欣赏": "语义：“欣赏”指喜爱美好的事物，垃圾不能被欣赏。", "感谢": "配价：“感谢”要求带指人的宾语，垃圾不能被感谢。", "批准": "搭配：“批准”的宾语应是申请、计划等，不能说批准垃圾。"}, "sentence_index": 6, "correct_answer": "处置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "摄影师处置了美丽的风景，照片拍得很好。", "explanation": "这里应该用〈拍摄〉。处置用于事情或问题，拍照应说拍摄。"}, {"text": "妹妹在台上处置了一首小提琴曲。", "explanation": "这里应该用〈演奏〉。处置用于事情或问题，演奏乐曲应说演奏。"}, {"text": "他处置了一首古诗，老师很满意。", "explanation": "这里应该用〈背诵〉。处置用于事情或问题，背古诗应说背诵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校长正在处置了这场纠纷。", "corrected_sentence": "校长正在处置这场纠纷。", "error_description": "错误：“正在”表示动作正在进行，不能与“了”同用，应说“正在处置这场纠纷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经把那批垃圾处置。", "corrected_sentence": "我们已经把那批垃圾处置了。", "error_description": "错误：“已经”表示动作已完成，“处置”后要加“了”，应说“我们已经把那批垃圾处置了”，不能省去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
