INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "吃剩下的东西。", "primary_collocate": null, "pronunciation": "shí wù cán zhā", "ipa": "ʂʐ̩˧˥ u˥˩ tsʰan˧˥ ʈʂa˥", "syllable_count": 4, "sentences": [{"text": "吃完饭，桌上还有一些食物残渣。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在地上找食物残渣。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把食物残渣倒进垃圾桶。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅里留着一点食物残渣。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刷牙可以去掉嘴里的食物残渣。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盘子上的食物残渣要先擦掉。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞来吃地上的食物残渣。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食物残渣不扔，厨房就会有虫子。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子吃饭时，地上掉了很多食物残渣。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天把食物残渣收集起来做肥。", "target_word": "食物残渣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "残渣", "label": "简称"}, {"form": "食物殘渣", "label": "繁体"}], "register": "口语", "sense_fingerprint": "吃剩下的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12bffa6a-c330-4612-90ca-b7a2113d6df9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食物残渣", "is_correct": true, "explanation": "正确：吃完饭后桌上剩下的碎屑就是食物残渣，与“吃完饭”相符。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不可能是饭后桌上的剩余物，与“吃完饭”的语境矛盾。"}, {"text": "洗洁精", "is_correct": false, "explanation": "搭配：“洗洁精”通常放在水槽边，不与“桌上还有”搭配。"}, {"text": "钢筋", "is_correct": false, "explanation": "语义：钢筋不会是饭后剩下的东西，与“吃完饭”的语境不符。"}], "explanations": {"食物残渣": "正确：吃完饭后桌上剩下的碎屑就是食物残渣，与“吃完饭”相符。", "汽油": "语义：汽油不可能是饭后桌上的剩余物，与“吃完饭”的语境矛盾。", "洗洁精": "搭配：“洗洁精”通常放在水槽边，不与“桌上还有”搭配。", "钢筋": "语义：钢筋不会是饭后剩下的东西，与“吃完饭”的语境不符。"}, "sentence_index": 0, "correct_answer": "食物残渣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把食物残渣当作礼物送给了朋友。", "explanation": "这里把〈食物残渣〉当作〈礼物〉来用。食物残渣是吃剩下的东西，不能拿来送人。"}, {"text": "我在炒菜时放了一点食物残渣。", "explanation": "这里应该用〈调料〉。食物残渣不能用来调味，炒菜时放的应是调料。"}, {"text": "桌上有一根食物残渣。", "explanation": "量词：“根”用于细长的东西，食物残渣是碎屑，应说“一点”或“一些”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食物残渣", "is_correct": true, "explanation": "正确：小鸟会啄食地上掉落的食物碎屑，与“飞来吃”相符。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是食物，小鸟不会把它当作食物啄食。"}, {"text": "硬币", "is_correct": false, "explanation": "搭配：“吃”的对象多为食物，“硬币”不能与“吃”搭配。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是非食物，小鸟不会吃，与“飞来吃”的语境矛盾。"}], "explanations": {"食物残渣": "正确：小鸟会啄食地上掉落的食物碎屑，与“飞来吃”相符。", "钥匙": "语义：钥匙不是食物，小鸟不会把它当作食物啄食。", "硬币": "搭配：“吃”的对象多为食物，“硬币”不能与“吃”搭配。", "玻璃": "语义：玻璃是非食物，小鸟不会吃，与“飞来吃”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "食物残渣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈做好了食物残渣。", "explanation": "这里应该用〈饭菜〉。食物残渣是吃剩的碎屑，不能当做好的饭菜端上桌，应说“饭菜”。"}, {"text": "孩子买了一包食物残渣。", "explanation": "这里应该用〈糖果〉。食物残渣不能买卖，孩子买的应是糖果。"}, {"text": "他把一块食物残渣当成蛋糕吃了。", "explanation": "这里把〈食物残渣〉当作〈蛋糕〉来用。食物残渣指吃剩下的东西，不能当成蛋糕吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子把一根食物残渣扔进了垃圾桶。", "corrected_sentence": "孩子把一点食物残渣扔进了垃圾桶。", "error_description": "量词错误：食物残渣是碎屑，不能用“根”（“根”用于细长的东西）；应说“一点食物残渣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地上掉了一个食物残渣。", "corrected_sentence": "地上掉了一堆食物残渣。", "error_description": "量词错误：食物残渣是碎屑，多成堆，应说“一堆食物残渣”；用“个”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
