INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25720, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "这个词表示某个东西里面含有另一些东西。", "primary_collocate": null, "pronunciation": "bāo hán", "ipa": "pɑʊ̯˥ xan˧˥", "syllable_count": 2, "sentences": [{"text": "这个菜里包含很多蔬菜。", "target_word": "包含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶果汁包含大量的糖。", "target_word": "包含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书包含了十个小故事。", "target_word": "包含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个套餐包含了一杯咖啡。", "target_word": "包含", "complexity_tier": "T3", "furigana": "zhè gè tào cān bāo hán le yì bēi kā fēi", "sentence_source": "generated"}, {"text": "这个词包含好几个意思。", "target_word": "包含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话里包含着很深的感情。", "target_word": "包含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告包含哪些内容？", "target_word": "包含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶包含丰富的蛋白质。", "target_word": "包含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房租包含水费和电费。", "target_word": "包含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划包含三个步骤。", "target_word": "包含", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "包含了", "label": "体标"}, {"form": "包含着", "label": "体标"}], "register": "中性", "sense_fingerprint": "整体里面含有某些部分或内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027318f4-2b33-4396-a5c8-0febbc57a5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25720, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包含", "is_correct": true, "explanation": "包含：表示菜里含有蔬菜，与句意一致。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求有生命的施事，“这个菜里”不能作施事去吃蔬菜。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”表示切割的动作，不表示里面含有某物。"}, {"text": "吐", "is_correct": false, "explanation": "搭配：“吐”与“这个菜里”的组合说不通，无法表示菜里有蔬菜。"}], "explanations": {"包含": "包含：表示菜里含有蔬菜，与句意一致。", "吃": "配价：“吃”要求有生命的施事，“这个菜里”不能作施事去吃蔬菜。", "切": "语义：“切”表示切割的动作，不表示里面含有某物。", "吐": "搭配：“吐”与“这个菜里”的组合说不通，无法表示菜里有蔬菜。"}, "sentence_index": 0, "correct_answer": "包含"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈总是包含我的错误。", "explanation": "这里应该用〈包容〉。包容指宽容、接纳别人的过错；包含指里面含有某些内容，不能用来表示宽容。"}, {"text": "他包含了犯罪的朋友。", "explanation": "这里应该用〈包庇〉。“包庇”指袒护坏人、隐瞒其错误；“包含”只表示里面有某物，不能用来表示袒护，应说“他包庇了犯罪的朋友”。"}, {"text": "她包含了一个孩子。", "explanation": "这里应该用〈怀〉。“怀”表示孕育，用于人怀孕；“包含”不能用来说人怀孕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包含", "is_correct": true, "explanation": "包含：表示报告里含有哪些内容，与句意一致。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的施事须是能饮用的人或动物，“这份报告”不能作施事去喝内容。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”的施事须是能唱歌的人，“报告”不能唱哪些内容。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”指把衣物穿在身上，不能用于报告的内容。"}], "explanations": {"包含": "包含：表示报告里含有哪些内容，与句意一致。", "喝": "配价：“喝”的施事须是能饮用的人或动物，“这份报告”不能作施事去喝内容。", "唱": "配价：“唱”的施事须是能唱歌的人，“报告”不能唱哪些内容。", "穿": "语义：“穿”指把衣物穿在身上，不能用于报告的内容。"}, "sentence_index": 6, "correct_answer": "包含"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我包含了这个计划的三个步骤。", "explanation": "这里应该用〈参与〉。“参与”指加入某项活动；“包含”的主语必须是整体，这句让“我”充当包含者，主客颠倒。应说“我参与了这个计划的三个步骤”。"}, {"text": "三个步骤包含了这个计划。", "explanation": "这里应该用〈组成〉。“组成”说部分构成整体；这句把“三个步骤”（部分）当作包含者、“这个计划”（整体）当作内容，主客颠倒。应说“三个步骤组成这个计划”。"}, {"text": "我们三个人包含了这个计划。", "explanation": "这里应该用〈承担〉。“承担”指接受并负责某项任务；“包含”的主语只能是整体，这句把“我们三个人”当作包含者，不能用来表示负责计划。应说“我们三个人承担了这个计划”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个包装盒很包含一本说明书。", "corrected_sentence": "这个包装盒里包含一本说明书。", "error_description": "错误在于“很”。“很”不能修饰“包含”这类动作动词；表示所在位置应用“里”，应说“包装盒里包含”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份文件包含报告里。", "corrected_sentence": "这份文件包含在报告里。", "error_description": "错误在于漏掉“在”。“包含在……里”表示被包含于某处，“在”不能省略，应说“包含在报告里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
