INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25724, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25724, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "因为这件事，所以我们想个办法。", "primary_collocate": null, "pronunciation": "yǒu jiàn yú cǐ", "ipa": "joʊ̯˨˩ tɕjɛn˥˩ y˧˥ tsʰɹ̩˨˩", "syllable_count": 4, "sentences": [{"text": "路上经常堵车，有鉴于此，我改坐地铁。", "target_word": "有鉴于此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月投诉很多，有鉴于此，我们想了一个新办法。", "target_word": "有鉴于此", "complexity_tier": "T3", "furigana": "zhège yuè tóusù hěn duō, yǒu jiàn yú cǐ, wǒmen xiǎng le yí ge xīn bànfǎ.", "sentence_source": "generated"}, {"text": "去年夏天太热，有鉴于此，今年我们早做准备。", "target_word": "有鉴于此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子总是迟到，有鉴于此，妈妈让他早睡。", "target_word": "有鉴于此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生总是走神，有鉴于此，老师换了上课的方式。", "target_word": "有鉴于此", "complexity_tier": "T3", "furigana": "xuésheng zǒngshì zǒushén, yǒu jiàn yú cǐ, lǎoshī huàn le shàngkè de fāngshì.", "sentence_source": "generated"}, {"text": "商店的东西卖不完，有鉴于此，老板降价了。", "target_word": "有鉴于此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上街道很暗，有鉴于此，小区装了新的路灯。", "target_word": "有鉴于此", "complexity_tier": "T3", "furigana": "wǎnshang jiēdào hěn àn, yǒu jiàn yú cǐ, xiǎoqū zhuāng le xīn de lùdēng.", "sentence_source": "generated"}, {"text": "公园里垃圾很多，有鉴于此，大家决定每周打扫。", "target_word": "有鉴于此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他连续熬夜，身体变差，有鉴于此，他不再熬夜工作了。", "target_word": "有鉴于此", "complexity_tier": "T3", "furigana": "tā liánxù áoyè, shēntǐ biàn chà, yǒu jiàn yú cǐ, tā bù zài áoyè gōngzuò le.", "sentence_source": "generated"}, {"text": "这次考试很难，有鉴于此，老师多给了一天复习时间。", "target_word": "有鉴于此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "因为前面这件事，所以想办法应对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12bffa6a-c330-4612-90ca-b7a2113d6df9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25724, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有鉴于此", "is_correct": true, "explanation": "有鉴于此：意思是考虑到路上堵车的情况，引出后面的做法，符合句意。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：“尽管”要与后文“但是”或“仍然”呼应，这里没有让步的分句。"}, {"text": "无论", "is_correct": false, "explanation": "搭配：“无论”要与后文“都”呼应，句中没有这样的呼应。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，但前文没有需要转折的内容。"}], "explanations": {"有鉴于此": "有鉴于此：意思是考虑到路上堵车的情况，引出后面的做法，符合句意。", "尽管": "搭配：“尽管”要与后文“但是”或“仍然”呼应，这里没有让步的分句。", "无论": "搭配：“无论”要与后文“都”呼应，句中没有这样的呼应。", "然而": "语义：“然而”表示转折，但前文没有需要转折的内容。"}, "sentence_index": 0, "correct_answer": "有鉴于此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暴雨下了一整夜，有鉴于此，街道积了水。", "explanation": "这里应该用〈以致〉。有鉴于此要引出做法或决定，不能引出“街道积了水”这样的结果。"}, {"text": "孩子看见了小狗，有鉴于此，笑了起来。", "explanation": "这里应该用〈于是〉。有鉴于此要引出做法或决定，不能引出“笑了起来”这样的反应。"}, {"text": "他今天没来，有鉴于此，大家都担心。", "explanation": "这里应该用〈难怪〉。有鉴于此要引出做法或决定，不能引出“大家都担心”这样的心理状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有鉴于此", "is_correct": true, "explanation": "有鉴于此：意思是考虑到街道很暗的情况，引出后面的做法，符合句意。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与后文“但是”呼应，句中没有让步的内容。"}, {"text": "不但", "is_correct": false, "explanation": "搭配：“不但”要与后文“而且”或“还”呼应，这里句式不成立。"}, {"text": "如果", "is_correct": false, "explanation": "语义：“如果”表示假设，但“街道很暗”是已经存在的事实。"}], "explanations": {"有鉴于此": "有鉴于此：意思是考虑到街道很暗的情况，引出后面的做法，符合句意。", "虽然": "搭配：“虽然”要与后文“但是”呼应，句中没有让步的内容。", "不但": "搭配：“不但”要与后文“而且”或“还”呼应，这里句式不成立。", "如果": "语义：“如果”表示假设，但“街道很暗”是已经存在的事实。"}, "sentence_index": 6, "correct_answer": "有鉴于此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没有带伞，有鉴于此，淋湿了。", "explanation": "这里应该用〈所以〉。有鉴于此要引出做法或决定，不能引出“淋湿了”这样的结果。"}, {"text": "这道题他只用了一分钟，有鉴于此，他很聪明。", "explanation": "这里应该用〈可见〉。有鉴于此要引出做法或决定，不能引出对人的评价“很聪明”。"}, {"text": "她收到了录取通知，有鉴于此，放心地笑了。", "explanation": "这里应该用〈才〉。有鉴于此要引出做法或决定，不能引出“放心地笑了”这样的反应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电话总是打不通，有鉴于此了，我们改用短信联系。", "corrected_sentence": "电话总是打不通，有鉴于此，我们改用短信联系。", "error_description": "错误：“有鉴于此”是连词，不能带“了”，应说“有鉴于此，”，不说“有鉴于此了，”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里常有人打架，有鉴于此的，派出所增加了巡逻。", "corrected_sentence": "夜里常有人打架，有鉴于此，派出所增加了巡逻。", "error_description": "错误：“有鉴于此”是连词，后面不能加“的”，应说“有鉴于此，”，不说“有鉴于此的，”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a90f66d-2343-469e-a462-6822f0402cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
