INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25730, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25730, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "树上掉下来的、已经枯黄或破碎的叶子。", "primary_collocate": null, "pronunciation": "cán yè", "ipa": "tsʰan˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "公园的路上铺满了残叶。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，残叶从树上掉下来了。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在地上捡残叶，做成了小画。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞过，几片残叶落到了水里。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清洁工每天早上都要扫残叶。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树的叶子黄了，地上有一层残叶。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踩着残叶，听到轻轻的响声。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下过雨以后，残叶都湿了。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把花盆里的残叶拿出来。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的小路上，残叶被风吹到了路边。", "target_word": "残叶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "殘葉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从树上掉下的枯黄或破碎的叶子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91551975-d9d1-42af-a4e4-1a8bfc2d0b91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25730, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残叶", "is_correct": true, "explanation": "残叶是可以铺满路面的枯黄叶子，与“公园的路上”的语境吻合。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的气体，不能被铺满在路面上。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋不会铺满公园的路，这一说法在语义上不成立。"}, {"text": "小猫", "is_correct": false, "explanation": "配价：“铺满”的对象须是可以铺展的物料，小猫是有生命的动物，不能被铺满。"}], "explanations": {"残叶": "残叶是可以铺满路面的枯黄叶子，与“公园的路上”的语境吻合。", "空气": "语义：空气是无形的气体，不能被铺满在路面上。", "鸡蛋": "语义：鸡蛋不会铺满公园的路，这一说法在语义上不成立。", "小猫": "配价：“铺满”的对象须是可以铺展的物料，小猫是有生命的动物，不能被铺满。"}, "sentence_index": 0, "correct_answer": "残叶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵小树又冒出了几片残叶。", "explanation": "这里应该用〈新叶〉。残叶指枯黄或破碎的叶子，不会从树上新冒出来；新长出的叶子要说新叶。"}, {"text": "夏天的树上挂满了翠绿的残叶。", "explanation": "这里应该用〈绿叶〉。残叶是枯黄或破碎的叶子，翠绿的夏叶不能说成残叶。"}, {"text": "残叶通过光合作用，为植物制造养分。", "explanation": "这里应该用〈叶片〉。残叶已枯黄破碎，不能进行光合作用，不能为植物制造养分；能进行光合作用的要说叶片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25730, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残叶", "is_correct": true, "explanation": "残叶是地上的枯叶，踩上去会发出轻轻的响声，符合语境。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐是声音，不是可以被踩的实体，与“踩着”不搭。"}, {"text": "妈妈", "is_correct": false, "explanation": "配价：“踩”的对象须是地面上的物体，“妈妈”是有生命的人，不能被踩。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯是照明器具，踩上去不会发出轻轻的响声，与语境不符。"}], "explanations": {"残叶": "残叶是地上的枯叶，踩上去会发出轻轻的响声，符合语境。", "音乐": "语义：音乐是声音，不是可以被踩的实体，与“踩着”不搭。", "妈妈": "配价：“踩”的对象须是地面上的物体，“妈妈”是有生命的人，不能被踩。", "灯": "语义：灯是照明器具，踩上去不会发出轻轻的响声，与语境不符。"}, "sentence_index": 6, "correct_answer": "残叶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "刚破土的小苗上，长着一圈圈的残叶。", "explanation": "这里应该用〈嫩芽〉。残叶是树上掉下来的枯黄或破碎的叶子，刚破土的新芽不能说残叶。"}, {"text": "妈妈说，新摘的残叶最适合拌凉菜，又嫩又脆。", "explanation": "这里应该用〈青菜〉。残叶是枯黄破碎的叶子，新摘下来、又嫩又脆的青菜不能说残叶。"}, {"text": "这束鲜花的花瓣还很新鲜，却有一枚花苞掉下来成了残叶。", "explanation": "这里应该用〈残花〉。残叶是树上掉下来的枯叶，花苞不是叶子，枯萎的花要说残花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里飘来一根残叶。", "corrected_sentence": "院子里飘来一片残叶。", "error_description": "错误形式“一根残叶”；正确形式“一片残叶”。“根”用于细长的东西，叶子要用“片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子角落里有一只残叶。", "corrected_sentence": "院子角落里有一片残叶。", "error_description": "错误形式“一只残叶”；正确形式“一片残叶”。“只”用于动物或成对器物中的一个，叶子要用“片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25732, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最低", "is_correct": true, "explanation": "最低与“最高”意思相反，指程度、价格等居于末位。"}, {"text": "深", "is_correct": false, "explanation": "深是从上到下或从外到里距离大，与“最高”没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "厚是物体两个表面之间的距离大，与“最高”没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "轻是重量小，与“最高”没有反义关系。"}], "correct_answer": "最低", "explanations": {"最低": "最低与“最高”意思相反，指程度、价格等居于末位。", "深": "深是从上到下或从外到里距离大，与“最高”没有反义关系。", "厚": "厚是物体两个表面之间的距离大，与“最高”没有反义关系。", "轻": "轻是重量小，与“最高”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25732, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最低", "is_correct": true, "explanation": "最低与“最高”意思相反，指程度、价格等居于末位。"}, {"text": "快", "is_correct": false, "explanation": "快是速度高，与“最高”没有反义关系。"}, {"text": "远", "is_correct": false, "explanation": "远是距离大，与“最高”没有反义关系。"}, {"text": "软", "is_correct": false, "explanation": "软是不硬，与“最高”没有反义关系。"}], "correct_answer": "最低", "explanations": {"最低": "最低与“最高”意思相反，指程度、价格等居于末位。", "快": "快是速度高，与“最高”没有反义关系。", "远": "远是距离大，与“最高”没有反义关系。", "软": "软是不硬，与“最高”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25732, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "最高的，就是比所有别的都高。", "primary_collocate": null, "pronunciation": "zuì gāo", "ipa": "tsweɪ˥˩ kɑʊ˥", "syllable_count": 2, "sentences": [{"text": "这是我们城市最高的楼。", "target_word": "最高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是班里个子最高的人。", "target_word": "最高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山是全国最高的山。", "target_word": "最高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的价格最高。", "target_word": "最高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的气温是这个月最高的。", "target_word": "最高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考试得了最高的分数。", "target_word": "最高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的工资是公司里最高的。", "target_word": "最高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里是城里最高的地方，能看到海。", "target_word": "最高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的最高奖金是十万元。", "target_word": "最高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上最高的山是珠穆朗玛峰。", "target_word": "最高", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "最高的", "label": "的字结构"}, {"form": "最高点", "label": "复合词"}, {"form": "最高峰", "label": "复合词"}], "register": "中性", "sense_fingerprint": "最高：形容词，高度、程度、数量在所有同类中居首", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be7eb40f-7d8a-4232-9c49-ff679e0a5a7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25732, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最高", "is_correct": true, "explanation": "“最高”表示高度居首，“这是我们城市最高的楼”搭配自然。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”说人或事物的年纪，不能用来形容楼。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来形容楼，句意不通。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体态，不能用来形容楼的外观。"}], "explanations": {"最高": "“最高”表示高度居首，“这是我们城市最高的楼”搭配自然。", "年轻": "搭配：“年轻”说人或事物的年纪，不能用来形容楼。", "聪明": "语义：“聪明”形容人的智力，不能用来形容楼，句意不通。", "胖": "体貌：“胖”形容人或动物的体态，不能用来形容楼的外观。"}, "sentence_index": 0, "correct_answer": "最高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市的面积最高。", "explanation": "这里应该用〈最大〉。“最高”说高度、水平、价格，超市的面积大小要用“最大”。"}, {"text": "他的胆子最高。", "explanation": "这里应该用〈最大〉。“最高”说高度或程度居首，胆子的大小要用“最大”。"}, {"text": "这条路的距离最高。", "explanation": "这里应该用〈最远〉。“最高”说高度、水平、价格，路程的远近要用“最远”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最高", "is_correct": true, "explanation": "“最高”表示工资在公司中居首，“我的工资是公司里最高的”搭配自然。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”说身高或事物的高度低，不说工资矮。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”形容外貌或事物美观，工资不能漂亮，句意不通。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：“寂寞”形容人的心情，工资不能寂寞，句意不通。"}], "explanations": {"最高": "“最高”表示工资在公司中居首，“我的工资是公司里最高的”搭配自然。", "矮": "搭配：“矮”说身高或事物的高度低，不说工资矮。", "漂亮": "语义：“漂亮”形容外貌或事物美观，工资不能漂亮，句意不通。", "寂寞": "语义：“寂寞”形容人的心情，工资不能寂寞，句意不通。"}, "sentence_index": 6, "correct_answer": "最高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给我们的帮助最高。", "explanation": "这里应该用〈最大〉。“最高”说高度或程度居首，帮助的多少要用“最大”。"}, {"text": "他的面子最高。", "explanation": "这里应该用〈最大〉。“最高”说高度或程度居首，面子的大小要用“最大”。"}, {"text": "他跑得最高。", "explanation": "“最高”说高度或程度，不能用来描述跑步的快慢，应说“跑得最快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在我们班里，他比我最高。", "corrected_sentence": "在我们班里，他最高。", "error_description": "错误形式“比我最高”，正确形式“最高”。“最高”本身表示在同类中居首，已含比较义，不能再与“比”字句同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我们村最高山。", "corrected_sentence": "这是我们村最高的山。", "error_description": "“最高山”不是通用说法。“最高”修饰“山”时要说“最高的山”。“最高峰”“最高点”是固定复合词，不适用此规则。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
