INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25734, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生物生出新的小宝宝。", "primary_collocate": null, "pronunciation": "fán zhí", "ipa": "fan˧˥ ʈʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "小猫长大了，也会繁殖。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子一年可以繁殖很多次。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小鱼在春天繁殖。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里的熊猫今年繁殖了。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "池塘里的青蛙繁殖得很快。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场里的羊每年都繁殖。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，鸟会在树上繁殖。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鱼在河里繁殖，不在海里。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小虫繁殖了很多，花园里到处都是。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊猫不容易繁殖，所以数量很少。", "target_word": "繁殖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "繁殖了", "label": "体标"}, {"form": "繁殖过", "label": "体标"}, {"form": "繁殖期", "label": "复合"}], "register": "中性", "sense_fingerprint": "动物生出小宝宝、有了下一代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9da955b2-9cb2-4719-95b9-57d75913c78c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25734, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "繁殖", "is_correct": true, "explanation": "繁殖（fán zhí）指生物生出小宝宝，是目标词本身。"}, {"text": "凡是", "is_correct": false, "explanation": "shì（第四声）与 zhí（第二声）声母与声调都不同，意思是“凡是”，指所有。"}, {"text": "分值", "is_correct": false, "explanation": "fēn（第一声）与 fán（第二声）韵母不同（en 与 an），声调也不同，意思是“分值”。"}, {"text": "烦事", "is_correct": false, "explanation": "shì（第四声）与 zhí（第二声）声母与声调都不同，意思是“烦心的事”。"}], "explanations": {"繁殖": "繁殖（fán zhí）指生物生出小宝宝，是目标词本身。", "凡是": "shì（第四声）与 zhí（第二声）声母与声调都不同，意思是“凡是”，指所有。", "分值": "fēn（第一声）与 fán（第二声）韵母不同（en 与 an），声调也不同，意思是“分值”。", "烦事": "shì（第四声）与 zhí（第二声）声母与声调都不同，意思是“烦心的事”。"}, "sentence_index": null, "correct_answer": "繁殖"}, "level_3": {"options": [{"text": "繁殖", "is_correct": true, "explanation": "“也会繁殖”指小猫长大后能生出小宝宝，与语境相合。"}, {"text": "拼写", "is_correct": false, "explanation": "语义：拼写指按字母写出单词，小猫不能拼写。"}, {"text": "调试", "is_correct": false, "explanation": "语义：调试指检查修正程序或设备，与小猫无关。"}, {"text": "盛开", "is_correct": false, "explanation": "搭配：“盛开”只用于花，不能用于小猫。"}], "explanations": {"繁殖": "“也会繁殖”指小猫长大后能生出小宝宝，与语境相合。", "拼写": "语义：拼写指按字母写出单词，小猫不能拼写。", "调试": "语义：调试指检查修正程序或设备，与小猫无关。", "盛开": "搭配：“盛开”只用于花，不能用于小猫。"}, "sentence_index": 0, "correct_answer": "繁殖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的顾客今年繁殖了很多。", "explanation": "这里应该用〈增加〉。繁殖指生物生出后代，顾客的人数要用增加。"}, {"text": "爱迪生繁殖了电灯。", "explanation": "这里应该用〈发明〉。繁殖指生物生出后代，电灯是人造的，要用发明。"}, {"text": "这家面包店每天繁殖很多面包。", "explanation": "这里应该用〈生产〉。面包是人做的，繁殖只指生物生出后代，要用生产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繁殖", "is_correct": true, "explanation": "“鸟会在树上繁殖”指鸟在树上生出小宝宝，与语境相合。"}, {"text": "投票", "is_correct": false, "explanation": "语义：投票指表决意见，鸟不能投票。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”的对象是房屋，不能用于鸟。"}, {"text": "漂流", "is_correct": false, "explanation": "语义：漂流指随水流移动，鸟不会在树上漂流。"}], "explanations": {"繁殖": "“鸟会在树上繁殖”指鸟在树上生出小宝宝，与语境相合。", "投票": "语义：投票指表决意见，鸟不能投票。", "装修": "搭配：“装修”的对象是房屋，不能用于鸟。", "漂流": "语义：漂流指随水流移动，鸟不会在树上漂流。"}, "sentence_index": 6, "correct_answer": "繁殖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵小树三年就繁殖到了两米高。", "explanation": "这里应该用〈生长〉。繁殖指生物生出后代，树木长高要用生长。"}, {"text": "孩子的身体繁殖得很好。", "explanation": "这里应该用〈发育〉。繁殖指生物生出后代，身体的成长要用发育。"}, {"text": "他每天繁殖一个小时。", "explanation": "这里应该用〈写作〉之类的动词。繁殖只指生物生出后代，不能用来说人做事的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种虫子繁殖的特别快。", "corrected_sentence": "这种虫子繁殖得特别快。", "error_description": "补语标记应为“得”，写作“繁殖得特别快”；“的”不用于动词与补语之间，这里误用了“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "熊猫去年繁殖着一次。", "corrected_sentence": "熊猫去年繁殖过一次。", "error_description": "表示经历的助词应为“过”，写作“繁殖过”；“着”表示持续，与“去年……一次”的经历语境不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
