INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25736, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纤维素是植物里的一种东西，让植物站得直。", "primary_collocate": null, "pronunciation": "xiān wéi sù", "ipa": "ɕi̯ɛn wei̯ su", "syllable_count": 3, "sentences": [{"text": "纤维素让植物站得直。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草茎里有纤维素，所以不容易倒。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有纤维素，植物就站不直。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，纤维素像植物的骨头。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竹子里的纤维素很多，所以很直。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物的细胞壁里有纤维素。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纤维素帮助小树长得直。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图画的是植物里的纤维素。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉米秆站得直，是因为有纤维素。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物靠纤维素撑起身体。", "target_word": "纤维素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "纖維素", "label": "繁体"}], "register": "科技", "sense_fingerprint": "植物里让植物站得直的东西，像植物的骨头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c8b8646-9bcc-4bda-9fbd-029237946042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25736, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纤维素", "is_correct": true, "explanation": "正确：纤维素是植物里让植物站得直的成分，符合“让植物站得直”的语境。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气是气体，不起支撑作用，不能让植物站得直。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光促进光合作用，但不能使植物站得直，与“站得直”的支撑意思不符。"}, {"text": "花粉", "is_correct": false, "explanation": "搭配：“让植物站得直”需要支撑性成分作主语，花粉属于繁殖结构，不能搭配这个结构。"}], "explanations": {"纤维素": "正确：纤维素是植物里让植物站得直的成分，符合“让植物站得直”的语境。", "氧气": "语义：氧气是气体，不起支撑作用，不能让植物站得直。", "阳光": "语义：阳光促进光合作用，但不能使植物站得直，与“站得直”的支撑意思不符。", "花粉": "搭配：“让植物站得直”需要支撑性成分作主语，花粉属于繁殖结构，不能搭配这个结构。"}, "sentence_index": 0, "correct_answer": "纤维素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根绳子的纤维素很粗。", "explanation": "这里应该用〈纤维〉。绳子的粗细指丝缕本身；纤维素是化合物名称，不能用来指一根根的丝。"}, {"text": "这座房子的纤维素很结实。", "explanation": "这里应该用〈骨架〉。房子结实靠骨架；纤维素是植物里的成分，不是房子的结构部件。"}, {"text": "这头牛的纤维素很硬。", "explanation": "这里应该用〈骨头〉。牛身上的硬物是骨骼，纤维素是植物细胞壁的主要成分，不能用来指牛的骨骼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25736, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纤维素", "is_correct": true, "explanation": "正确：纤维素是植物体内的支撑成分，能帮助小树长得直。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是植物的支撑成分，不能帮助小树长得直。"}, {"text": "塑料袋", "is_correct": false, "explanation": "语义：塑料袋与植物的生长结构无关，不能帮助小树站直。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：“帮助小树长得直”的主语应是植物体内的支撑结构，牛奶不搭配这个结构。"}], "explanations": {"纤维素": "正确：纤维素是植物体内的支撑成分，能帮助小树长得直。", "玩具": "语义：玩具不是植物的支撑成分，不能帮助小树长得直。", "塑料袋": "语义：塑料袋与植物的生长结构无关，不能帮助小树站直。", "牛奶": "搭配：“帮助小树长得直”的主语应是植物体内的支撑结构，牛奶不搭配这个结构。"}, "sentence_index": 6, "correct_answer": "纤维素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师拿出一只纤维素给我们看。", "explanation": "这里应该用〈种〉。“只”用于动物或成对的东西，纤维素是物质，不能用“只”计量。"}, {"text": "这株小草里有一条纤维素。", "explanation": "这里应该直接说“纤维素”或用〈种〉。“条”用于细长的东西，纤维素是物质，不能按条计量。"}, {"text": "竹子里有一支纤维素。", "explanation": "这里应该用〈种〉。“支”用于细长的棍状物，如笔、蜡烛；纤维素是物质，不能用“支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "竹子能长得很直，是因为有一颗纤维素。", "corrected_sentence": "竹子能长得很直，是因为有纤维素。", "error_description": "“纤维素”是物质名称，不能用“颗”计量（“颗”多用于粒状物）。应去掉“一颗”，说“有纤维素”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这棵树的纤维素们很多，所以站得很直。", "corrected_sentence": "这棵树的纤维素很多，所以站得很直。", "error_description": "“纤维素”是物质名词，不能加复数后缀“们”。应说“纤维素很多”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
