INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25738, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "庄稼收完后剩下的茎和叶子。", "primary_collocate": null, "pronunciation": "jiē gǎn", "ipa": "tɕjɛ˥ kan˨˩", "syllable_count": 2, "sentences": [{"text": "玉米收完以后，田里只剩下秸秆。", "target_word": "秸秆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶用秸秆编了一个小篮子。", "target_word": "秸秆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我们在秸秆堆里捉迷藏。", "target_word": "秸秆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天，农民把秸秆盖在菜地上保暖。", "target_word": "秸秆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一捆秸秆很轻，但是体积很大。", "target_word": "秸秆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛在棚里慢慢嚼着秸秆。", "target_word": "秸秆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高粱的秸秆又细又长，可以做扫把。", "target_word": "秸秆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麦子割完后，剩下的秸秆要及时清理。", "target_word": "秸秆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸开车运来了一车秸秆。", "target_word": "秸秆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些秸秆晒干以后很容易着火。", "target_word": "秸秆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捆", "label": "量词"}, {"form": "玉米秸秆", "label": "复合"}, {"form": "秸稈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "庄稼收完后田里剩下的茎和叶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91551975-d9d1-42af-a4e4-1a8bfc2d0b91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秸秆", "is_correct": true, "explanation": "玉米收完后，田里剩下的就是秸秆，符合句意。"}, {"text": "稻谷", "is_correct": false, "explanation": "语义：收完的粮食会被收走，不会剩在田里。"}, {"text": "星期三", "is_correct": false, "explanation": "语义：星期三是时间，不是能留在田里的实物，不能“剩下”。"}, {"text": "道理", "is_correct": false, "explanation": "语义：道理是抽象的想法，不是能留在田里的实物，与“只剩下”不搭。"}], "explanations": {"秸秆": "玉米收完后，田里剩下的就是秸秆，符合句意。", "稻谷": "语义：收完的粮食会被收走，不会剩在田里。", "星期三": "语义：星期三是时间，不是能留在田里的实物，不能“剩下”。", "道理": "语义：道理是抽象的想法，不是能留在田里的实物，与“只剩下”不搭。"}, "sentence_index": 0, "correct_answer": "秸秆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们用秸秆做馒头。", "explanation": "这里应该用〈面粉〉。做馒头要用面粉，秸秆是茎叶，不能代替面粉。"}, {"text": "农民每年春天在地里播秸秆。", "explanation": "这里应该用〈种子〉。秸秆是收割后剩下的茎秆，不能播种，播种要用种子。"}, {"text": "妈妈用秸秆煮汤，味道很鲜。", "explanation": "这里应该用〈排骨〉。秸秆是茎，不能食用，煮汤要用排骨这类食材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秸秆", "is_correct": true, "explanation": "高粱的秸秆细长，可以用来做扫把，符合句中的描述。"}, {"text": "果实", "is_correct": false, "explanation": "语义：果实是可食用的部分，不能用来做扫把。"}, {"text": "籽粒", "is_correct": false, "explanation": "体貌：籽粒圆小，不是“又细又长”的形状。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会是细长的植物茎，也不能用来做扫把。"}], "explanations": {"秸秆": "高粱的秸秆细长，可以用来做扫把，符合句中的描述。", "果实": "语义：果实是可食用的部分，不能用来做扫把。", "籽粒": "体貌：籽粒圆小，不是“又细又长”的形状。", "石头": "语义：石头不会是细长的植物茎，也不能用来做扫把。"}, "sentence_index": 6, "correct_answer": "秸秆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秸秆脱粒以后，要先晒干再装袋。", "explanation": "这里应该用〈稻谷〉。脱粒的是稻谷，秸秆是收割后剩下的茎，不能脱粒。"}, {"text": "我把秸秆放进火锅里涮着吃，味道很鲜。", "explanation": "这里应该用〈青菜〉。秸秆是茎，不能涮着吃；火锅里涮的要说青菜。"}, {"text": "写字要用秸秆。", "explanation": "这里应该用〈墨水〉。写字要用墨水这类书写材料，秸秆不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民把这只秸秆搬走了。", "corrected_sentence": "农民把这捆秸秆搬走了。", "error_description": "量词错误：“只”用于动物或成对器物中的一个，不能用于秸秆；可以说“这根秸秆”或“这捆秸秆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把秸秆捆起去了。", "corrected_sentence": "他把秸秆捆起来了。", "error_description": "趋向补语错误：“捆”之后表示动作聚拢或完成的趋向补语应为“起来”，不说“起去”，应说“捆起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
