INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25740, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "木头里的一种东西，让树木很硬。", "primary_collocate": null, "pronunciation": "mù zhì sù", "ipa": "mu ʈʂɨ su", "syllable_count": 3, "sentences": [{"text": "木质素让树木很硬。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头为什么硬？因为里面有木质素。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木质素在树干里。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小树的木质素少，所以比较软。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木质素多，木头就硬。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了木质素的图片。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "硬木头里的木质素特别多。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木质素帮树站得稳。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竹子里也有木质素。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木质素让桌子的木板很结实。", "target_word": "木质素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "木質素", "label": "繁体"}], "register": "科技", "sense_fingerprint": "木头里让树木变硬、变结实的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c8b8646-9bcc-4bda-9fbd-029237946042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25740, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "木质素", "is_correct": true, "explanation": "正确：木质素是木头里让树木变硬的成分，符合“让树木很硬”的语境。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气是气体，不能让树木变硬。"}, {"text": "树叶", "is_correct": false, "explanation": "体貌：树叶薄而软，不能让树木“很硬”，与硬度的描述不符。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光促进光合作用，但不能使树木变硬。"}], "explanations": {"木质素": "正确：木质素是木头里让树木变硬的成分，符合“让树木很硬”的语境。", "氧气": "语义：氧气是气体，不能让树木变硬。", "树叶": "体貌：树叶薄而软，不能让树木“很硬”，与硬度的描述不符。", "阳光": "语义：阳光促进光合作用，但不能使树木变硬。"}, "sentence_index": 0, "correct_answer": "木质素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "木质素很粗，支撑着整个树冠。", "explanation": "这里应该用〈树干〉。树干有粗细，能支撑树冠；木质素是树木里的成分，不是有粗细的树干。"}, {"text": "木质素很厚，能保护树干。", "explanation": "这里应该用〈树皮〉。树皮有厚薄，能保护树干；木质素在树木内部，不是覆盖在外面的皮。"}, {"text": "木质素很甜，我们可以直接吃。", "explanation": "这里应该用〈糖〉。木质素是树木里的成分，没有甜味，也不能吃；甜的东西要用〈糖〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25740, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木质素", "is_correct": true, "explanation": "正确：硬木头中木质素含量高，符合“硬木头里的……特别多”的语境。"}, {"text": "蛋白质", "is_correct": false, "explanation": "语义：木头中几乎不含蛋白质，“特别多”与木头的构成不符。"}, {"text": "维生素", "is_correct": false, "explanation": "语义：木头不是维生素的主要来源，“硬木头里的维生素特别多”不符合实际。"}, {"text": "木屑", "is_correct": false, "explanation": "搭配：“硬木头里的”修饰的应是木材本身的构成，木屑是加工后的碎屑，不能说“硬木头里的木屑特别多”。"}], "explanations": {"木质素": "正确：硬木头中木质素含量高，符合“硬木头里的……特别多”的语境。", "蛋白质": "语义：木头中几乎不含蛋白质，“特别多”与木头的构成不符。", "维生素": "语义：木头不是维生素的主要来源，“硬木头里的维生素特别多”不符合实际。", "木屑": "搭配：“硬木头里的”修饰的应是木材本身的构成，木屑是加工后的碎屑，不能说“硬木头里的木屑特别多”。"}, "sentence_index": 6, "correct_answer": "木质素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌子上放着一张木质素。", "explanation": "这里应该用〈种〉或不加量词。“张”用于纸、桌子等平面的东西；木质素是物质，不能用“张”计量。"}, {"text": "老师拿出一头木质素。", "explanation": "这里应该用〈种〉。“头”用于牛、猪等大型动物，木质素是物质，不能用“头”计量。"}, {"text": "他抽出一支木质素。", "explanation": "这里应该用〈种〉。“支”用于细长的棍状物，如笔、蜡烛；木质素不是棍状物，不能用“支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这棵大树的一条木质素很多，所以很硬。", "corrected_sentence": "这棵大树的木质素很多，所以很硬。", "error_description": "“木质素”是物质名称，不能用“条”计量（“条”用于细长的东西）。应去掉“一条”，说“这棵大树的木质素很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块木板里的一根木质素特别多。", "corrected_sentence": "这块木板里的木质素特别多。", "error_description": "“木质素”是物质名称，不能用“根”计量（“根”用于细长的东西）。应说“这块木板里的木质素特别多”，去掉“一根”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
