INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25742, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "需要的东西", "primary_collocate": null, "pronunciation": "suǒ xū", "ipa": "swo˨˩ ɕy˥˥", "syllable_count": 2, "sentences": [{"text": "商店里有你所需的一切。", "target_word": "所需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店能满足客人的所需。", "target_word": "所需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉我你的所需，我来准备。", "target_word": "所需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的人用土地换来生活所需。", "target_word": "所需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院把病人的所需列成了清单。", "target_word": "所需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的所需并不多，只要有人陪。", "target_word": "所需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按照孩子的所需买了文具。", "target_word": "所需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱只够买最基本的所需。", "target_word": "所需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司会尽量满足员工工作中的所需。", "target_word": "所需", "complexity_tier": "T3", "furigana": "gōng sī huì jǐn liàng mǎn zú yuán gōng gōng zuò zhōng de suǒ xū", "sentence_source": "generated"}, {"text": "旅行前，先写下路上的所需。", "target_word": "所需", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "单独作名词，指人或事物需要的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ae535a-9ea1-4936-80af-cc9fd7df8a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所需", "is_correct": true, "explanation": "正确。「商店里有你所需的一切」中，所需指你需要的东西。"}, {"text": "所欠", "is_correct": false, "explanation": "语义：「欠」指亏欠，商店里不能有你所亏欠的东西。"}, {"text": "所跑", "is_correct": false, "explanation": "语义：「跑」指奔跑，商店里不能有你所跑的一切，句意荒谬。"}, {"text": "所哭", "is_correct": false, "explanation": "语义：「哭」指流泪，商店里不能有你所哭的一切，句意荒谬。"}], "explanations": {"所需": "正确。「商店里有你所需的一切」中，所需指你需要的东西。", "所欠": "语义：「欠」指亏欠，商店里不能有你所亏欠的东西。", "所跑": "语义：「跑」指奔跑，商店里不能有你所跑的一切，句意荒谬。", "所哭": "语义：「哭」指流泪，商店里不能有你所哭的一切，句意荒谬。"}, "sentence_index": 0, "correct_answer": "所需"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一生所需的困难没有止境。", "explanation": "这里应该用〈所遭遇的〉。所需指需要的东西，不能用来修饰遭遇的困难，遭遇的困难应说所遭遇的。"}, {"text": "那一天所需的景象让人难忘。", "explanation": "这里应该用〈所见的〉。所需指需要的东西，不能用来修饰看到的景象，看到的景象应说所见的。"}, {"text": "他的所需很聪明。", "explanation": "这里应该用〈头脑〉。所需指需要的东西，不能用来形容聪明，应说「他的头脑很聪明」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所需", "is_correct": true, "explanation": "正确。「他按照孩子的所需买了文具」中，所需指孩子需要的东西。"}, {"text": "所笑", "is_correct": false, "explanation": "语义：「所笑」指所笑的人或事，不能作为买文具的依据。"}, {"text": "所睡", "is_correct": false, "explanation": "搭配：「睡」是不及物动词，不能构成「所」字结构，「孩子的所睡」无法作为买文具的依据。"}, {"text": "所走", "is_correct": false, "explanation": "搭配：「走」是不及物动词，不能构成「所」字结构，「孩子的所走」与买文具的依据无关。"}], "explanations": {"所需": "正确。「他按照孩子的所需买了文具」中，所需指孩子需要的东西。", "所笑": "语义：「所笑」指所笑的人或事，不能作为买文具的依据。", "所睡": "搭配：「睡」是不及物动词，不能构成「所」字结构，「孩子的所睡」无法作为买文具的依据。", "所走": "搭配：「走」是不及物动词，不能构成「所」字结构，「孩子的所走」与买文具的依据无关。"}, "sentence_index": 6, "correct_answer": "所需"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的所需很热情。", "explanation": "这里应该用〈性格〉。所需指需要的东西，不能用来形容热情，应说「她的性格很热情」。"}, {"text": "奶奶的所需很健康。", "explanation": "这里应该用〈身体〉。所需指需要的东西，不能用来形容健康，应说「奶奶的身体很健康」。"}, {"text": "那场大火所需的损失很大。", "explanation": "这里应该用〈所造成的〉。所需指需要的东西，不能用来修饰大火造成的损失，造成的损失应说所造成的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把孩子所需了的用品都准备好了。", "corrected_sentence": "他把孩子所需的用品都准备好了。", "error_description": "「所需」是定语，后面不能带「了」。正确形式是「所需的用品」，「所需了的用品」错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他列了一份旅行所需的的清单。", "corrected_sentence": "他列了一份旅行所需的清单。", "error_description": "错误：“所需的的清单”；正确：“旅行所需的清单”。多写了一个“的”，“所需”作定语后只接一个“的”再接名词即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
