INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25744, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "身体把吃进去的东西变成力气和热量的过程。", "primary_collocate": null, "pronunciation": "néng liàng dài xiè", "ipa": "nɤŋ˧˥ liɑŋ˥˩ taɪ̯˥˩ ɕiɛ˥˩", "syllable_count": 4, "sentences": [{"text": "运动以后，我的能量代谢会变快。", "target_word": "能量代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人睡觉的时候，能量代谢比较慢。", "target_word": "能量代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，年纪大了，能量代谢会变慢。", "target_word": "能量代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能量代谢让身体把食物变成力气。", "target_word": "能量代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲状腺出问题，会影响能量代谢。", "target_word": "能量代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天天冷，身体的能量代谢会加快。", "target_word": "能量代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的能量代谢很旺盛，吃得多也不胖。", "target_word": "能量代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院用仪器检查病人的能量代谢。", "target_word": "能量代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多喝水、多运动，有助于能量代谢。", "target_word": "能量代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长身体，能量代谢比大人快。", "target_word": "能量代谢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "能量代謝", "label": "繁体"}], "register": "书面", "sense_fingerprint": "身体把食物转化为力气和热量的生理过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '385e789d-21ea-49b5-b03e-4cf712cdbae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不会“变快”，“变快”多用于速度、代谢等过程。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不会随运动而“变快”，句子讲的是身体的变化。"}, {"text": "能量代谢", "is_correct": true, "explanation": "能量代谢：身体把食物变成力气和热量的过程，运动后会变快，与语境相符。"}, {"text": "信用", "is_correct": false, "explanation": "搭配：“信用”不能与“变快”搭配，句中说的是身体的生理变化。"}], "explanations": {"颜色": "搭配：“颜色”不会“变快”，“变快”多用于速度、代谢等过程。", "名字": "语义：“名字”不会随运动而“变快”，句子讲的是身体的变化。", "能量代谢": "能量代谢：身体把食物变成力气和热量的过程，运动后会变快，与语境相符。", "信用": "搭配：“信用”不能与“变快”搭配，句中说的是身体的生理变化。"}, "sentence_index": 0, "correct_answer": "能量代谢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钱存进了银行，攒下的能量代谢很多。", "explanation": "这里应该用〈存款〉。钱可以存入银行、攒起来，能量代谢是身体把食物变成力气和热量的过程，不能被存入或攒起。"}, {"text": "医生给病人打了一针能量代谢。", "explanation": "这里应该用〈营养液〉。“打针”注射的是药物或营养液，能量代谢是身体把食物变成力气和热量的过程，不能被注射。"}, {"text": "这个小伙子很有能量代谢，能扛起一百斤。", "explanation": "这里应该用〈力气〉。“很有”接的是人可以拥有的力量，能量代谢是身体内的过程，不能用“很有”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地址", "is_correct": false, "explanation": "搭配：“地址”不能用“旺盛”来形容，二者不搭配。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“钥匙”与“旺盛”不搭配，句中说的是身体的代谢状态。"}, {"text": "能量代谢", "is_correct": true, "explanation": "能量代谢：身体把食物变成力气和热量的过程，“旺盛”形容它很活跃，与“吃得多也不胖”相符。"}, {"text": "戒指", "is_correct": false, "explanation": "语义：戒指与“吃得多也不胖”的身体语境不符，句子说不通。"}], "explanations": {"地址": "搭配：“地址”不能用“旺盛”来形容，二者不搭配。", "钥匙": "搭配：“钥匙”与“旺盛”不搭配，句中说的是身体的代谢状态。", "能量代谢": "能量代谢：身体把食物变成力气和热量的过程，“旺盛”形容它很活跃，与“吃得多也不胖”相符。", "戒指": "语义：戒指与“吃得多也不胖”的身体语境不符，句子说不通。"}, "sentence_index": 6, "correct_answer": "能量代谢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "千卡是能量代谢的单位。", "explanation": "这里应该用〈热量〉。千卡计量的是热量，能量代谢是身体把食物变成力气和热量的过程，不能作为计量单位。"}, {"text": "煤是重要的能量代谢。", "explanation": "这里应该用〈能量来源〉。能量代谢是身体内的过程，不是能量的来源，煤才是能量来源。"}, {"text": "运动会消耗大量能量代谢。", "explanation": "这里应该用〈能量〉。运动消耗的是能量，能量代谢是过程，不是可以被消耗的物质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "喝了咖啡以后，他的能量代谢的很快。", "corrected_sentence": "喝了咖啡以后，他的能量代谢很快。", "error_description": "错误：“能量代谢”后面多加了“的”。正确：“很快”作谓语，直接接在“能量代谢”之后，不能再加“的”。正确句：“喝了咖啡以后，他的能量代谢很快。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药能加快病人能量代谢。", "corrected_sentence": "这种药能加快病人的能量代谢。", "error_description": "错误：名词“病人”修饰“能量代谢”时漏掉了“的”。正确：应说“病人的能量代谢”，名词性定语与中心语之间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
