INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25748, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很小的洞或缝。", "primary_collocate": null, "pronunciation": "kǒng xì", "ipa": "kʰʊŋ ɕi", "syllable_count": 2, "sentences": [{"text": "门板上有很小的孔隙。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光从墙的孔隙里照进来。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚂蚁从石头的孔隙里爬出来。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木头的孔隙太小，水进不去。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手指堵住了水管的孔隙。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包切开后，能看到许多孔隙。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子之间有很多孔隙。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风从窗户的孔隙吹进来。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块石板的孔隙很多，水很容易渗进去。", "target_word": "孔隙", "complexity_tier": "T3", "furigana": "zhè kuài shí bǎn de kǒng xì hěn duō, shuǐ hěn róng yì shèn jìn qù.", "sentence_source": "generated"}, {"text": "小虫躲在树皮的孔隙里。", "target_word": "孔隙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "东西上很小的洞或缝，光、风、水可以从中通过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c8b8646-9bcc-4bda-9fbd-029237946042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25748, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孔隙", "is_correct": true, "explanation": "正确。「很小的孔隙」指门板上细小的孔洞或缝隙。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」指气味或滋味，门板上的小洞不是味道。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」指色彩，不指能透光透风的细小孔洞。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：「门板上有很小的」后面应接描述孔洞或缝隙的词，「玩具」不搭配。"}], "explanations": {"孔隙": "正确。「很小的孔隙」指门板上细小的孔洞或缝隙。", "味道": "语义：「味道」指气味或滋味，门板上的小洞不是味道。", "颜色": "语义：「颜色」指色彩，不指能透光透风的细小孔洞。", "玩具": "搭配：「门板上有很小的」后面应接描述孔洞或缝隙的词，「玩具」不搭配。"}, "sentence_index": 0, "correct_answer": "孔隙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门板上有一只孔隙。", "explanation": "这里应该用〈个〉或〈处〉。〈只〉用于动物或成对物件中的一个，孔隙不用这个量词。"}, {"text": "他用孔隙写了一封信。", "explanation": "这里应该用〈纸〉。孔隙是物体上细小的孔洞或缝隙，不能用来写字；写字要用〈纸〉。"}, {"text": "这杯牛奶的孔隙很多。", "explanation": "这里应该用〈气泡〉。孔隙指固体上的细小孔洞，牛奶是液体，里面的小泡要用〈气泡〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孔隙", "is_correct": true, "explanation": "正确。「沙子之间有很多孔隙」指沙粒之间细小的空隙。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：「朋友」指人，沙子之间不会有朋友。"}, {"text": "故事", "is_correct": false, "explanation": "语义：「故事」是叙述性的内容，不是可以存在于沙子之间的东西。"}, {"text": "皱纹", "is_correct": false, "explanation": "体貌：「皱纹」指皮肤或物体表面的褶痕外形，沙粒之间的空隙不用这个词。"}], "explanations": {"孔隙": "正确。「沙子之间有很多孔隙」指沙粒之间细小的空隙。", "朋友": "语义：「朋友」指人，沙子之间不会有朋友。", "故事": "语义：「故事」是叙述性的内容，不是可以存在于沙子之间的东西。", "皱纹": "体貌：「皱纹」指皮肤或物体表面的褶痕外形，沙粒之间的空隙不用这个词。"}, "sentence_index": 6, "correct_answer": "孔隙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋子里有很多孔隙，我们可以住在里面。", "explanation": "这里应该用〈房间〉。孔隙是细小的孔洞，不能供人居住。"}, {"text": "他把孔隙煮进了汤里。", "explanation": "这里应该用〈调料〉。孔隙是物体上的细小孔洞或缝隙，不是食材，不能煮进汤里。"}, {"text": "他从孔隙探出头来看风景。", "explanation": "这里应该用〈窗口〉。孔隙太小，人的头探不出去；能让人看出去的开口要用〈窗口〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这扇门板上有一条很小的孔隙。", "corrected_sentence": "这扇门板上有一处很小的孔隙。", "error_description": "量词用错。“孔隙”可用量词“处”或“个”，“条”用于细长的东西，不适用于孔隙。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蚂蚁钻进了墙的孔隙上。", "corrected_sentence": "蚂蚁钻进了墙的孔隙里。", "error_description": "方位词用错。表示进入内部应该说“孔隙里”，“上”表示表面，不能用于孔隙内部。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
