INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25750, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水果里面硬硬的小东西。", "primary_collocate": null, "pronunciation": "guǒ hé", "ipa": "kuɔ˨˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "橄榄的果核两头尖，里面很硬。", "target_word": "果核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不小心咬到了果核，牙很疼。", "target_word": "果核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "荔枝的果核是黑色的，又圆又亮。", "target_word": "果核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟把枣的果核吐在小盘子里。", "target_word": "果核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃李子时，他把果核放在了盘子里。", "target_word": "果核", "complexity_tier": "T3", "furigana": "guǒ hé", "sentence_source": "generated"}, {"text": "这个果核太硬了，小鸟也啄不开。", "target_word": "果核", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把果核洗干净晒干，可以做小玩具。", "target_word": "果核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做山楂果酱前，要先把果核去掉。", "target_word": "果核", "complexity_tier": "T3", "furigana": "guǒ hé", "sentence_source": "generated"}, {"text": "她在院子里种下了一个桃子的果核。", "target_word": "果核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龙眼的果核像黑色的小球，很光滑。", "target_word": "果核", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "颗", "label": "量词"}], "register": "中性", "sense_fingerprint": "水果里面又小又硬的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91551975-d9d1-42af-a4e4-1a8bfc2d0b91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25750, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "果核", "is_correct": true, "explanation": "果核是橄榄里面的硬核，两头尖、里面很硬，与语境一致。"}, {"text": "果肉", "is_correct": false, "explanation": "语义：果肉柔软多汁，与“里面很硬”相反，不能说“两头尖、里面很硬”。"}, {"text": "叶子", "is_correct": false, "explanation": "体貌：叶子是薄片，没有“里面”可言，不能用“两头尖、里面很硬”来描述。"}, {"text": "果汁", "is_correct": false, "explanation": "体貌：果汁是液体，没有固定的形状，不能说“两头尖”。"}], "explanations": {"果核": "果核是橄榄里面的硬核，两头尖、里面很硬，与语境一致。", "果肉": "语义：果肉柔软多汁，与“里面很硬”相反，不能说“两头尖、里面很硬”。", "叶子": "体貌：叶子是薄片，没有“里面”可言，不能用“两头尖、里面很硬”来描述。", "果汁": "体貌：果汁是液体，没有固定的形状，不能说“两头尖”。"}, "sentence_index": 0, "correct_answer": "果核"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个桃子的果核红红的，又甜又多汁。", "explanation": "这里应该用〈果肉〉。果核是坚硬、不能吃的部分，不能说又甜又多汁；甜美多汁的部分要说果肉。"}, {"text": "我喝了一杯橙子果核。", "explanation": "这里应该用〈果汁〉。果核是坚硬的固体，不能喝；橙子榨出的饮料要说果汁。"}, {"text": "橘子的果核很薄，很容易剥下来。", "explanation": "这里应该用〈果皮〉。果核是包在果肉中间的硬核，不会很薄、很容易剥下来；能剥下来的薄皮要说果皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "果核", "is_correct": true, "explanation": "果核是硬的，洗干净晒干后可以做小玩具，符合语境。"}, {"text": "糖", "is_correct": false, "explanation": "语义：糖遇水会溶化，不能洗干净后再晒干做玩具。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块遇热会融化，不能晒干，也不能做成小玩具。"}, {"text": "洗衣粉", "is_correct": false, "explanation": "配价：“洗”的对象要能被洗涤，洗衣粉是洗涤用品，不能被“洗干净”。"}], "explanations": {"果核": "果核是硬的，洗干净晒干后可以做小玩具，符合语境。", "糖": "语义：糖遇水会溶化，不能洗干净后再晒干做玩具。", "冰块": "语义：冰块遇热会融化，不能晒干，也不能做成小玩具。", "洗衣粉": "配价：“洗”的对象要能被洗涤，洗衣粉是洗涤用品，不能被“洗干净”。"}, "sentence_index": 6, "correct_answer": "果核"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把篮子里的果核洗干净，一口一口全吃光了，甜甜的。", "explanation": "这里应该用〈果实〉。果核坚硬，不能一口一口吃光；可以吃的甜美果实要说果实。"}, {"text": "这把葵花籽炒得香脆，每一颗都是咸香的果核。", "explanation": "这里应该用〈瓜子〉。果核坚硬不能当零食；炒熟的葵花籽香脆可口，要说瓜子。"}, {"text": "这颗栗子的果核又香又软，剥开就能吃。", "explanation": "这里应该用〈果仁〉。果核是坚硬的外壳，剥开就能吃的是包在里面的果仁，要说果仁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在草丛里发现一根果核。", "corrected_sentence": "我在草丛里发现一颗果核。", "error_description": "错误形式“一根果核”；正确形式“一颗果核”。“根”用于细长的东西，果核要用“颗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上有一只果核。", "corrected_sentence": "桌上有一颗果核。", "error_description": "错误形式“一只果核”；正确形式“一颗果核”。“只”用于动物或成对器物中的一个，果核要用“颗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965858d1-cb57-48b9-ae76-3740a03aa4cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25752, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25752, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25752, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指两个事物或两个人。", "primary_collocate": null, "pronunciation": "liǎng zhě", "ipa": "liɑŋ˨˩ ʈʂɤ˨˩", "syllable_count": 2, "sentences": [{"text": "我有一本中文书和一本英文书，两者都很新。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王和小李是同学，两者都爱打篮球。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁和公共汽车，两者我都常坐。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店有蛋糕和面包，两者都不贵。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥和弟弟长得很像，两者都有大眼睛。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京和上海，两者我都去过。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机和电脑都能上网，两者各有用处。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天和秋天很舒服，两者都不冷不热。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要选咖啡还是茶？两者我都可以。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉字和拼音，两者都要学。", "target_word": "两者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "代指刚提到的两个事物或两个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c8b8646-9bcc-4bda-9fbd-029237946042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25752, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "两者", "is_correct": true, "explanation": "正确。两者 liǎng zhě 指两个事物或两个人。"}, {"text": "讲者", "is_correct": false, "explanation": "jiǎng（第三声）与 liǎng（第三声）声母不同，l 与 j 不同，意思是讲者（讲话的人）。"}, {"text": "两只", "is_correct": false, "explanation": "第二音节 zhī（第一声）与 zhě（第三声）声调不同，意思是“两只”，是数量词组。"}, {"text": "两枝", "is_correct": false, "explanation": "与两者的第二音节声调不同，意思是“两枝”（如两枝花），是数量词组。"}], "explanations": {"两者": "正确。两者 liǎng zhě 指两个事物或两个人。", "讲者": "jiǎng（第三声）与 liǎng（第三声）声母不同，l 与 j 不同，意思是讲者（讲话的人）。", "两只": "第二音节 zhī（第一声）与 zhě（第三声）声调不同，意思是“两只”，是数量词组。", "两枝": "与两者的第二音节声调不同，意思是“两枝”（如两枝花），是数量词组。"}, "sentence_index": null, "correct_answer": "两者"}, "level_3": {"options": [{"text": "两者", "is_correct": true, "explanation": "正确。「两者」回指前面的中文书和英文书，都很新。"}, {"text": "双方", "is_correct": false, "explanation": "语义：「双方」指双方人员或团体，不指书。"}, {"text": "他们", "is_correct": false, "explanation": "语义：「他们」指人，不指书。"}, {"text": "彼此", "is_correct": false, "explanation": "配价：「彼此」表示互相的关系，句中“都很新”无法构成互相关系。"}], "explanations": {"两者": "正确。「两者」回指前面的中文书和英文书，都很新。", "双方": "语义：「双方」指双方人员或团体，不指书。", "他们": "语义：「他们」指人，不指书。", "彼此": "配价：「彼此」表示互相的关系，句中“都很新”无法构成互相关系。"}, "sentence_index": 0, "correct_answer": "两者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店有蛋糕、面包和饼干，两者都不贵。", "explanation": "这里应该用〈三者〉。两者只指两个事物或两个人，这里列出了蛋糕、面包、饼干三样东西。"}, {"text": "我们全班两者都参加了比赛。", "explanation": "这里应该用〈大家〉。两者只指两个事物或两个人，不能用来指整个班级。"}, {"text": "这次考试很难，两者都没考好。", "explanation": "这里应该用〈大家〉。两者要回指前文已提到的两个对象，这句前文没有，泛指一群人应说〈大家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "两者", "is_correct": true, "explanation": "正确。「两者」指手机和电脑，各有用处。"}, {"text": "大家", "is_correct": false, "explanation": "语义：「大家」指人，手机和电脑不是人。"}, {"text": "你们", "is_correct": false, "explanation": "语义：「你们」指听话的人，不指物品。"}, {"text": "自己", "is_correct": false, "explanation": "配价：「自己」需要有明确的施事者，句中“各有用处”并不指向某人。"}], "explanations": {"两者": "正确。「两者」指手机和电脑，各有用处。", "大家": "语义：「大家」指人，手机和电脑不是人。", "你们": "语义：「你们」指听话的人，不指物品。", "自己": "配价：「自己」需要有明确的施事者，句中“各有用处”并不指向某人。"}, "sentence_index": 6, "correct_answer": "两者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汉字，两者都要学。", "explanation": "这里应该用〈它〉。两者指两个对象，这里只提到汉字一个。"}, {"text": "这次比赛，一方赢了，两者都赢了。", "explanation": "这里应该说〈另一方输了〉。两者指双方，但这里一方赢了，另一方输了，不能说两者都赢。"}, {"text": "我一个人去了超市，两者都买了东西。", "explanation": "这里应该用〈自己〉。两者只指两个事物或两个人，这句只有一个人去超市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "红茶和咖啡，两者能都提神。", "corrected_sentence": "红茶和咖啡，两者都能提神。", "error_description": "语序错误。“都”应紧跟“两者”，说“两者都能”；“都”放在“能”后面是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电视和电脑，两者们都能看视频。", "corrected_sentence": "电视和电脑，两者都能看视频。", "error_description": "错误：“两者”后不能加“们”。正确：“两者都能”，“两者”是指两个对象的代词，不接“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
