INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25754, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "闻起来像药水一样的味道。", "primary_collocate": null, "pronunciation": "ān wèi", "ipa": "an˥ wei˥˩", "syllable_count": 2, "sentences": [{"text": "医院的走廊里有一股淡淡的氨味。", "target_word": "氨味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶清洁剂有氨味，像药水一样。", "target_word": "氨味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "泳池的水闻起来有氨味，像药水。", "target_word": "氨味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的外套上有一股氨味，像刚从医院回来。", "target_word": "氨味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢这种洗发水，氨味太重了。", "target_word": "氨味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "染发的时候，满屋子都是氨味。", "target_word": "氨味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "擦过地以后，房间里留下了氨味。", "target_word": "氨味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家旅馆的被子有一股氨味，我睡不着。", "target_word": "氨味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你闻闻这杯水，是不是有氨味？", "target_word": "氨味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一进药店，就闻到了熟悉的氨味。", "target_word": "氨味", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "股", "label": "量词"}], "register": "中性", "sense_fingerprint": "像药水一样的刺鼻味道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86537d87-dd9d-4550-9cf6-595ab4b6d796') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "氨味", "is_correct": true, "explanation": "正确：氨味是像药水一样的气味，走廊里有淡淡的氨味，符合句意。"}, {"text": "水流", "is_correct": false, "explanation": "语义：走廊里不会有水流的气味，句意说不通。"}, {"text": "力量", "is_correct": false, "explanation": "语义：“一股淡淡的”形容可以闻到的气味，力量不能被闻到，句意说不通。"}, {"text": "勇气", "is_correct": false, "explanation": "语义：勇气不能被闻到，走廊里不会有“淡淡的勇气”这种气味，句意说不通。"}], "explanations": {"氨味": "正确：氨味是像药水一样的气味，走廊里有淡淡的氨味，符合句意。", "水流": "语义：走廊里不会有水流的气味，句意说不通。", "力量": "语义：“一股淡淡的”形容可以闻到的气味，力量不能被闻到，句意说不通。", "勇气": "语义：勇气不能被闻到，走廊里不会有“淡淡的勇气”这种气味，句意说不通。"}, "sentence_index": 0, "correct_answer": "氨味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的氨味很悦耳。", "explanation": "这里应该用〈旋律〉。氨味是气味，不能用来形容声音悦耳，歌曲好听要说旋律。"}, {"text": "这束百合散发着好闻的氨味。", "explanation": "这里应该用〈香味〉。氨味像药水一样刺鼻，不能用来形容好闻的百合香。"}, {"text": "他用氨味擦了擦桌子。", "explanation": "这里应该用〈消毒水〉。氨味是气味，不能拿来擦桌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "氨味", "is_correct": true, "explanation": "正确：擦过地以后房间里留下的是气味，即氨味，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：房间里不会留下价格，句意说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是可以留在房间里的东西，句意说不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「留下」后面接痕迹、气味，不接体重。"}], "explanations": {"氨味": "正确：擦过地以后房间里留下的是气味，即氨味，符合句意。", "价格": "语义：房间里不会留下价格，句意说不通。", "年龄": "语义：年龄不是可以留在房间里的东西，句意说不通。", "体重": "搭配：「留下」后面接痕迹、气味，不接体重。"}, "sentence_index": 6, "correct_answer": "氨味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布料的氨味很鲜艳。", "explanation": "这里应该用〈色彩〉。氨味是气味，不能形容布料颜色鲜艳，布料的颜色要说色彩。"}, {"text": "厨房里飘来一阵氨味，香得人直流口水。", "explanation": "这里应该用〈饭香〉。氨味刺鼻，不是香味，不能说香得人直流口水。"}, {"text": "院子里的氨味让人心情舒畅。", "explanation": "这里应该用〈花香〉。氨味刺鼻，不能让人心情舒畅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这瓶药水散发着很浓氨味。", "corrected_sentence": "这瓶药水散发着很浓的氨味。", "error_description": "「很浓」修饰「氨味」，中间要加「的」，应说「很浓的氨味」，不能省略「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厨房的门一开，就闻到一只氨味。", "corrected_sentence": "厨房的门一开，就闻到一股氨味。", "error_description": "量词错误：「氨味」的量词应为「股」，「只」不能用于气味。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cd1bdf2-4ba8-450e-99d6-7776bfbed701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
