INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25764, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "木头做成的。", "primary_collocate": null, "pronunciation": "mù zhì", "ipa": "mu˥˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这是一把木质勺子。", "target_word": "木质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的书桌是木质的。", "target_word": "木质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子喜欢玩木质积木。", "target_word": "木质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "木质楼梯走起来有声音。", "target_word": "木质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个木质衣架很轻，也很便宜。", "target_word": "木质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老房子的木质门窗已经很旧了。", "target_word": "木质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木质筷子洗完以后要擦干。", "target_word": "木质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他送给我一支木质的笔，上面刻着我的名字。", "target_word": "木质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把木质的小船放进了水里。", "target_word": "木质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，木质的房子比石头房子暖和。", "target_word": "木质", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "木質", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西是木头做的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07a53c-a9cf-4bf8-a96d-3c0a8dd8e503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25764, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "木质", "is_correct": true, "explanation": "正确。“木质勺子”指用木头做的勺子，与句意相符。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：“嘹亮”形容声音，不能用来修饰勺子。"}, {"text": "温柔", "is_correct": false, "explanation": "搭配：“温柔”形容人的性情，不能用于勺子。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”形容味道，勺子本身不能是“辣”的。"}], "explanations": {"木质": "正确。“木质勺子”指用木头做的勺子，与句意相符。", "嘹亮": "语义：“嘹亮”形容声音，不能用来修饰勺子。", "温柔": "搭配：“温柔”形容人的性情，不能用于勺子。", "辣": "语义：“辣”形容味道，勺子本身不能是“辣”的。"}, "sentence_index": 0, "correct_answer": "木质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "木质飞得很快。", "explanation": "这里应该用〈飞机〉。飞机能在空中飞行；“木质”只描述木头的性质，不能指能飞的东西。"}, {"text": "他听到好消息很木质。", "explanation": "这里应该用〈开心〉。“木质”只描述材料的性质，不能形容人的心情，这里应说“开心”。"}, {"text": "一个小木质站在桌上。", "explanation": "这里应该用〈木偶〉。“木质”是形容词，修饰名词，不能指“木偶”这样的具体物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木质", "is_correct": true, "explanation": "正确。“木质筷子”指用木头做的筷子，洗完要擦干，符合句意。"}, {"text": "锋利", "is_correct": false, "explanation": "语义：“锋利”形容刀刃等切割工具，筷子不是用来切割的。"}, {"text": "悲伤", "is_correct": false, "explanation": "搭配：“悲伤”形容人的情绪，筷子不能悲伤。"}, {"text": "寂静", "is_correct": false, "explanation": "搭配：“寂静”形容环境或声音，不能用来修饰筷子。"}], "explanations": {"木质": "正确。“木质筷子”指用木头做的筷子，洗完要擦干，符合句意。", "锋利": "语义：“锋利”形容刀刃等切割工具，筷子不是用来切割的。", "悲伤": "搭配：“悲伤”形容人的情绪，筷子不能悲伤。", "寂静": "搭配：“寂静”形容环境或声音，不能用来修饰筷子。"}, "sentence_index": 6, "correct_answer": "木质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "木质停了，我们出去玩吧。", "explanation": "这里应该用〈雨〉。雨会停止；“木质”只指木头的性质，不能指天气现象。"}, {"text": "我的木质很调皮，喜欢抓东西。", "explanation": "这里应该用〈猫〉。猫是会调皮的动物；“木质”只指材料，不能指动物。"}, {"text": "木质很甜，大家一起吃。", "explanation": "这里应该用〈西瓜〉。西瓜有甜味；“木质”只指材料的性质，不能形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个勺子是木质的的。", "corrected_sentence": "这个勺子是木质的。", "error_description": "“的”重复：“木质的”已经带“的”，后面不能再加“的”。正确形式是“这个勺子是木质的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那把的木质扇子很漂亮。", "corrected_sentence": "那把木质扇子很漂亮。", "error_description": "“的”位置错误：“那把”和“木质”之间不能加“的”，应说“那把木质扇子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
