INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25766, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放好或安排。", "primary_collocate": null, "pronunciation": "shè", "ipa": "ʂɤ˥˩", "syllable_count": 1, "sentences": [{"text": "展厅里设了一排展台。", "target_word": "设", "complexity_tier": "T3", "furigana": "zhǎn tīng lǐ shè le yì pái zhǎn tái。", "sentence_source": "generated"}, {"text": "教室里设了五十个座位。", "target_word": "设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在院子里设了一张圆桌。", "target_word": "设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把婚礼的座位设在花园里。", "target_word": "设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台设在广场的中间。", "target_word": "设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "服务员在窗边设了两个座位。", "target_word": "设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把讲台设在教室前面。", "target_word": "设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会场里设了一个签到台。", "target_word": "设", "complexity_tier": "T3", "furigana": "huì chǎng lǐ shè le yí ge qiān dào tái。", "sentence_source": "generated"}, {"text": "主人在客厅里设了茶桌。", "target_word": "设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家把帐篷设在河边。", "target_word": "设", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "设了", "label": "完成体"}, {"form": "设过", "label": "经历体"}, {"form": "設", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把桌椅、座位、碗筷等摆放安排好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 展厅 (Zipf 3.34), 一排 (Zipf 3.62), 展台 (Zipf 3.18)']::text[], '9799c0aa-2ee0-4905-9cb8-472d94641281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25766, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "设", "is_correct": true, "explanation": "正确答案。设（shè）表示把桌椅、座位等摆放安排好，与听到的读音一致。"}, {"text": "色", "is_correct": false, "explanation": "色（sè）与设（shè）声母不同（s 与 sh），声调相同，意思是颜色。"}, {"text": "舍", "is_correct": false, "explanation": "舍（shě）与设（shè）声调不同（第三声与第四声），意思是房屋或舍弃。"}, {"text": "十", "is_correct": false, "explanation": "十（shí）与设（shè）声调不同（第二声与第四声），意思是数字十。"}, {"text": "蛇", "is_correct": false, "explanation": "蛇（shé）与设（shè）声调不同（第二声与第四声），意思是蛇。"}, {"text": "示", "is_correct": false, "explanation": "示（shì）与设（shè）声调相同，都是第四声，仅韵母不同（ì 与 è）；意思是展示、表示。"}], "explanations": {"设": "正确答案。设（shè）表示把桌椅、座位等摆放安排好，与听到的读音一致。", "色": "色（sè）与设（shè）声母不同（s 与 sh），声调相同，意思是颜色。", "舍": "舍（shě）与设（shè）声调不同（第三声与第四声），意思是房屋或舍弃。", "十": "十（shí）与设（shè）声调不同（第二声与第四声），意思是数字十。", "蛇": "蛇（shé）与设（shè）声调不同（第二声与第四声），意思是蛇。", "示": "示（shì）与设（shè）声调相同，都是第四声，仅韵母不同（ì 与 è）；意思是展示、表示。"}, "sentence_index": null, "correct_answer": "设"}, "level_3": {"options": [{"text": "设", "is_correct": true, "explanation": "正确。设表示摆放，此处指在展厅摆好一排展台，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“展台”搭配，展台不能被吃。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指演唱，与摆放展台的意思无关。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能带“展台”作宾语，搭配不当。"}], "explanations": {"设": "正确。设表示摆放，此处指在展厅摆好一排展台，符合句意。", "吃": "搭配：“吃”不能与“展台”搭配，展台不能被吃。", "唱": "语义：“唱”指演唱，与摆放展台的意思无关。", "咬": "搭配：“咬”不能带“展台”作宾语，搭配不当。"}, "sentence_index": 0, "correct_answer": "设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把饺子设在盘子里。", "explanation": "这里应该用〈放〉。设多用于摆放桌椅、座位，放饺子要用〈放〉。"}, {"text": "床底下设着一堆玩具。", "explanation": "这里应该用〈堆〉。设用于摆放桌椅、座位，堆放玩具要用〈堆〉。"}, {"text": "墙上设了一幅画，很好看。", "explanation": "这里应该用〈挂〉。设用于摆放桌椅、座位，挂画要用〈挂〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25766, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "设", "is_correct": true, "explanation": "正确答案。设（shè）表示把桌椅、座位等摆放安排好，与听到的读音一致。"}, {"text": "事", "is_correct": false, "explanation": "事（shì）与设（shè）声调相同，都是第四声，仅韵母不同（ì 与 è）；意思是事情。"}, {"text": "是", "is_correct": false, "explanation": "是（shì）与设（shè）声调相同，都是第四声，仅韵母不同（ì 与 è）；意思是对、是的。"}, {"text": "涩", "is_correct": false, "explanation": "涩（sè）与设（shè）声母不同（s 与 sh），声调相同，意思是不光滑、难懂。"}, {"text": "奢", "is_correct": false, "explanation": "奢（shē）与设（shè）声调不同（第一声与第四声），意思是奢侈。"}], "explanations": {"设": "正确答案。设（shè）表示把桌椅、座位等摆放安排好，与听到的读音一致。", "事": "事（shì）与设（shè）声调相同，都是第四声，仅韵母不同（ì 与 è）；意思是事情。", "是": "是（shì）与设（shè）声调相同，都是第四声，仅韵母不同（ì 与 è）；意思是对、是的。", "涩": "涩（sè）与设（shè）声母不同（s 与 sh），声调相同，意思是不光滑、难懂。", "奢": "奢（shē）与设（shè）声调不同（第一声与第四声），意思是奢侈。"}, "sentence_index": null, "correct_answer": "设"}, "level_3": {"options": [{"text": "设", "is_correct": true, "explanation": "正确。设表示摆放，讲台设在教室前面，符合句意。"}, {"text": "吻", "is_correct": false, "explanation": "搭配：“吻”不能带“讲台”作宾语，搭配不当。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指烹饪，与摆放讲台的意思无关。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带宾语“讲台”。"}], "explanations": {"设": "正确。设表示摆放，讲台设在教室前面，符合句意。", "吻": "搭配：“吻”不能带“讲台”作宾语，搭配不当。", "煮": "语义：“煮”指烹饪，与摆放讲台的意思无关。", "笑": "配价：“笑”是不及物动词，不能带宾语“讲台”。"}, "sentence_index": 6, "correct_answer": "设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把行李设在车顶上。", "explanation": "这里应该用〈捆〉。设用于摆放桌椅、座位，捆行李要用〈捆〉。"}, {"text": "篮子里设了几根香蕉，很新鲜。", "explanation": "这里应该用〈装〉。设用于摆放桌椅、座位，装香蕉要用〈装〉。"}, {"text": "床上设了一层被子。", "explanation": "这里应该用〈铺〉。设用于摆放桌椅、座位，铺被子要用〈铺〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "饭店在大厅了设几张圆桌。", "corrected_sentence": "饭店在大厅设了几张圆桌。", "error_description": "“了”的位置错误：完成体“了”应紧跟动词“设”，应说“设了”，不能放在动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "礼堂里设了着几排座位。", "corrected_sentence": "礼堂里设着几排座位。", "error_description": "“了”与“着”不能同用：表示持续状态时，“设”后只用“着”，应说“设着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
