INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25772, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情中最重要的部分。", "primary_collocate": null, "pronunciation": "sān yào sù", "ipa": "san˥ jɑʊ˥˩ su˥˩", "syllable_count": 3, "sentences": [{"text": "做菜的三要素是火候、盐和新鲜的菜。", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演讲有三要素：内容、声音和表情。", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买房子看三要素：地段、价格和环境。", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的比赛取胜的三要素是速度、准确和稳定。", "target_word": "三要素", "complexity_tier": "T3", "furigana": "tā men de bǐ sài qǔ shèng de sān yào sù shì sù dù zhǔn què hé wěn dìng", "sentence_source": "generated"}, {"text": "老板说，开店的三要素是人、货和地方。", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写作文的三要素你记住了吗？", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学好英语的三要素是兴趣、方法和坚持。", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把成功的三要素写在笔记本的第一页上。", "target_word": "三要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看电影的三要素：故事、演员和音乐。", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏的三要素是玩法、画面和声音。", "target_word": "三要素", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一件事里最重要的三个部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9d26fe1-76de-4d72-b2de-845fecb9db9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "三要素", "is_correct": true, "explanation": "“三要素”指事情中最重要的部分，与“火候、盐和新鲜的菜”三项相合，可以放入空缺。"}, {"text": "三步骤", "is_correct": false, "explanation": "语义：“火候、盐和新鲜的菜”是并列的食材和要点，不是先后进行的步骤。"}, {"text": "三工具", "is_correct": false, "explanation": "语义：火候不是工具，“三工具”与列出的内容不相符。"}, {"text": "三大件", "is_correct": false, "explanation": "搭配：“三大件”指大型成套物品，盐和火候不属于这一类，不能这样搭配。"}], "explanations": {"三要素": "“三要素”指事情中最重要的部分，与“火候、盐和新鲜的菜”三项相合，可以放入空缺。", "三步骤": "语义：“火候、盐和新鲜的菜”是并列的食材和要点，不是先后进行的步骤。", "三工具": "语义：火候不是工具，“三工具”与列出的内容不相符。", "三大件": "搭配：“三大件”指大型成套物品，盐和火候不属于这一类，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "三要素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的三要素考了九十分。", "explanation": "这里应该用〈成绩〉。“三要素”指事情中最重要的部分，不能作为考试成绩的主语。"}, {"text": "这件衣服的三要素是中号。", "explanation": "这里应该用〈尺寸〉。“三要素”指最重要的部分，不指衣服的大小。"}, {"text": "他把三要素借给了邻居。", "explanation": "这里把“三要素”当成了可以借出的东西。“三要素”是抽象概念，不是具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三要素", "is_correct": true, "explanation": "“三要素”指事情中最重要的部分，“兴趣、方法和坚持”正是学好英语的关键。"}, {"text": "三色", "is_correct": false, "explanation": "语义：“三色”指三种颜色，“兴趣、方法和坚持”不是颜色。"}, {"text": "三头肌", "is_correct": false, "explanation": "语义：“三头肌”是肌肉名称，不能指学习的关键要素，句意不通。"}, {"text": "三标签", "is_correct": false, "explanation": "语义：“三标签”指贴上去的标记，与学习的关键因素不是同一概念。"}], "explanations": {"三要素": "“三要素”指事情中最重要的部分，“兴趣、方法和坚持”正是学好英语的关键。", "三色": "语义：“三色”指三种颜色，“兴趣、方法和坚持”不是颜色。", "三头肌": "语义：“三头肌”是肌肉名称，不能指学习的关键要素，句意不通。", "三标签": "语义：“三标签”指贴上去的标记，与学习的关键因素不是同一概念。"}, "sentence_index": 6, "correct_answer": "三要素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这三要素在晚上唱起了歌。", "explanation": "这里把“三要素”当成了会唱歌的主体。“三要素”是抽象概念，不能做动作。"}, {"text": "我们把三要素涂成了红色。", "explanation": "这里用的是具体物体的意思。“三要素”指事情中最重要的部分，不是可以涂色的东西。"}, {"text": "他的三要素有一米八高。", "explanation": "这里用来形容身高，与“三要素”指最重要的部分不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "做饭时要抓住一个三要素。", "corrected_sentence": "做饭时要抓住三要素。", "error_description": "多加了“一个”。“三要素”本身已含数词“三”，前面不能再加表示数量的“一个”，应说“做饭时要抓住三要素”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师讲了学习英语的三要素们。", "corrected_sentence": "老师讲了学习英语的三要素。", "error_description": "错误在于“们”。“们”只附在指人的名词后面，“三要素”是抽象名词，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
