INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25774, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "温度和湿度放在一起说。", "primary_collocate": null, "pronunciation": "wēn shī dù", "ipa": "wən˥ ʂɨ˥ tu˥˩", "syllable_count": 3, "sentences": [{"text": "天气预报会告诉我们明天的温湿度。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室要记录每天的温湿度。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "葡萄酒需要放在温湿度稳定的地方。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的温湿度和城市很不一样。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空调可以把房间的温湿度调到合适的范围。", "target_word": "温湿度", "complexity_tier": "T3", "furigana": "wēn shī dù", "sentence_source": "generated"}, {"text": "这种植物对温湿度的变化很敏感。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天的温湿度正好，很适合出去玩。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先看一下机房的温湿度再进去。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "茶叶放久了，温湿度不对就会发霉。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "温湿度太高的时候，衣服很难干。", "target_word": "温湿度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "温湿度计", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把温度和湿度合在一起说的日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9d26fe1-76de-4d72-b2de-845fecb9db9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "票价", "is_correct": false, "explanation": "语义：天气预报不报告票价，两者无关。"}, {"text": "血压", "is_correct": false, "explanation": "语义：血压是人的指标，不是天气预报的内容。"}, {"text": "温湿度", "is_correct": true, "explanation": "正确：天气预报会告诉我们明天的温湿度，符合语境。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“天气预报会告诉我们”后不接“明天的生日”。"}], "explanations": {"票价": "语义：天气预报不报告票价，两者无关。", "血压": "语义：血压是人的指标，不是天气预报的内容。", "温湿度": "正确：天气预报会告诉我们明天的温湿度，符合语境。", "生日": "搭配：“天气预报会告诉我们”后不接“明天的生日”。"}, "sentence_index": 0, "correct_answer": "温湿度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的温湿度是三十度，很热。", "explanation": "这里应该用〈气温〉。温湿度是温度与湿度的合称，不能单指一个温度数值。"}, {"text": "他发烧了，温湿度很高。", "explanation": "这里应该用〈体温〉。温湿度指环境的温度与湿度，不用来说人的体温。"}, {"text": "这间屋子的温湿度是百分之六十，衣服一直干不了。", "explanation": "这里应该用〈湿度〉。温湿度是合称，不单指湿度的数值，不能说“是百分之六十”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业不是天气，“春天的作业正好”不合语境。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄与天气无关，“正好，适合出去玩”无法解释。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“春天的手机正好”不成立，“正好”不搭配手机。"}, {"text": "温湿度", "is_correct": true, "explanation": "正确：春天的温湿度正好，很适合出去玩，符合语境。"}], "explanations": {"作业": "语义：作业不是天气，“春天的作业正好”不合语境。", "年龄": "语义：年龄与天气无关，“正好，适合出去玩”无法解释。", "手机": "搭配：“春天的手机正好”不成立，“正好”不搭配手机。", "温湿度": "正确：春天的温湿度正好，很适合出去玩，符合语境。"}, "sentence_index": 6, "correct_answer": "温湿度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里的温湿度是二十五度，很舒服。", "explanation": "这里应该用〈室温〉。温湿度是合称，不单指室内温度。"}, {"text": "我把温湿度当成一件衣服穿在身上。", "explanation": "温湿度指环境的温度与湿度，不是衣物，此处不能当成实物。"}, {"text": "这杯茶的温湿度很香。", "explanation": "这里应该用〈味道〉。温湿度指温度与湿度，不能用来形容茶的香气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车间里挂着一个温湿度。", "corrected_sentence": "车间里挂着一个温湿度计。", "error_description": "应为“温湿度计”。“温湿度”是温度与湿度的合称，不是仪器，挂的仪器要说“温湿度计”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器能控制室内的温湿度的。", "corrected_sentence": "这台机器能控制室内的温湿度。", "error_description": "句末多出“的”。“室内的温湿度”后面不能再加“的”，否则名词短语无中心语，应去掉句末的“的”，说“室内的温湿度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94d61c99-a610-44f4-a28d-c3fb91d53a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25776, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散", "is_correct": true, "explanation": "正确：“散”与“成团”相对，指人群分散、散开。"}, {"text": "唱歌", "is_correct": false, "explanation": "不是反义词：“唱歌”指发声演唱，与“成团”没有相对关系。"}, {"text": "写字", "is_correct": false, "explanation": "不是反义词：“写字”指书写文字，与“成团”没有相对关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "不是反义词：“吃饭”指进餐，与“成团”没有相对关系。"}], "correct_answer": "散", "explanations": {"散": "正确：“散”与“成团”相对，指人群分散、散开。", "唱歌": "不是反义词：“唱歌”指发声演唱，与“成团”没有相对关系。", "写字": "不是反义词：“写字”指书写文字，与“成团”没有相对关系。", "吃饭": "不是反义词：“吃饭”指进餐，与“成团”没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25776, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散", "is_correct": true, "explanation": "正确：“散”与“成团”相对，指人群分散、散开。"}, {"text": "跑步", "is_correct": false, "explanation": "不是反义词：“跑步”指快速移动的运动，与“成团”没有相对关系。"}, {"text": "收拾", "is_correct": false, "explanation": "不是反义词：“收拾”指整理、清理，与“成团”没有相对关系。"}, {"text": "游泳", "is_correct": false, "explanation": "不是反义词：“游泳”指在水中运动，与“成团”没有相对关系。"}], "correct_answer": "散", "explanations": {"散": "正确：“散”与“成团”相对，指人群分散、散开。", "跑步": "不是反义词：“跑步”指快速移动的运动，与“成团”没有相对关系。", "收拾": "不是反义词：“收拾”指整理、清理，与“成团”没有相对关系。", "游泳": "不是反义词：“游泳”指在水中运动，与“成团”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25776, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "很多人聚在一起变成一团或一群。", "primary_collocate": null, "pronunciation": "chéng tuán", "ipa": "ʈʂʰɤŋ˧˥ tʰuan˧˥", "syllable_count": 2, "sentences": [{"text": "下课铃一响，同学们很快就成团了。", "target_word": "成团", "complexity_tier": "T3", "furigana": "xià kè líng yì xiǎng, tóng xué men hěn kuài jiù chéng tuán le.", "sentence_source": "generated"}, {"text": "晚上，许多邻居在路灯下很快就成团，议论起了新来的住户。", "target_word": "成团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客一到，景点门口就成团了。", "target_word": "成团", "complexity_tier": "T3", "furigana": "yóu kè yí dào, jǐng diǎn mén kǒu jiù chéng tuán le.", "sentence_source": "generated"}, {"text": "十个人才能成团，我们还差两个人。", "target_word": "成团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报名的人够了，旅行团明天就能成团。", "target_word": "成团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "粉丝们在门口成团，想看明星一眼。", "target_word": "成团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一下雨，大家就成团了，都挤到屋檐下。", "target_word": "成团", "complexity_tier": "T3", "furigana": "yí xià yǔ, dà jiā jiù chéng tuán le, dōu jǐ dào wū yán xià.", "sentence_source": "generated"}, {"text": "孩子们在操场上一聚就成团，玩起了游戏。", "target_word": "成团", "complexity_tier": "T3", "furigana": "hái zi men zài cāo chǎng shàng yí jù jiù chéng tuán, wán qǐ le yóu xì.", "sentence_source": "generated"}, {"text": "买菜的人一多，摊位前就成团了。", "target_word": "成团", "complexity_tier": "T3", "furigana": "mǎi cài de rén yì duō, tān wèi qián jiù chéng tuán le.", "sentence_source": "generated"}, {"text": "外国朋友们在机场门口已经成团了。", "target_word": "成团", "complexity_tier": "T3", "furigana": "wài guó péng you men zài jī chǎng mén kǒu yǐ jīng chéng tuán le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "成团了", "label": "完成体"}, {"form": "成團", "label": "繁体"}], "register": "中性", "sense_fingerprint": "许多人聚拢在一起形成一群或一个团队", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9799c0aa-2ee0-4905-9cb8-472d94641281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成团", "is_correct": true, "explanation": "正确：“很快就成团了”指同学们下课后聚在一起，符合句意。"}, {"text": "上课", "is_correct": false, "explanation": "语义：“下课铃一响”之后不会“上课”，与“下课”的语境冲突。"}, {"text": "吵醒", "is_correct": false, "explanation": "配价：“吵醒”需要宾语，“同学们很快就吵醒了”不成句。"}, {"text": "逃课", "is_correct": false, "explanation": "语义：下课铃响说明课已结束，不存在“逃课”，与语境矛盾。"}], "explanations": {"成团": "正确：“很快就成团了”指同学们下课后聚在一起，符合句意。", "上课": "语义：“下课铃一响”之后不会“上课”，与“下课”的语境冲突。", "吵醒": "配价：“吵醒”需要宾语，“同学们很快就吵醒了”不成句。", "逃课": "语义：下课铃响说明课已结束，不存在“逃课”，与语境矛盾。"}, "sentence_index": 0, "correct_answer": "成团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵们在操场上成团前进。", "explanation": "这里应该用〈结队〉。结队指排成队伍前进，成团指松散的人聚在一起，不能说“成团前进”。"}, {"text": "我一个人在路灯下，很快就成团了。", "explanation": "这里误用了〈成团〉：它指很多人聚在一起，不能用于单独一个人。"}, {"text": "一家人成团吃年夜饭。", "explanation": "这里应该用〈团聚〉。团聚指家人相聚在一起，“成团”强调人群组成团体，不用于家人团圆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成团", "is_correct": true, "explanation": "正确：“一下雨，大家就成团了”指人群聚在一起，与“都挤到屋檐下”相符。"}, {"text": "分开", "is_correct": false, "explanation": "语义：句中说“都挤到屋檐下”，“分开”与聚在一起的情形相反。"}, {"text": "晒太阳", "is_correct": false, "explanation": "语义：“一下雨”说明天气阴湿，晒太阳与语境矛盾。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”指收取成熟的庄稼，不用于形容人群在雨中的动作。"}], "explanations": {"成团": "正确：“一下雨，大家就成团了”指人群聚在一起，与“都挤到屋檐下”相符。", "分开": "语义：句中说“都挤到屋檐下”，“分开”与聚在一起的情形相反。", "晒太阳": "语义：“一下雨”说明天气阴湿，晒太阳与语境矛盾。", "收割": "搭配：“收割”指收取成熟的庄稼，不用于形容人群在雨中的动作。"}, "sentence_index": 6, "correct_answer": "成团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一个人在机场门口已经成团了。", "explanation": "这里误用了〈成团〉：它指很多人聚在一起，不能用于单独的个体。"}, {"text": "这块石头在桌子上已经成团了。", "explanation": "这里误用了〈成团〉：它指很多人聚在一起，不能用于单个固体。"}, {"text": "这盏灯泡在灯座里已经成团了。", "explanation": "这里误用了〈成团〉：它指很多人聚在一起，不能用于单个器件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们放学以后，很快就成团着。", "corrected_sentence": "孩子们放学以后，很快就成团了。", "error_description": "体貌错误：“很快就”表示变化已经完成，应用完成的“了”，持续的“着”不能用在这里，应说“成团了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "游客们很快就把成团了。", "corrected_sentence": "游客们很快就成团了。", "error_description": "“把”不能与不及物动词“成团”搭配：“成团”不带宾语，应说“游客们很快就成团了”，不能说“把成团”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c00ba3b-ab45-44e6-b20e-26758768f25c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
